INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20262, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "消失", "is_correct": true, "explanation": "反义：“出现”指从看不见到看得见，“消失”指从看得见到看不见。"}, {"text": "到达", "is_correct": false, "explanation": "“到达”指抵达某地，与“出现”没有反义关系。"}, {"text": "保持", "is_correct": false, "explanation": "“保持”指维持原样，与“出现”没有反义关系。"}, {"text": "完成", "is_correct": false, "explanation": "“完成”指做好某件事，与“出现”没有反义关系。"}], "correct_answer": "消失", "explanations": {"消失": "反义：“出现”指从看不见到看得见，“消失”指从看得见到看不见。", "到达": "“到达”指抵达某地，与“出现”没有反义关系。", "保持": "“保持”指维持原样，与“出现”没有反义关系。", "完成": "“完成”指做好某件事，与“出现”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20262, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "消失", "is_correct": true, "explanation": "反义：“出现”指从看不见到看得见，“消失”指从看得见到看不见。"}, {"text": "进入", "is_correct": false, "explanation": "“进入”指从外面到里面，与“出现”没有反义关系。"}, {"text": "保留", "is_correct": false, "explanation": "“保留”指留存不丢，与“出现”没有反义关系。"}, {"text": "结束", "is_correct": false, "explanation": "“结束”指事情到了终点，与“出现”没有反义关系。"}], "correct_answer": "消失", "explanations": {"消失": "反义：“出现”指从看不见到看得见，“消失”指从看得见到看不见。", "进入": "“进入”指从外面到里面，与“出现”没有反义关系。", "保留": "“保留”指留存不丢，与“出现”没有反义关系。", "结束": "“结束”指事情到了终点，与“出现”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20262, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "人或事物从看不见到看得见。", "primary_collocate": null, "pronunciation": "chū xiàn", "ipa": "ʈʂʰu⁵⁵ ɕjɛn⁵¹", "syllable_count": 2, "sentences": [{"text": "天上出现了一朵大云。", "target_word": "出现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳出现了，天气很好。", "target_word": "出现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口突然出现一只小狗。", "target_word": "出现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一出现，大家都笑了。", "target_word": "出现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以前从没出现在这张照片里。", "target_word": "出现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的电脑上出现了一个红点。", "target_word": "出现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后天上出现了彩虹。", "target_word": "出现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么一直不出现？", "target_word": "出现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上出现了很多车。", "target_word": "出现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她出现在门口，手里拿着花。", "target_word": "出现", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出现了", "label": "体标"}, {"form": "出现过", "label": "体标"}, {"form": "出現", "label": "繁体"}], "register": "中性", "sense_fingerprint": "从无到有地显露出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f67254c-2b72-48f7-a62f-6cc95d11eae2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20262, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "出现", "is_correct": true, "explanation": "正确：出现 chū xiàn，指东西从看不见到看得见。"}, {"text": "曲线", "is_correct": false, "explanation": "第一音节 qū 与 chū 声母不同（q 与 ch），意思是曲线。"}, {"text": "出险", "is_correct": false, "explanation": "第二音节 xiǎn（第三声）与 xiàn（第四声）声调不同，意思是发生保险事故。"}, {"text": "粗线", "is_correct": false, "explanation": "第一音节 cū 与 chū 声母不同（c 与 ch），意思是粗的线条。"}], "explanations": {"出现": "正确：出现 chū xiàn，指东西从看不见到看得见。", "曲线": "第一音节 qū 与 chū 声母不同（q 与 ch），意思是曲线。", "出险": "第二音节 xiǎn（第三声）与 xiàn（第四声）声调不同，意思是发生保险事故。", "粗线": "第一音节 cū 与 chū 声母不同（c 与 ch），意思是粗的线条。"}, "sentence_index": null, "correct_answer": "出现"}, "level_3": {"options": [{"text": "出现", "is_correct": true, "explanation": "正确：天上出现了一朵云，符合“从看不见到看得见”。"}, {"text": "写", "is_correct": false, "explanation": "语义：写是书写文字的动作，云不能被“写”出来。"}, {"text": "修", "is_correct": false, "explanation": "语义：修指修理或建造，不能用来说天上的云。"}, {"text": "发生", "is_correct": false, "explanation": "搭配：“发生”多用于事件，不说“发生了一朵云”。"}], "explanations": {"出现": "正确：天上出现了一朵云，符合“从看不见到看得见”。", "写": "语义：写是书写文字的动作，云不能被“写”出来。", "修": "语义：修指修理或建造，不能用来说天上的云。", "发生": "搭配：“发生”多用于事件，不说“发生了一朵云”。"}, "sentence_index": 0, "correct_answer": "出现"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他明天出现会议。", "explanation": "这里应该用〈出席〉。出现是事物显露，不能带“会议”作宾语，参加会议要说“出席”。"}, {"text": "哥伦布出现了新大陆。", "explanation": "这里应该用〈发现〉。出现不能带“新大陆”作宾语，找到新地方要说“发现”。"}, {"text": "我们明天出现去北京。", "explanation": "这里应该用〈出发〉。出现不能和“去北京”这类表示移动的短语搭配，动身要说“出发”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20262, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出现", "is_correct": true, "explanation": "正确：雨后天上出现彩虹，符合“从看不见到看得见”。"}, {"text": "下", "is_correct": false, "explanation": "搭配：雨可以说“下”，但不说“下彩虹”。"}, {"text": "收", "is_correct": false, "explanation": "语义：收是收起、收拾，彩虹不能被收起来。"}, {"text": "落", "is_correct": false, "explanation": "搭配：“落”多指东西向下掉，彩虹不说“落”。"}], "explanations": {"出现": "正确：雨后天上出现彩虹，符合“从看不见到看得见”。", "下": "搭配：雨可以说“下”，但不说“下彩虹”。", "收": "语义：收是收起、收拾，彩虹不能被收起来。", "落": "搭配：“落”多指东西向下掉，彩虹不说“落”。"}, "sentence_index": 6, "correct_answer": "出现"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请出现你的身份证。", "explanation": "这里应该用〈出示〉。出现表示显露，不表示拿出证件给别人看。"}, {"text": "他出现了这座大楼。", "explanation": "这里应该用〈设计〉。出现表示显露，不能带“大楼”作宾语，设计建筑要说“设计”。"}, {"text": "司机每天早上出现汽车。", "explanation": "这里应该用〈发动〉。出现不能带“汽车”作宾语，启动车辆要说“发动”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20262, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他突然出现门口。", "corrected_sentence": "他突然出现在门口。", "error_description": "介词错误：“出现”后表示地点时要加介词“在”，应说“出现在门口”，不能说“出现门口”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20262, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种鸟在这里出现过很多次过。", "corrected_sentence": "这种鸟在这里出现过很多次。", "error_description": "动态助词重复：“过”只用一次，紧跟动词，说“出现过很多次”，句末不能再加“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
