INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20266, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "不再表示从今以后不这样做或不再发生。", "primary_collocate": null, "pronunciation": "bù zài", "ipa": "pu˥˩ tsaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他不再抽烟。", "target_word": "不再", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我不再担心考试了。", "target_word": "不再", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子长大了，不再需要妈妈送他上学。", "target_word": "不再", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气暖和以后，我们不再穿厚衣服。", "target_word": "不再", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他搬到北京以后，不再住在这里。", "target_word": "不再", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我已经不再生他的气了。", "target_word": "不再", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店太贵，我们以后不再来了。", "target_word": "不再", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说过的话，我不再相信。", "target_word": "不再", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病好了以后，奶奶不再每天吃药。", "target_word": "不再", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她决定不再给那个朋友打电话。", "target_word": "不再", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，表示以前有的动作或状态从现在起不继续、不重复", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e424837-2e8c-4c86-b782-2097d65b46d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20266, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不再", "is_correct": true, "explanation": "正确：“不再”表示以前抽烟、现在停止，与句意相符。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”修饰形容词或心理动词，不修饰“抽烟”这类动作，“他很抽烟”不通。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”同样不修饰“抽烟”这类动作，不能说“非常抽烟”。"}, {"text": "太", "is_correct": false, "explanation": "语义：“太”表示程度过分，“抽烟”是一个动作而不是程度，“他太抽烟”不通。"}], "explanations": {"不再": "正确：“不再”表示以前抽烟、现在停止，与句意相符。", "很": "搭配：“很”修饰形容词或心理动词，不修饰“抽烟”这类动作，“他很抽烟”不通。", "非常": "搭配：“非常”同样不修饰“抽烟”这类动作，不能说“非常抽烟”。", "太": "语义：“太”表示程度过分，“抽烟”是一个动作而不是程度，“他太抽烟”不通。"}, "sentence_index": 0, "correct_answer": "不再"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从小到大不再抽烟。", "explanation": "这里应该用〈从来不〉。“不再”表示以前有、现在停止，他从小到大都没抽过，应说“从来不”。"}, {"text": "我们第一次见面，他不再笑。", "explanation": "这里应该用〈一直没有〉。“不再”预设他以前笑过，而第一次见面时他一直没有笑，应说“一直没有笑”。"}, {"text": "我以前不再学过汉语，这是第一次学。", "explanation": "这里应该用〈没有〉。“不再”表示以前有、以后停止，不能和表示经历的“过”一起说过去从没做的事，应说“我以前没有学过汉语”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20266, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不再", "is_correct": true, "explanation": "正确：“不再”表示以后不再去这家店，与“太贵”的原因相符。"}, {"text": "更", "is_correct": false, "explanation": "搭配：“更”修饰形容词或其他副词，不修饰“来”，不能说“以后更来了”。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去有过的经历，与“以后”的将来时间矛盾，句子说不通。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示动作已经完成，与“以后”的将来时间矛盾。"}], "explanations": {"不再": "正确：“不再”表示以后不再去这家店，与“太贵”的原因相符。", "更": "搭配：“更”修饰形容词或其他副词，不修饰“来”，不能说“以后更来了”。", "曾经": "语义：“曾经”指过去有过的经历，与“以后”的将来时间矛盾，句子说不通。", "已经": "语义：“已经”表示动作已经完成，与“以后”的将来时间矛盾。"}, "sentence_index": 6, "correct_answer": "不再"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她昨天不再给那个朋友打过电话。", "explanation": "这里应该用〈没〉。“不再”表示从此以后停止，不能和“过”一起叙述昨天的情况，应说“她昨天没给那个朋友打过电话”。"}, {"text": "她决定不再给那个朋友打电话，所以每天都给他打。", "explanation": "这里应该用〈继续〉。“不再”表示停止，与后面的“每天都给他打”矛盾，应说“她决定继续给那个朋友打电话”。"}, {"text": "她刚认识那个朋友，就不再给他打电话了。", "explanation": "这里应该用〈第一次〉。“不再”预设以前打过电话，她刚认识那个朋友，这是第一次打，应说“她第一次给他打电话”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20266, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "现在他不再了哭。", "corrected_sentence": "现在他不再哭了。", "error_description": "语序错误：“了”表示完成，要放在动词“哭”的后面，写成“不再了哭”不通，应改为“不再哭了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20266, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她不在给他写信了。", "corrected_sentence": "她不再给他写信了。", "error_description": "用字错误：“不在”表示人不在某处，这里要说以后不继续写信，应该用“不再”，写作“她不再给他写信了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20268, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "少量", "is_correct": true, "explanation": "正确：“少量”与“大量”是一对反义词，都指数量。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”形容明白、不模糊，与“大量”的数量义无关。"}, {"text": "迅速", "is_correct": false, "explanation": "“迅速”形容速度快，与“大量”没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”形容没有污垢，不是“大量”的反义词。"}], "correct_answer": "少量", "explanations": {"少量": "正确：“少量”与“大量”是一对反义词，都指数量。", "清楚": "“清楚”形容明白、不模糊，与“大量”的数量义无关。", "迅速": "“迅速”形容速度快，与“大量”没有反义关系。", "干净": "“干净”形容没有污垢，不是“大量”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20268, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "少量", "is_correct": true, "explanation": "正确：“少量”与“大量”是一对反义词，都指数量。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线充足或颜色鲜明，与“大量”的数量义无关。"}, {"text": "柔软", "is_correct": false, "explanation": "“柔软”形容质地不硬，与“大量”没有反义关系。"}, {"text": "简单", "is_correct": false, "explanation": "“简单”形容不复杂，不是“大量”的反义词。"}], "correct_answer": "少量", "explanations": {"少量": "正确：“少量”与“大量”是一对反义词，都指数量。", "明亮": "“明亮”形容光线充足或颜色鲜明，与“大量”的数量义无关。", "柔软": "“柔软”形容质地不硬，与“大量”没有反义关系。", "简单": "“简单”形容不复杂，不是“大量”的反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20268, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示数量很多。", "primary_collocate": null, "pronunciation": "dà liàng", "ipa": "tɑ˥˩ ljɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他每天喝大量的水，身体很好。", "target_word": "大量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个商店卖大量便宜的衣服。", "target_word": "大量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了写作业，我找了大量资料。", "target_word": "大量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，路上有大量的水。", "target_word": "大量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在网上看了大量的视频。", "target_word": "大量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天，公园里来了大量的游客。", "target_word": "大量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给了我们大量的作业。", "target_word": "大量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司需要大量的工人。", "target_word": "大量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了大量的书，房间里都放不下了。", "target_word": "大量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种菜里有大量的维生素。", "target_word": "大量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大量地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "数量很多，常修饰名词或动词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b8f789-626d-40d7-a308-633398a91259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20268, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大量", "is_correct": true, "explanation": "正确：大量（dà liàng），表示数量很多。"}, {"text": "大梁", "is_correct": false, "explanation": "大梁（dà liáng）与大量（dà liàng）第二个音节声调不同（阳平与去声），意思是房屋或桥梁上的粗横木。"}, {"text": "打量", "is_correct": false, "explanation": "打量（dǎ liang）与大量（dà liàng）两个音节的声调都不同，意思是上下仔细看。"}, {"text": "大浪", "is_correct": false, "explanation": "大浪（dà làng）与大量（dà liàng）第二个音节去掉了韵头 i，意思是很大的波浪。"}], "explanations": {"大量": "正确：大量（dà liàng），表示数量很多。", "大梁": "大梁（dà liáng）与大量（dà liàng）第二个音节声调不同（阳平与去声），意思是房屋或桥梁上的粗横木。", "打量": "打量（dǎ liang）与大量（dà liàng）两个音节的声调都不同，意思是上下仔细看。", "大浪": "大浪（dà làng）与大量（dà liàng）第二个音节去掉了韵头 i，意思是很大的波浪。"}, "sentence_index": null, "correct_answer": "大量"}, "level_3": {"options": [{"text": "大量", "is_correct": true, "explanation": "正确：“大量”表示数量多，修饰“水”，与“每天喝”和“身体很好”相合。"}, {"text": "脏", "is_correct": false, "explanation": "语义：“脏”指不干净，与“身体很好”矛盾，喝脏水不利于健康。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌，不能用来说水的质量。"}, {"text": "年轻", "is_correct": false, "explanation": "搭配：“年轻”只用于人或生物，不能修饰“水”。"}], "explanations": {"大量": "正确：“大量”表示数量多，修饰“水”，与“每天喝”和“身体很好”相合。", "脏": "语义：“脏”指不干净，与“身体很好”矛盾，喝脏水不利于健康。", "漂亮": "体貌：“漂亮”形容外貌，不能用来说水的质量。", "年轻": "搭配：“年轻”只用于人或生物，不能修饰“水”。"}, "sentence_index": 0, "correct_answer": "大量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对这件事大量地感到高兴。", "explanation": "这里应该用〈非常〉。“大量”只说数量多，不能用来表示感受的程度，“非常高兴”才对。"}, {"text": "他把房间打扫得大量地干净。", "explanation": "这里应该用〈很〉。“大量”只说数量多，不能修饰“干净”的程度，“打扫得很干净”才对。"}, {"text": "这个班级有大量的三十个学生。", "explanation": "这里的人数是确定的，应该去掉〈大量〉，直接说“三十个学生”。“大量”只表示数量多而不确定，不能与确切数字连用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20268, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大量", "is_correct": true, "explanation": "正确：“大量”表示数量多，修饰“作业”，与句意相合。"}, {"text": "冰冷", "is_correct": false, "explanation": "语义：作业没有温度，不能说冰冷。"}, {"text": "悲伤", "is_correct": false, "explanation": "搭配：“悲伤”形容人的情绪，不能用来修饰作业。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的形体，不能用来形容作业的数量。"}], "explanations": {"大量": "正确：“大量”表示数量多，修饰“作业”，与句意相合。", "冰冷": "语义：作业没有温度，不能说冰冷。", "悲伤": "搭配：“悲伤”形容人的情绪，不能用来修饰作业。", "高大": "体貌：“高大”形容人或物的形体，不能用来形容作业的数量。"}, "sentence_index": 6, "correct_answer": "大量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只小猫有大量的个头，像一只小老虎。", "explanation": "这里应该用〈大〉。“大量”只表示数量多，不能用来说个头的大小，说个子大要用〈大〉。"}, {"text": "他大量地摔了一跤，疼得站不起来。", "explanation": "这里应该用〈重〉。“大量地”表示数量多或次数多，不能修饰一次跌倒；跌得厉害要用〈重〉。"}, {"text": "他的脚步大量地轻，怕吵醒我。", "explanation": "这里应该用〈很〉，说“他的脚步很轻”。“大量”只说数量多，不能表示“轻”的程度，程度要用〈很〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20268, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司进了大量地货。", "corrected_sentence": "公司进了大量的货。", "error_description": "错误：修饰名词“货”的成分用了“地”。“地”用于修饰动词，修饰名词要用“的”。正确应为“大量的货”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20268, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校招了大量地新老师。", "corrected_sentence": "学校招了大量新老师。", "error_description": "错误：“大量”修饰名词“新老师”时用了“地”。“地”用于修饰动词，修饰名词不加“地”，正确应为“大量新老师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20270, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "超过", "is_correct": true, "explanation": "正确。“超过”与“不到”相反，表示超出某个数量，符合“不到二十个人”的反义关系。"}, {"text": "休息", "is_correct": false, "explanation": "与“不到”的任何义项都没有反义关系，“休息”指停止活动。"}, {"text": "喜欢", "is_correct": false, "explanation": "与“不到”的任何义项都没有反义关系，“喜欢”指对人或事物有好感。"}, {"text": "同意", "is_correct": false, "explanation": "与“不到”的任何义项都没有反义关系，“同意”指赞成某种意见。"}], "correct_answer": "超过", "explanations": {"超过": "正确。“超过”与“不到”相反，表示超出某个数量，符合“不到二十个人”的反义关系。", "休息": "与“不到”的任何义项都没有反义关系，“休息”指停止活动。", "喜欢": "与“不到”的任何义项都没有反义关系，“喜欢”指对人或事物有好感。", "同意": "与“不到”的任何义项都没有反义关系，“同意”指赞成某种意见。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20270, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "超过", "is_correct": true, "explanation": "正确。“超过”与“不到”相反，表示超出某个数量，符合“不到一半”的反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "与“不到”的任何义项都没有反义关系，“散步”指慢慢地走着活动身体。"}, {"text": "洗澡", "is_correct": false, "explanation": "与“不到”的任何义项都没有反义关系，“洗澡”指用水清洗身体。"}, {"text": "阅读", "is_correct": false, "explanation": "与“不到”的任何义项都没有反义关系，“阅读”指看书、看文字。"}], "correct_answer": "超过", "explanations": {"超过": "正确。“超过”与“不到”相反，表示超出某个数量，符合“不到一半”的反义关系。", "散步": "与“不到”的任何义项都没有反义关系，“散步”指慢慢地走着活动身体。", "洗澡": "与“不到”的任何义项都没有反义关系，“洗澡”指用水清洗身体。", "阅读": "与“不到”的任何义项都没有反义关系，“阅读”指看书、看文字。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20270, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "没有到达某个数量或程度。", "primary_collocate": null, "pronunciation": "bú dào", "ipa": "pu˧˥ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这个孩子不到五岁。", "target_word": "不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家离学校不到一公里。", "target_word": "不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他等了不到十分钟就走了。", "target_word": "不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里不到二十个人。", "target_word": "不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书不到一百页。", "target_word": "不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不到半年，他就学会了开车。", "target_word": "不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的工资不到五千块。", "target_word": "不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨晚睡了不到三个小时。", "target_word": "不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路不到两公里长。", "target_word": "不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天来的学生不到一半。", "target_word": "不到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "数量或程度还没有达到某个数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f5780da-c6e6-4d29-93fe-0d7e321c3e1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20270, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不到", "is_correct": true, "explanation": "正确。不到 bú dào，表示没有达到某个数量或程度。"}, {"text": "不带", "is_correct": false, "explanation": "dài（第四声）与 dào 韵母不同（ai 与 ao），意思是不携带。"}, {"text": "步道", "is_correct": false, "explanation": "bù（第四声）与 bú（第二声）声调不同，意思是步行的道路。"}, {"text": "不倒", "is_correct": false, "explanation": "dǎo（第三声）与 dào（第四声）声调不同，意思是不倒下。"}, {"text": "不掉", "is_correct": false, "explanation": "diào 比 dào 多了介音 i，韵母不同，意思是不掉落。"}], "explanations": {"不到": "正确。不到 bú dào，表示没有达到某个数量或程度。", "不带": "dài（第四声）与 dào 韵母不同（ai 与 ao），意思是不携带。", "步道": "bù（第四声）与 bú（第二声）声调不同，意思是步行的道路。", "不倒": "dǎo（第三声）与 dào（第四声）声调不同，意思是不倒下。", "不掉": "diào 比 dào 多了介音 i，韵母不同，意思是不掉落。"}, "sentence_index": null, "correct_answer": "不到"}, "level_3": {"options": [{"text": "不到", "is_correct": true, "explanation": "正确。“不到五岁”表示年龄还没有满五岁，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，不能说“吃五岁”。"}, {"text": "碰到", "is_correct": false, "explanation": "语义：“碰到”指接触或遇见，与年龄无关，“碰到五岁”句意不通。"}, {"text": "摸", "is_correct": false, "explanation": "语义：“摸”指用手接触，不能用来表示年龄，句子不通。"}], "explanations": {"不到": "正确。“不到五岁”表示年龄还没有满五岁，符合句意。", "吃": "搭配：“吃”的宾语应是食物，不能说“吃五岁”。", "碰到": "语义：“碰到”指接触或遇见，与年龄无关，“碰到五岁”句意不通。", "摸": "语义：“摸”指用手接触，不能用来表示年龄，句子不通。"}, "sentence_index": 0, "correct_answer": "不到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次数学不到及格，还得补考。", "explanation": "这里应该用〈没及格〉。“不到”表示未达到某个数量或标准，如“不到及格线”；说“不到及格”不自然，应说“没及格”。"}, {"text": "这次出差他不到回来。", "explanation": "这里应该用〈回不来〉。“不到”不能直接接动词作补语，表示无法回来要说“回不来”。"}, {"text": "这几天我都不到他的消息。", "explanation": "这里应该用〈收不到〉。表示没有得到消息要说“收不到”或“没收到”，“不到”不能直接接“消息”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20270, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不到", "is_correct": true, "explanation": "正确。不到 bú dào，表示没有达到某个数量或程度。"}, {"text": "不料", "is_correct": false, "explanation": "liào（第四声）与 dào 声母不同（l 与 d），声调相同，意思是没想到。"}, {"text": "不抱", "is_correct": false, "explanation": "bào 与 dào 声母不同（b 与 d），声调相同，意思是不拥抱。"}, {"text": "布道", "is_correct": false, "explanation": "bù（第四声）与 bú（第二声）声调不同，dào 相同，意思是向人宣讲教义。"}], "explanations": {"不到": "正确。不到 bú dào，表示没有达到某个数量或程度。", "不料": "liào（第四声）与 dào 声母不同（l 与 d），声调相同，意思是没想到。", "不抱": "bào 与 dào 声母不同（b 与 d），声调相同，意思是不拥抱。", "布道": "bù（第四声）与 bú（第二声）声调不同，dào 相同，意思是向人宣讲教义。"}, "sentence_index": null, "correct_answer": "不到"}, "level_3": {"options": [{"text": "不到", "is_correct": true, "explanation": "正确。“不到五千块”表示工资还没有达到五千块，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能与“工资”搭配，“工资唱五千块”不通。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿夹住或嚼碎，与工资无关，句子不通。"}, {"text": "跑", "is_correct": false, "explanation": "配价：“跑”是不及物动词，后面不能直接带“五千块”作宾语。"}], "explanations": {"不到": "正确。“不到五千块”表示工资还没有达到五千块，符合句意。", "唱": "搭配：“唱”的对象是歌曲，不能与“工资”搭配，“工资唱五千块”不通。", "咬": "语义：“咬”指用牙齿夹住或嚼碎，与工资无关，句子不通。", "跑": "配价：“跑”是不及物动词，后面不能直接带“五千块”作宾语。"}, "sentence_index": 6, "correct_answer": "不到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道题他不到做出来。", "explanation": "这里应该用〈做不出来〉。“不到”不能直接接动词作补语，表示做不出要说“做不出来”。"}, {"text": "这段时间，我一直不到他。", "explanation": "这里应该用〈见不到〉。“不到”后面接地点、时间或数量，不能直接带人作宾语，要说“见不到他”。"}, {"text": "因为堵车，我不到末班车了。", "explanation": "这里缺少动词“赶”，应说〈赶不到〉。“不到”单独不能接车次作宾语，要加“赶”构成“赶不到末班车”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20270, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他今年还不到了二十岁。", "corrected_sentence": "他今年还不到二十岁。", "error_description": "错误：“不到”后多加了“了”。“不到”表示还没达到某个数量，后面直接接数量，不能加“了”，应说“他今年还不到二十岁”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20270, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们等了很不到半个小时。", "corrected_sentence": "我们等了不到半个小时。", "error_description": "错误：在“不到”前多加了程度副词“很”。“不到”表示时间未达到某个长度，前面不能加“很”，应说“我们等了不到半个小时”，表示等待时间不足半小时。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
