INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20272, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "德国人就是来自德国的人。", "primary_collocate": null, "pronunciation": "dé guó rén", "ipa": "tɤ˧˥ kuɔ˧˥ ɻən˧˥", "syllable_count": 3, "sentences": [{"text": "他是德国人，住在柏林。", "target_word": "德国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的老师是一位德国人。", "target_word": "德国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多德国人喜欢喝啤酒。", "target_word": "德国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "德国人做事很认真。", "target_word": "德国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个德国人会说中文。", "target_word": "德国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在飞机上认识了一个德国人。", "target_word": "德国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他妈妈是中国人，爸爸是德国人。", "target_word": "德国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店有很多德国人来吃饭。", "target_word": "德国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "德国人也喜欢踢足球。", "target_word": "德国人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个德国人想去北京玩。", "target_word": "德国人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "德國人", "label": "繁体"}], "register": "中性", "sense_fingerprint": "国籍为德国的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09aebaf0-be95-4ef2-b319-0da839c40a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20272, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "德国人", "is_correct": true, "explanation": "德国人：国籍为德国的人，符合句意。"}, {"text": "猫", "is_correct": false, "explanation": "语义：“他”指人，不能是猫。"}, {"text": "木板", "is_correct": false, "explanation": "语义：木板是材料，不能用来说明一个人的身份。"}, {"text": "书店", "is_correct": false, "explanation": "搭配：“是”后接的身份名词一般指人，“书店”不能用来指人。"}], "explanations": {"德国人": "德国人：国籍为德国的人，符合句意。", "猫": "语义：“他”指人，不能是猫。", "木板": "语义：木板是材料，不能用来说明一个人的身份。", "书店": "搭配：“是”后接的身份名词一般指人，“书店”不能用来指人。"}, "sentence_index": 0, "correct_answer": "德国人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我认识一只德国人。", "explanation": "这里应该用〈个〉或〈位〉。德国人指人，量词不能用“只”，“只”通常用于动物。"}, {"text": "德国人位于欧洲中部。", "explanation": "这里应该用〈德国〉。德国是国家，人不能“位于”某地，“德国人”指人，不指地方。"}, {"text": "他会说流利的德国人。", "explanation": "这里应该用〈德语〉。说的是语言，德国人指人，不能用来说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20272, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "德国人", "is_correct": true, "explanation": "德国人：国籍为德国的人，符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能用来说明父亲的身份。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“是”后接身份名词时不说食物，“面包”不能用来指人。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海是水域，不能是一个人的身份或国籍。"}], "explanations": {"德国人": "德国人：国籍为德国的人，符合句意。", "桌子": "语义：桌子是家具，不能用来说明父亲的身份。", "面包": "搭配：“是”后接身份名词时不说食物，“面包”不能用来指人。", "大海": "语义：大海是水域，不能是一个人的身份或国籍。"}, "sentence_index": 6, "correct_answer": "德国人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我喜欢吃德国人。", "explanation": "这里应该用〈德国菜〉。德国人指人，不能用来吃，“吃”的对象应是菜。"}, {"text": "德国人很耐用。", "explanation": "这里应该用〈汽车〉。耐用形容物品，德国人是人，不能这样说。"}, {"text": "德国人很好听。", "explanation": "这里应该用〈德语〉。好听形容声音或语言，德国人指人，不能说“好听”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20272, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只德国人是工程师。", "corrected_sentence": "那位德国人是工程师。", "error_description": "“那只德国人”错误，“只”用于动物，指人应用“位”或“个”，应改为“那位德国人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20272, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张德国人是医生。", "corrected_sentence": "这位德国人是医生。", "error_description": "“这张德国人”错误，“张”用于纸张等扁平物，指人应用“位”或“个”，应改为“这位德国人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20274, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "迷信", "is_correct": true, "explanation": "正确：“科学”与“迷信”是一对反义词，前者讲究证据和规律，后者缺乏依据。"}, {"text": "音乐", "is_correct": false, "explanation": "“音乐”是艺术形式，与“科学”没有反义关系。"}, {"text": "运动", "is_correct": false, "explanation": "“运动”指身体活动，与“科学”没有反义关系。"}, {"text": "美食", "is_correct": false, "explanation": "“美食”指好吃的食物，与“科学”没有反义关系。"}], "correct_answer": "迷信", "explanations": {"迷信": "正确：“科学”与“迷信”是一对反义词，前者讲究证据和规律，后者缺乏依据。", "音乐": "“音乐”是艺术形式，与“科学”没有反义关系。", "运动": "“运动”指身体活动，与“科学”没有反义关系。", "美食": "“美食”指好吃的食物，与“科学”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20274, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "迷信", "is_correct": true, "explanation": "正确：“科学”与“迷信”是一对反义词，前者讲究证据和规律，后者缺乏依据。"}, {"text": "花园", "is_correct": false, "explanation": "“花园”指种花草的场所，与“科学”没有反义关系。"}, {"text": "旅游", "is_correct": false, "explanation": "“旅游”指出行游览，与“科学”没有反义关系。"}, {"text": "游戏", "is_correct": false, "explanation": "“游戏”指供人娱乐的活动，与“科学”没有反义关系。"}], "correct_answer": "迷信", "explanations": {"迷信": "正确：“科学”与“迷信”是一对反义词，前者讲究证据和规律，后者缺乏依据。", "花园": "“花园”指种花草的场所，与“科学”没有反义关系。", "旅游": "“旅游”指出行游览，与“科学”没有反义关系。", "游戏": "“游戏”指供人娱乐的活动，与“科学”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20274, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "科学是研究世界怎么运行的知识。", "primary_collocate": null, "pronunciation": "kē xué", "ipa": "kʰɤ˥ ɕɥe˧˥", "syllable_count": 2, "sentences": [{"text": "我觉得科学很有意思。", "target_word": "科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学能告诉我们天为什么会下雨。", "target_word": "科学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想长大以后研究科学。", "target_word": "科学", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "科学让我们的生活越来越方便。", "target_word": "科学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学需要认真做实验。", "target_word": "科学", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "很多人小时候对科学很感兴趣。", "target_word": "科学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学证明，地球绕着太阳转。", "target_word": "科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学好科学，需要多问为什么。", "target_word": "科学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老人一辈子都在研究科学。", "target_word": "科学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学告诉我们，水到零度会变成冰。", "target_word": "科学", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "科学家", "label": "复合"}, {"form": "科學", "label": "繁体"}], "register": "中性", "sense_fingerprint": "研究自然和世界规律的系统知识", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '245410d8-ef7c-4e0b-b864-35d4e472cd06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20274, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "科学", "is_correct": true, "explanation": "正确：“科学”指研究世界规律的知识，可以说“很有意思”，符合语境。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是一种疾病，不是可以被评价“很有意思”的对象。"}, {"text": "贵", "is_correct": false, "explanation": "词性：“贵”是形容词，不能作“觉得……很有意思”中的主语对象。"}, {"text": "饿", "is_correct": false, "explanation": "词性：“饿”是形容词，表示身体感觉，不能放在这里作被评价的对象。"}], "explanations": {"科学": "正确：“科学”指研究世界规律的知识，可以说“很有意思”，符合语境。", "感冒": "语义：感冒是一种疾病，不是可以被评价“很有意思”的对象。", "贵": "词性：“贵”是形容词，不能作“觉得……很有意思”中的主语对象。", "饿": "词性：“饿”是形容词，表示身体感觉，不能放在这里作被评价的对象。"}, "sentence_index": 0, "correct_answer": "科学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一位很有名的科学，发明了很多东西。", "explanation": "这里应该用〈科学家〉。“科学”指知识体系，不指人；从事研究的人要用〈科学家〉。"}, {"text": "他读了很多书，科学很深厚。", "explanation": "这里应该用〈学问〉。“科学”指知识体系，不能用来形容一个人的学识深厚。"}, {"text": "今天的科学很好，我们去公园吧。", "explanation": "这里应该用〈天气〉。“科学”指知识体系，不能用来形容天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20274, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "科学", "is_correct": true, "explanation": "正确：科学可以证明地球绕太阳转，符合语境。"}, {"text": "传说", "is_correct": false, "explanation": "语义：传说没有可靠证据，不能用来“证明”事实。"}, {"text": "梦", "is_correct": false, "explanation": "语义：梦是个人的想象，无法证明天文事实。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“脚步”不能用来证明事实，与“证明”搭配不当。"}], "explanations": {"科学": "正确：科学可以证明地球绕太阳转，符合语境。", "传说": "语义：传说没有可靠证据，不能用来“证明”事实。", "梦": "语义：梦是个人的想象，无法证明天文事实。", "脚步": "搭配：“脚步”不能用来证明事实，与“证明”搭配不当。"}, "sentence_index": 6, "correct_answer": "科学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家商店的科学很热闹。", "explanation": "这里应该用〈生意〉。“科学”是知识体系，不能形容商店的热闹程度；商店热闹要说〈生意〉。"}, {"text": "他每天坐着科学去上班。", "explanation": "这里应该用〈地铁〉。“科学”是知识体系，不能当作交通工具乘坐。"}, {"text": "他的科学今天感冒了。", "explanation": "这里应该用〈学生〉。“科学”是知识体系，不会感冒；会感冒的主语应是人，如〈学生〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20274, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "数学是一个很有用的科学。", "corrected_sentence": "数学是一门很有用的科学。", "error_description": "“科学”作为学科，应用量词“门”，不用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20274, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要用科学地方法解决问题。", "corrected_sentence": "我们要用科学的方法解决问题。", "error_description": "“科学”修饰名词“方法”时应用“的”，不能用“地”；“地”用于修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20276, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "消费", "is_correct": true, "explanation": "正确：“生产”与“消费”是一对反义词，前者是制造产品，后者是使用产品。"}, {"text": "休息", "is_correct": false, "explanation": "“休息”指停下来不做事，与“生产”没有反义关系。"}, {"text": "旅游", "is_correct": false, "explanation": "“旅游”指出行游览，与“生产”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”指慢慢地走，与“生产”没有反义关系。"}], "correct_answer": "消费", "explanations": {"消费": "正确：“生产”与“消费”是一对反义词，前者是制造产品，后者是使用产品。", "休息": "“休息”指停下来不做事，与“生产”没有反义关系。", "旅游": "“旅游”指出行游览，与“生产”没有反义关系。", "散步": "“散步”指慢慢地走，与“生产”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20276, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "消费", "is_correct": true, "explanation": "正确：“生产”与“消费”是一对反义词，前者是制造产品，后者是使用产品。"}, {"text": "睡觉", "is_correct": false, "explanation": "“睡觉”指休息入睡，与“生产”没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "“唱歌”指用声音表演歌曲，与“生产”没有反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "“跑步”指快速地跑，与“生产”没有反义关系。"}], "correct_answer": "消费", "explanations": {"消费": "正确：“生产”与“消费”是一对反义词，前者是制造产品，后者是使用产品。", "睡觉": "“睡觉”指休息入睡，与“生产”没有反义关系。", "唱歌": "“唱歌”指用声音表演歌曲，与“生产”没有反义关系。", "跑步": "“跑步”指快速地跑，与“生产”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20276, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做出有用的东西。", "primary_collocate": null, "pronunciation": "shēng chǎn", "ipa": "ʂɤŋ˥ ʈʂʰan˨˩˦", "syllable_count": 2, "sentences": [{"text": "这家工厂生产汽车。", "target_word": "生产", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们工厂每天生产一万个杯子。", "target_word": "生产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民在田里生产粮食。", "target_word": "生产", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个工厂生产的牛奶很好喝。", "target_word": "生产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新工厂开始生产电视了。", "target_word": "生产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在小镇上生产过很多鞋。", "target_word": "生产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家自己生产药，不用买。", "target_word": "生产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们正忙着生产新手机。", "target_word": "生产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为下雨，工厂今天不生产。", "target_word": "生产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台机器一天能生产一千双袜子。", "target_word": "生产", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "生产了", "label": "体标"}, {"form": "生产过", "label": "体标"}, {"form": "生产线", "label": "复合"}, {"form": "生產", "label": "繁体"}], "register": "中性", "sense_fingerprint": "工厂或农民制造出产品、粮食等物品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '245410d8-ef7c-4e0b-b864-35d4e472cd06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20276, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生产", "is_correct": true, "explanation": "正确：工厂“生产”汽车，指制造产品，符合语境。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的主语应是人，工厂不能驾驶汽车。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，汽车不能吃，与语境不符。"}, {"text": "旅行", "is_correct": false, "explanation": "配价：“旅行”是不及物动词，后面不能直接带“汽车”作宾语。"}], "explanations": {"生产": "正确：工厂“生产”汽车，指制造产品，符合语境。", "驾驶": "搭配：“驾驶”的主语应是人，工厂不能驾驶汽车。", "吃": "语义：“吃”指进食，汽车不能吃，与语境不符。", "旅行": "配价：“旅行”是不及物动词，后面不能直接带“汽车”作宾语。"}, "sentence_index": 0, "correct_answer": "生产"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事生产了很大的影响。", "explanation": "这里应该用〈产生〉。“生产”指制造物品或粮食，不能与“影响”搭配。"}, {"text": "他每天都在生产笑话。", "explanation": "这里应该用〈讲〉。笑话不是产品，“生产”的对象应是物品。"}, {"text": "他生产了一首很好听的歌。", "explanation": "这里应该用〈创作〉。“生产”指制造物品或粮食，写歌、作曲要用〈创作〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20276, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生产", "is_correct": true, "explanation": "正确：国家自己制造药品，符合“不用买”的语境。"}, {"text": "购买", "is_correct": false, "explanation": "语义：“购买”与后文“不用买”矛盾，不能用在这里。"}, {"text": "拍", "is_correct": false, "explanation": "搭配：“拍”的对象是照片、影视等，不能说“拍药”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说“唱药”。"}], "explanations": {"生产": "正确：国家自己制造药品，符合“不用买”的语境。", "购买": "语义：“购买”与后文“不用买”矛盾，不能用在这里。", "拍": "搭配：“拍”的对象是照片、影视等，不能说“拍药”。", "唱": "搭配：“唱”的对象是歌曲，不能说“唱药”。"}, "sentence_index": 6, "correct_answer": "生产"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家学校每年生产一百个学生。", "explanation": "这里应该用〈培养〉。“生产”指制造物品或粮食，学生是人，要用〈培养〉。"}, {"text": "妈妈每天在厨房生产三顿饭。", "explanation": "家里做饭应用〈做〉，〈生产〉指大规模制造产品，不用于日常做饭。"}, {"text": "他每天都生产很多好主意。", "explanation": "这里应该用〈想出〉。主意不是产品，不能用“生产”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20276, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂每天生产三十个汽车。", "corrected_sentence": "这家工厂每天生产三十辆汽车。", "error_description": "量词错误：“汽车”的量词应为“辆”，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20276, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家工厂明年能生产了五万双袜子。", "corrected_sentence": "这家工厂明年能生产五万双袜子。", "error_description": "“明年”指将来，“能”加动词表示将来的能力，动词后不能再加“了”，应说“明年能生产五万双袜子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
