INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20280, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "学习就是看、听、做，让自己知道更多东西。", "primary_collocate": null, "pronunciation": "xué xí", "ipa": "ɕɥe˧˥ ɕi˧˥", "syllable_count": 2, "sentences": [{"text": "我每天晚上在家学习汉语。", "target_word": "学习", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他学习很努力，老师常常夸他。", "target_word": "学习", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末我不出去玩，要在图书馆学习。", "target_word": "学习", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她正在学习做中国菜。", "target_word": "学习", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想向你学习怎么游泳。", "target_word": "学习", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一边工作，一边学习英语。", "target_word": "学习", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们坐在教室里认真学习。", "target_word": "学习", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我学习了一年中文，现在能和朋友聊天了。", "target_word": "学习", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家应该多向他学习。", "target_word": "学习", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟玩了一个下午，现在要学习了。", "target_word": "学习", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "学习了", "label": "体标（了）"}, {"form": "学习过", "label": "体标（过）"}, {"form": "學習", "label": "繁体"}], "register": "中性", "sense_fingerprint": "通过看、听、做获得知识和本领", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa6fc4b-3b94-4372-8dfa-3cb1d7e50379') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20280, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学习", "is_correct": true, "explanation": "学习：通过看、听、做获得知识，与“汉语”搭配，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语通常是食物，不能接“汉语”。"}, {"text": "睡", "is_correct": false, "explanation": "语义：睡是休息的动作，与“学习汉语”的学习行为矛盾。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的宾语是物体或身体部位，不能接“汉语”。"}], "explanations": {"学习": "学习：通过看、听、做获得知识，与“汉语”搭配，符合句意。", "吃": "搭配：“吃”的宾语通常是食物，不能接“汉语”。", "睡": "语义：睡是休息的动作，与“学习汉语”的学习行为矛盾。", "洗": "搭配：“洗”的宾语是物体或身体部位，不能接“汉语”。"}, "sentence_index": 0, "correct_answer": "学习"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师每天学习我们汉语。", "explanation": "这里应该用〈教〉。学习指学的一方获得知识，“老师”是施教的一方，应说“教”。"}, {"text": "妈妈在厨房学习了一碗面条给我吃。", "explanation": "这里应该用〈做〉。学习的对象是知识或技能，给人做饭要说“做”。"}, {"text": "张教授在大学里学习课。", "explanation": "这里应该用〈讲〉。教授面向学生讲课，不说“学习课”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9f4295-840f-4af1-87bc-c2967f68f7cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20280, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学习", "is_correct": true, "explanation": "学习：认真地获得知识，与“坐在教室里”的语境相符。"}, {"text": "站", "is_correct": false, "explanation": "语义：站与“坐在”的姿势矛盾。"}, {"text": "飞", "is_correct": false, "explanation": "语义：孩子不会飞，句子所指的是坐在教室里学习，飞说不通。"}, {"text": "游", "is_correct": false, "explanation": "搭配：“游”指在水中移动，不能用于教室里的学习。"}], "explanations": {"学习": "学习：认真地获得知识，与“坐在教室里”的语境相符。", "站": "语义：站与“坐在”的姿势矛盾。", "飞": "语义：孩子不会飞，句子所指的是坐在教室里学习，飞说不通。", "游": "搭配：“游”指在水中移动，不能用于教室里的学习。"}, "sentence_index": 6, "correct_answer": "学习"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她学习了一把椅子。", "explanation": "这里应该用〈买〉。学习的对象是知识或技能，不能是具体的椅子。"}, {"text": "他学习了一场雨。", "explanation": "这里应该用〈下〉。学习的对象是知识或技能，雨是自然现象，不能学习；说下雨。"}, {"text": "他学习了一只猫。", "explanation": "这里应该用〈养〉。学习的对象是知识或技能，猫是动物，不能学习。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9f4295-840f-4af1-87bc-c2967f68f7cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20280, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我学习很过汉语。", "corrected_sentence": "我学习过汉语。", "error_description": "副词误用：「很」插在动词「学习」与体标「过」之间，「很」只修饰形容词，应去掉「很」，说「我学习过汉语」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9f4295-840f-4af1-87bc-c2967f68f7cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20280, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他学习很得努力。", "corrected_sentence": "他学习得很努力。", "error_description": "错误形式是“学习很得努力”，正确形式是“学习得很努力”。程度补语“得”应紧接动词，“很”要放在“得”之后修饰形容词，不能放在“得”之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9f4295-840f-4af1-87bc-c2967f68f7cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
