INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20282, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "医学是帮人治病、让人健康的学问。", "primary_collocate": null, "pronunciation": "yī xué", "ipa": "i˥ ɕɥe˧˥", "syllable_count": 2, "sentences": [{"text": "他在大学学医学。", "target_word": "医学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医学帮助人们治病。", "target_word": "医学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐想学医学，以后当医生。", "target_word": "医学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现代医学发展得很快。", "target_word": "医学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医学书上说，每天运动对身体好。", "target_word": "医学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对医学很有兴趣，想当医生。", "target_word": "医学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医学要学很多年，也很辛苦。", "target_word": "医学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国的医学有几千年的历史。", "target_word": "医学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个医生的医学知识很多。", "target_word": "医学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医学的进步让很多病人恢复了健康。", "target_word": "医学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "醫學", "label": "繁体"}, {"form": "医学院", "label": "复合"}, {"form": "医学家", "label": "复合"}], "register": "中性", "sense_fingerprint": "研究治病和保持健康的学问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60fb9430-b8df-4950-a53e-fc0e3676837a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20282, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "医学", "is_correct": true, "explanation": "医学：研究治病、保持健康的学问，与“学”的对象相符。"}, {"text": "小学", "is_correct": false, "explanation": "语义：“小学”是基础教育阶段，与“大学”矛盾。"}, {"text": "幼儿园", "is_correct": false, "explanation": "语义：幼儿园是学前教育机构，不是可以学的学科，与“大学”冲突。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“学”接学科或技能，不接“作业”。"}], "explanations": {"医学": "医学：研究治病、保持健康的学问，与“学”的对象相符。", "小学": "语义：“小学”是基础教育阶段，与“大学”矛盾。", "幼儿园": "语义：幼儿园是学前教育机构，不是可以学的学科，与“大学”冲突。", "作业": "搭配：“学”接学科或技能，不接“作业”。"}, "sentence_index": 0, "correct_answer": "医学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是医学，每天给病人看病。", "explanation": "这里应该用〈医生〉。医学指学问，不指人；表示做这一职业的人要用“医生”。"}, {"text": "他每天吃医学，身体越来越好。", "explanation": "这里应该用〈药〉。医学指学问，不是可以吃的东西；吃下去治病的要用“药”。"}, {"text": "我的医学破了，要去买一双新的。", "explanation": "这里应该用〈鞋〉。医学是学问，不是穿的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20282, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "医学", "is_correct": true, "explanation": "医学：是需要花很多年学习的学问，符合句子语境。"}, {"text": "生日", "is_correct": false, "explanation": "语义：生日是日期，不是需要学很多年的对象。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是物品，不能作为需要学很多年的对象。"}, {"text": "窗户", "is_correct": false, "explanation": "配价：“要学”的主语应是可以学习的技能或学科，“窗户”不能充当。"}], "explanations": {"医学": "医学：是需要花很多年学习的学问，符合句子语境。", "生日": "语义：生日是日期，不是需要学很多年的对象。", "房子": "语义：房子是物品，不能作为需要学很多年的对象。", "窗户": "配价：“要学”的主语应是可以学习的技能或学科，“窗户”不能充当。"}, "sentence_index": 6, "correct_answer": "医学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天去医学上班，很辛苦。", "explanation": "这里应该用〈医院〉。医学是学问，不指工作的地点；去上班的地方要用“医院”。"}, {"text": "他每天用医学擦桌子。", "explanation": "这里应该用〈抹布〉。医学是学问，不是擦东西的用具；擦桌子要用“抹布”。"}, {"text": "医学很好喝，我每天喝一杯。", "explanation": "这里应该用〈牛奶〉。医学是学问，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20282, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我弟弟选了一本医学，想以后当医生。", "corrected_sentence": "我弟弟选了医学，想以后当医生。", "error_description": "量词错误：医学是学科，不能用“本”（“本”用于书），应直接说“选了医学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20282, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所医学的学生很努力。", "corrected_sentence": "这所医学院的学生很努力。", "error_description": "复合词错误：“医学”指学科，指学校要用“医学院”。应说“医学院的学生”，不说“医学的学生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
