INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20284, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "别人有困难时，你去做点事让他好过一点。", "primary_collocate": null, "pronunciation": "bāng zhù", "ipa": "paŋ˥ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "谢谢你帮助我学中文。", "target_word": "帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师常常帮助有困难的同学。", "target_word": "帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他帮助了很多生病的老人。", "target_word": "帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们都愿意帮助我们。", "target_word": "帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想帮助他，但是不知道怎么做。", "target_word": "帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友帮助我找到了新工作。", "target_word": "帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶年纪大了，爸爸常常帮助她做家务。", "target_word": "帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们互相帮助，一起做完了作业。", "target_word": "帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她总是帮助别人，大家都喜欢她。", "target_word": "帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该帮助那位迷路的老人。", "target_word": "帮助", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "帮助了", "label": "体标"}, {"form": "帮助过", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词，在别人有困难时出力或出主意，使对方得到好处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b19119-d89a-436b-a0df-53ddddc827e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20284, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "帮助", "is_correct": true, "explanation": "正确：听到的是“帮助”bāngzhù，指出力或出主意使别人好过一点。"}, {"text": "绑住", "is_correct": false, "explanation": "绑住 bǎngzhù 与 帮助 bāngzhù 第一音节声调不同（bǎng 第三声，bāng 第一声），意思是绑住。"}, {"text": "保住", "is_correct": false, "explanation": "保住 bǎozhù 与 帮助 bāngzhù 第一音节韵母不同（-o 与 -ng）且声调不同，意思是保住。"}, {"text": "抱住", "is_correct": false, "explanation": "抱住 bàozhù 与 帮助 bāngzhù 第一音节韵母与声调都不同，意思是抱住。"}, {"text": "帮主", "is_correct": false, "explanation": "帮主 bāngzhǔ 与 帮助 bāngzhù 第二音节声调不同（zhǔ 第三声，zhù 第四声），意思是帮派的首领。"}], "explanations": {"帮助": "正确：听到的是“帮助”bāngzhù，指出力或出主意使别人好过一点。", "绑住": "绑住 bǎngzhù 与 帮助 bāngzhù 第一音节声调不同（bǎng 第三声，bāng 第一声），意思是绑住。", "保住": "保住 bǎozhù 与 帮助 bāngzhù 第一音节韵母不同（-o 与 -ng）且声调不同，意思是保住。", "抱住": "抱住 bàozhù 与 帮助 bāngzhù 第一音节韵母与声调都不同，意思是抱住。", "帮主": "帮主 bāngzhǔ 与 帮助 bāngzhù 第二音节声调不同（zhǔ 第三声，zhù 第四声），意思是帮派的首领。"}, "sentence_index": null, "correct_answer": "帮助"}, "level_3": {"options": [{"text": "帮助", "is_correct": true, "explanation": "正确：“谢谢”之后接帮助对方的行为，“帮助我学中文”符合语境。"}, {"text": "阻碍", "is_correct": false, "explanation": "语义：“阻碍”指妨碍，与“谢谢”的感激语境相反，“谢谢你阻碍我学中文”不通。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“反对”表示不同意，与“谢谢”前后矛盾，句意不通。"}, {"text": "打断", "is_correct": false, "explanation": "搭配：“打断”多接讲话、思路等，“打断我学中文”搭配不自然。"}], "explanations": {"帮助": "正确：“谢谢”之后接帮助对方的行为，“帮助我学中文”符合语境。", "阻碍": "语义：“阻碍”指妨碍，与“谢谢”的感激语境相反，“谢谢你阻碍我学中文”不通。", "反对": "语义：“反对”表示不同意，与“谢谢”前后矛盾，句意不通。", "打断": "搭配：“打断”多接讲话、思路等，“打断我学中文”搭配不自然。"}, "sentence_index": 0, "correct_answer": "帮助"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们帮助你的决定。", "explanation": "这里应该用〈支持〉。“帮助”针对需要援助的人，对别人的决定表示赞同要用“支持”。"}, {"text": "我们帮助了那间破旧的房子。", "explanation": "这里应该用〈修缮〉。帮助的对象是人，破旧的房子要修缮，不能说帮助房子。"}, {"text": "我帮助她的勇气。", "explanation": "这里应该用〈欣赏〉。“帮助”指给人实际援助，不用于欣赏对方的品质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5386a762-7b32-4110-b8c7-1a768f13dace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20284, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "帮助", "is_correct": true, "explanation": "正确：听到的是“帮助”bāngzhù，指出力或出主意使别人好过一点。"}, {"text": "包住", "is_correct": false, "explanation": "包住 bāozhù 与 帮助 bāngzhù 第一音节韵母不同（-o 与 -ng），意思是包住。"}, {"text": "扳住", "is_correct": false, "explanation": "扳住 bānzhù 与 帮助 bāngzhù 第一音节韵母不同（-n 与 -ng），意思是用力拉住或握紧。"}, {"text": "绷住", "is_correct": false, "explanation": "绷住 bēngzhù 与 帮助 bāngzhù 第一音节主要元音不同（ē 与 ā），意思是绷紧、撑住。"}], "explanations": {"帮助": "正确：听到的是“帮助”bāngzhù，指出力或出主意使别人好过一点。", "包住": "包住 bāozhù 与 帮助 bāngzhù 第一音节韵母不同（-o 与 -ng），意思是包住。", "扳住": "扳住 bānzhù 与 帮助 bāngzhù 第一音节韵母不同（-n 与 -ng），意思是用力拉住或握紧。", "绷住": "绷住 bēngzhù 与 帮助 bāngzhù 第一音节主要元音不同（ē 与 ā），意思是绷紧、撑住。"}, "sentence_index": null, "correct_answer": "帮助"}, "level_3": {"options": [{"text": "帮助", "is_correct": true, "explanation": "正确：“爸爸常常帮助她做家务”指爸爸替年纪大的奶奶分担家务，符合语境。"}, {"text": "怀念", "is_correct": false, "explanation": "语义：“怀念”指思念过去的人或事，不能用来表示正在进行的家务帮忙，句意不通。"}, {"text": "打听", "is_correct": false, "explanation": "搭配：“打听”一般接消息、情况，不接“她做家务”，搭配不当。"}, {"text": "原谅", "is_correct": false, "explanation": "语义：“原谅”针对过错，句中没有需要原谅的事，句意不通。"}], "explanations": {"帮助": "正确：“爸爸常常帮助她做家务”指爸爸替年纪大的奶奶分担家务，符合语境。", "怀念": "语义：“怀念”指思念过去的人或事，不能用来表示正在进行的家务帮忙，句意不通。", "打听": "搭配：“打听”一般接消息、情况，不接“她做家务”，搭配不当。", "原谅": "语义：“原谅”针对过错，句中没有需要原谅的事，句意不通。"}, "sentence_index": 6, "correct_answer": "帮助"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师帮助了他的错误。", "explanation": "这里应该用〈批评〉。“帮助”针对需要帮助的人，指出错误要用“批评”。"}, {"text": "他帮助了历史。", "explanation": "这里应该用〈研究〉。“帮助”的对象是人，历史不能被帮助，研究历史要用“研究”。"}, {"text": "工程师帮助了这座桥。", "explanation": "这里应该用〈设计〉。“帮助”的对象是人，桥是被设计出来的，应用“设计”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5386a762-7b32-4110-b8c7-1a768f13dace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20284, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "去年他帮助我了很多次。", "corrected_sentence": "去年他帮助了我很多次。", "error_description": "错误：“帮助我了”；正确：“帮助了我”。动词后面的“了”要紧跟动词，“我”是宾语，应放在“了”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5386a762-7b32-4110-b8c7-1a768f13dace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20284, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们互帮助，度过了难关。", "corrected_sentence": "我们互相帮助，度过了难关。", "error_description": "错误：“互帮助”不是规范说法；应为“互相帮助”。“互相”是表示彼此的副词，应放在动词“帮助”之前，“互”不能拆出来单独修饰“帮助”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5386a762-7b32-4110-b8c7-1a768f13dace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
