INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20286, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "已经发生过的事情，就像昨天做的事一样。", "primary_collocate": null, "pronunciation": "lì shǐ", "ipa": "li⁵¹ ʂɻ̩²¹⁴", "syllable_count": 2, "sentences": [{"text": "我喜欢听老师讲历史故事。", "target_word": "历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市有两千年的历史。", "target_word": "历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事已经成为历史了。", "target_word": "历史", "complexity_tier": "T3", "furigana": "zhè jiàn shì yǐ jīng chéng wéi lì shǐ le", "sentence_source": "generated"}, {"text": "我昨天读了一本讲历史的书。", "target_word": "历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一段很长的历史。", "target_word": "历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要记住这段历史。", "target_word": "历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京的历史比上海长。", "target_word": "历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对中国历史很感兴趣。", "target_word": "历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里的东西都在讲历史。", "target_word": "历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人给孩子们讲村子的历史。", "target_word": "历史", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "段", "label": "量词"}, {"form": "歷史", "label": "繁体"}, {"form": "历史学", "label": "复合"}], "register": "中性", "sense_fingerprint": "过去发生的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f67254c-2b72-48f7-a62f-6cc95d11eae2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20286, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "历史", "is_correct": true, "explanation": "正确：历史 lì shǐ，指已经发生过的事情。"}, {"text": "历时", "is_correct": false, "explanation": "第二音节 shí（第二声）与 shǐ（第三声）声调不同，意思是经历一段时间。"}, {"text": "理事", "is_correct": false, "explanation": "两个音节声调都不同（第三声、第四声），意思是负责管理事务的人。"}, {"text": "力士", "is_correct": false, "explanation": "第二音节 shì（第四声）与 shǐ（第三声）声调不同，意思是力气大的人。"}, {"text": "离世", "is_correct": false, "explanation": "两个音节声调都不同（第二声、第四声），意思是去世。"}], "explanations": {"历史": "正确：历史 lì shǐ，指已经发生过的事情。", "历时": "第二音节 shí（第二声）与 shǐ（第三声）声调不同，意思是经历一段时间。", "理事": "两个音节声调都不同（第三声、第四声），意思是负责管理事务的人。", "力士": "第二音节 shì（第四声）与 shǐ（第三声）声调不同，意思是力气大的人。", "离世": "两个音节声调都不同（第二声、第四声），意思是去世。"}, "sentence_index": null, "correct_answer": "历史"}, "level_3": {"options": [{"text": "历史", "is_correct": true, "explanation": "正确：历史故事指讲过去发生的事的故事，符合语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是气象变化，不能被“讲”成故事。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体形，不能被“讲”成故事。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：作业是练习题，一般不能被“讲”成故事。"}], "explanations": {"历史": "正确：历史故事指讲过去发生的事的故事，符合语境。", "天气": "语义：天气是气象变化，不能被“讲”成故事。", "身材": "体貌：身材指人的体形，不能被“讲”成故事。", "作业": "搭配：作业是练习题，一般不能被“讲”成故事。"}, "sentence_index": 0, "correct_answer": "历史"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天打了一个历史。", "explanation": "这里应该用〈电话〉。历史指已经发生的事，不是可以拨打的东西。"}, {"text": "我们花了很多历史。", "explanation": "这里应该用〈时间〉。历史是已经发生的事，不能用“花”来计量。"}, {"text": "这把历史很悠久。", "explanation": "这里应该用〈段〉。历史用“段”计量，“把”用于有柄的器物，不能用于历史。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20286, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "历史", "is_correct": true, "explanation": "正确：北京的历史指北京过去的发展，比较长短符合语境。"}, {"text": "语言", "is_correct": false, "explanation": "语义：语言没有长短之分，不能拿来和城市比“长”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重指轻重，不能用“长”来比较。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：人口多少要说“多”或“少”，不说“长”。"}], "explanations": {"历史": "正确：北京的历史指北京过去的发展，比较长短符合语境。", "语言": "语义：语言没有长短之分，不能拿来和城市比“长”。", "体重": "语义：体重指轻重，不能用“长”来比较。", "人口": "搭配：人口多少要说“多”或“少”，不说“长”。"}, "sentence_index": 6, "correct_answer": "历史"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个历史位置很好，交通也方便。", "explanation": "这里应该用〈地理〉。历史指已经发生的事，不能用来说位置。"}, {"text": "今天的历史很好，我们去公园吧。", "explanation": "这里应该用〈天气〉。历史是过去的事，不能用来形容今天的状况。"}, {"text": "他每天早上吃历史。", "explanation": "这里应该用〈早饭〉。历史不是可以吃的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20286, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要珍惜这张历史。", "corrected_sentence": "我们要珍惜这段历史。", "error_description": "量词错误：历史用“段”计量，应说“这段历史”，不能用“张”（“张”用于纸张、桌子等平面的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20286, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座城市的历史的很长。", "corrected_sentence": "这座城市的历史很长。", "error_description": "多余的“的”：“历史”与“很长”之间不能加“的”，应说“这座城市的历史很长”，不能说“这座城市的历史的很长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
