INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20288, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "指每个人。", "primary_collocate": null, "pronunciation": "suǒ yǒu rén", "ipa": "swo˨˩ i̯oʊ˨˩˦ ɻən˧˥", "syllable_count": 3, "sentences": [{"text": "所有人都到了，我们可以开始了。", "target_word": "所有人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请所有人把书打开。", "target_word": "所有人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个好消息，所有人都笑了。", "target_word": "所有人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "所有人都喜欢她，因为她很热心。", "target_word": "所有人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题，所有人都答对了。", "target_word": "所有人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想谢谢所有人，今天你们帮了我。", "target_word": "所有人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，所有人都跑进了教室。", "target_word": "所有人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间很小，坐不下所有人。", "target_word": "所有人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束后，所有人一起拍了照。", "target_word": "所有人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "所有人都在等他，他却睡着了。", "target_word": "所有人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "所有人：每一个人，全部的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e8c9982-2261-4a26-bafc-a41b87d5771d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20288, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "所有人", "is_correct": true, "explanation": "正确：“所有人”指全部的人，与“都到了”的全体语义一致。"}, {"text": "没有人", "is_correct": false, "explanation": "语义：“没有人”否定存在，与“都到了”的全体义矛盾，不能用于此句。"}, {"text": "个别人", "is_correct": false, "explanation": "语义：“个别人”指少数几个人，与“都到了”表示的全体义矛盾。"}, {"text": "有人", "is_correct": false, "explanation": "搭配：“有人”表示不确定的个别人，不能与“都”搭配表示全体。"}], "explanations": {"所有人": "正确：“所有人”指全部的人，与“都到了”的全体语义一致。", "没有人": "语义：“没有人”否定存在，与“都到了”的全体义矛盾，不能用于此句。", "个别人": "语义：“个别人”指少数几个人，与“都到了”表示的全体义矛盾。", "有人": "搭配：“有人”表示不确定的个别人，不能与“都”搭配表示全体。"}, "sentence_index": 0, "correct_answer": "所有人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "所有人都没来，只有他来了。", "explanation": "这里应该用〈别人〉。“所有人”包括他自己，和“只有他来了”矛盾；除他以外的人要说“别人”。"}, {"text": "所有人喜欢夏天，有的人喜欢冬天。", "explanation": "这里应该用〈大多数人〉。“所有人”表示全体，与后半句的“有的人”表示部分相矛盾；说大多数喜欢要用“大多数人”。"}, {"text": "很多所有人都喜欢他。", "explanation": "这里应该用〈很多人〉。“所有人”本身已是全体的说法，前面不能再加“很多”等数量词修饰；要说“很多人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20288, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "所有人", "is_correct": true, "explanation": "正确：“所有人”指全部的人，与“都跑进了教室”的全体语义一致。"}, {"text": "没有人", "is_correct": false, "explanation": "语义：“没有人”否定存在，与“都跑进了教室”的全体动作矛盾。"}, {"text": "没有一个人", "is_correct": false, "explanation": "语义：“没有一个人”否定全部，与“都”表示的全体语义直接冲突。"}, {"text": "一个人", "is_correct": false, "explanation": "数量：“一个人”只指单独一人，不能与“都”搭配表示多人全体。"}], "explanations": {"所有人": "正确：“所有人”指全部的人，与“都跑进了教室”的全体语义一致。", "没有人": "语义：“没有人”否定存在，与“都跑进了教室”的全体动作矛盾。", "没有一个人": "语义：“没有一个人”否定全部，与“都”表示的全体语义直接冲突。", "一个人": "数量：“一个人”只指单独一人，不能与“都”搭配表示多人全体。"}, "sentence_index": 6, "correct_answer": "所有人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "很少所有人愿意帮忙。", "explanation": "这里应该用〈少数人〉。“所有人”指全体，不能用来指少数人；说只有少数人愿意要用“少数人”。"}, {"text": "这些书所有人都是我的。", "explanation": "这里应该用〈全部〉。“所有人”只能指人，不能用来指书。"}, {"text": "所有人一个也没到。", "explanation": "这里应该用〈没有人〉。“所有人”指全体，与“一个也没到”的说法矛盾；一个都没来要说“没有人来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20288, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "所有人的都参加了比赛。", "corrected_sentence": "所有人都参加了比赛。", "error_description": "错误：“所有人”后多加了“的”，使它变成定语，后面缺少中心语，句子不通。正确：应直接说“所有人都参加了比赛”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20288, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "所有人们都同意这个计划。", "corrected_sentence": "所有人都同意这个计划。", "error_description": "错误：“所有人”本身已指全体，不能再加复数后缀“们”，属于重复表示复数。正确：应去掉“们”，说“所有人都同意这个计划”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
