INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20290, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb992c-4cb3-4d2d-b363-c122f580b353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20290, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "就是马上做，不等一会儿。", "primary_collocate": null, "pronunciation": "lì kè", "ipa": "li˥˩ kʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "听到电话响，他立刻跑过去了。", "target_word": "立刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说“开始”，我们立刻写字。", "target_word": "立刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你到家以后，请立刻给我打电话。", "target_word": "立刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看见红灯，司机立刻停下车。", "target_word": "立刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他应该立刻去医院。", "target_word": "立刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一回到家，就立刻洗手。", "target_word": "立刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子哭了，妈妈立刻抱起他。", "target_word": "立刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课铃一响，学生们立刻站起来。", "target_word": "立刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发现钥匙不见了，她立刻回头找。", "target_word": "立刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到好消息，他立刻告诉了朋友。", "target_word": "立刻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，表示马上做，不拖延", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c13fba2-698e-4727-b25b-42f4c360e701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20290, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "立刻", "is_correct": true, "explanation": "正确：“立刻”表示马上做，不等一会儿，与“听到电话响”后的即时反应相符。"}, {"text": "始终", "is_correct": false, "explanation": "语义：“始终”表示一贯不变，与“听到电话响”后的一次性动作不合。"}, {"text": "渐渐", "is_correct": false, "explanation": "语义：“渐渐”表示逐步变化，不能用来描述听到电话后一下子跑过去的瞬间动作。"}, {"text": "偶尔", "is_correct": false, "explanation": "搭配：“偶尔”表示不常发生，与“跑过去了”这种一次性完成的动作不搭配。"}], "explanations": {"立刻": "正确：“立刻”表示马上做，不等一会儿，与“听到电话响”后的即时反应相符。", "始终": "语义：“始终”表示一贯不变，与“听到电话响”后的一次性动作不合。", "渐渐": "语义：“渐渐”表示逐步变化，不能用来描述听到电话后一下子跑过去的瞬间动作。", "偶尔": "搭配：“偶尔”表示不常发生，与“跑过去了”这种一次性完成的动作不搭配。"}, "sentence_index": 0, "correct_answer": "立刻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他立刻学了三年汉语。", "explanation": "这里应该用〈一直〉。“立刻”表示马上做某事，不能和“三年”这种时段搭配；表示持续的动作要说“一直”。"}, {"text": "他立刻在这家公司干了十年。", "explanation": "这里应该用〈已经〉。“立刻”指动作马上发生，不能与“十年”这类长时段连用；说经历的时间要用“已经在这家公司干了十年”。"}, {"text": "我立刻吃过饭了，所以不饿。", "explanation": "这里应该用〈刚刚〉。“立刻”表示动作马上发生，不表示刚过去不久；刚完成的动作要说“刚刚吃过饭了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb992c-4cb3-4d2d-b363-c122f580b353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20290, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "立刻", "is_correct": true, "explanation": "正确：“立刻”表示马上行动，与“孩子哭了”后妈妈马上抱起他的情形相符。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”多用于否定句或表示一贯情况，不能修饰“抱起他”这种一次性动作。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：“一直”表示持续不断，不与“抱起”这种一次性完成的动作搭配。"}, {"text": "始终", "is_correct": false, "explanation": "语义：“始终”表示一贯不变，与“孩子哭了”这一次具体情形不合。"}], "explanations": {"立刻": "正确：“立刻”表示马上行动，与“孩子哭了”后妈妈马上抱起他的情形相符。", "从来": "搭配：“从来”多用于否定句或表示一贯情况，不能修饰“抱起他”这种一次性动作。", "一直": "搭配：“一直”表示持续不断，不与“抱起”这种一次性完成的动作搭配。", "始终": "语义：“始终”表示一贯不变，与“孩子哭了”这一次具体情形不合。"}, "sentence_index": 6, "correct_answer": "立刻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他立刻是我的老师。", "explanation": "这里应该用〈原来〉。“立刻”修饰马上发生的动作，不能用来说明早已存在的身份；说明一直如此要用“原来是”。"}, {"text": "这把椅子立刻很旧了。", "explanation": "这里应该用〈渐渐〉。“立刻”指动作即刻发生，不能描述“很旧”这种慢慢形成的状态；慢慢变化要说“渐渐变旧了”。"}, {"text": "他立刻天天锻炼身体。", "explanation": "这里应该用〈一直〉。“立刻”表示某一次动作马上发生，不能修饰“天天”这种长期习惯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb992c-4cb3-4d2d-b363-c122f580b353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20290, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈立刻立刻接了电话。", "corrected_sentence": "妈妈立刻接了电话。", "error_description": "错误在于“立刻”重复出现：副词“立刻”只用一次，放在动词“接”之前。应说“妈妈立刻接了电话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb992c-4cb3-4d2d-b363-c122f580b353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20290, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他立刻的站了起来。", "corrected_sentence": "他立刻站了起来。", "error_description": "错误在于“立刻”后面多加了“的”。“立刻”是副词，修饰动词时不加“的”，应说“立刻站了起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb992c-4cb3-4d2d-b363-c122f580b353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
