INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20292, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很多人住在一起的大地方。", "primary_collocate": null, "pronunciation": "chéng shì", "ipa": "ʈʂʰɤŋ˧˥ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "北京是中国很大的城市。", "target_word": "城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢在安静的城市里生活。", "target_word": "城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市有很多公园。", "target_word": "城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小城市搬到了大城市。", "target_word": "城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里的公交车很方便。", "target_word": "城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的城市又热又吵。", "target_word": "城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐飞机去了另一个城市。", "target_word": "城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的冬天很冷。", "target_word": "城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多年轻人想去大城市工作。", "target_word": "城市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上，城市的灯都亮着。", "target_word": "城市", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "城市化", "label": "复合词"}], "register": "中性", "sense_fingerprint": "人口集中、有工商业和公共设施的大型居住地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1de80df8-30f4-4a4d-832e-d5d2f03764c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20292, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国家", "is_correct": false, "explanation": "语义：北京是城市，不是国家，“北京是中国很大的国家”说法不成立。"}, {"text": "学校", "is_correct": false, "explanation": "搭配：“中国很大的学校”修饰的不是地区，“北京是……学校”无法指代北京。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋是水域，北京不是海洋，句子与北京的所指冲突。"}, {"text": "城市", "is_correct": true, "explanation": "城市指很多人住在一起的大地方，北京符合这一说法。"}], "explanations": {"国家": "语义：北京是城市，不是国家，“北京是中国很大的国家”说法不成立。", "学校": "搭配：“中国很大的学校”修饰的不是地区，“北京是……学校”无法指代北京。", "海洋": "语义：海洋是水域，北京不是海洋，句子与北京的所指冲突。", "城市": "城市指很多人住在一起的大地方，北京符合这一说法。"}, "sentence_index": 0, "correct_answer": "城市"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个城市只住着几户人家，安安静静的。", "explanation": "这里应该用〈小镇〉。城市指很多人住在一起的大地方，句中只住着几户人家，应说小镇。"}, {"text": "这个城市只有几十个人，大家都互相认识。", "explanation": "这里应该用〈村庄〉。城市指很多人住在一起的大地方，句中只有几十个人、大家互相认识，应说村庄。"}, {"text": "中国是世界上人口最多的城市。", "explanation": "这里应该用〈国家〉。城市指人口集中的大地方，中国是国家，不能说城市。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20292, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "故事", "is_correct": false, "explanation": "语义：故事不是可以前往的地方，与“坐飞机去了”的处所不符。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不是人可以坐飞机前往的居住地，“去了另一个河流”不通。"}, {"text": "手指", "is_correct": false, "explanation": "搭配：“去”后面接身体部位不成立，“去了另一个手指”无法理解。"}, {"text": "城市", "is_correct": true, "explanation": "城市是可以坐飞机前往的地方，与句中语境相符。"}], "explanations": {"故事": "语义：故事不是可以前往的地方，与“坐飞机去了”的处所不符。", "河流": "语义：河流不是人可以坐飞机前往的居住地，“去了另一个河流”不通。", "手指": "搭配：“去”后面接身体部位不成立，“去了另一个手指”无法理解。", "城市": "城市是可以坐飞机前往的地方，与句中语境相符。"}, "sentence_index": 6, "correct_answer": "城市"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个城市人口稀少，主要是牧场。", "explanation": "这里应该用〈地区〉。城市指人口集中的大地方，这里说人口稀少、主要是牧场，应说地区。"}, {"text": "这个城市每天早上五点下地干活。", "explanation": "这里应该用〈农民〉。城市指很多人住在一起的大地方，不能下地干活；句中说下地干活，只能指人，应说农民。"}, {"text": "这个城市到处是田地，几乎没有高楼。", "explanation": "这里应该用〈村庄〉。城市要人口集中、有高楼，到处是田地应说村庄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20292, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条城市的地铁很方便。", "corrected_sentence": "这座城市的地铁很方便。", "error_description": "量词错误：“城市”可用“座”或“个”，不能说“条”；“条”多用于河流、道路等细长事物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20292, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我一直住在城市上。", "corrected_sentence": "我一直住在城市里。", "error_description": "方位词错误：“里”表示在范围之内，应说“城市里”；“上”指表面，不能说“城市上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
