INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20294, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "可以放很多书，让大家安静看书的房子。", "primary_collocate": null, "pronunciation": "tú shū guǎn", "ipa": "tʰu˧˥ ʂu˥ kuan˨˩˦", "syllable_count": 3, "sentences": [{"text": "我每个星期六去图书馆。", "target_word": "图书馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆里很安静。", "target_word": "图书馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在图书馆看了一下午书。", "target_word": "图书馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的图书馆有很多书。", "target_word": "图书馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书我是从图书馆借的。", "target_word": "图书馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆几点关门？", "target_word": "图书馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你在图书馆里不能大声说话。", "target_word": "图书馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和朋友约好在图书馆门口见面。", "target_word": "图书馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市有一座很大的图书馆。", "target_word": "图书馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆旁边有一家小咖啡店。", "target_word": "图书馆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "大学图书馆", "label": "复合词"}], "register": "中性", "sense_fingerprint": "收藏书籍供人阅读和借阅的公共场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b8f789-626d-40d7-a308-633398a91259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20294, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "太阳", "is_correct": false, "explanation": "语义：“去”的对象是可以前往的场所，太阳不能前往。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是设备，不是可以前往的场所，“去电脑”不成立。"}, {"text": "图书馆", "is_correct": true, "explanation": "图书馆是供人借阅书籍、安静看书的场所，每周六去正合句意。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“去”后接场所，窗户只是建筑部件，不说“去窗户”。"}], "explanations": {"太阳": "语义：“去”的对象是可以前往的场所，太阳不能前往。", "电脑": "语义：电脑是设备，不是可以前往的场所，“去电脑”不成立。", "图书馆": "图书馆是供人借阅书籍、安静看书的场所，每周六去正合句意。", "窗户": "搭配：“去”后接场所，窗户只是建筑部件，不说“去窗户”。"}, "sentence_index": 0, "correct_answer": "图书馆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个图书馆卖很多外语书。", "explanation": "这里应该用〈书店〉。图书馆供人借阅，不卖书；卖书的地方是书店。"}, {"text": "这个图书馆里的厨师正在做饭。", "explanation": "这里应该用〈厨房〉。图书馆是借阅书籍的地方，做饭要在厨房进行。"}, {"text": "图书馆里有很多运动员在比赛。", "explanation": "这里应该用〈体育馆〉。图书馆是借阅书籍的地方，运动员比赛要在体育馆进行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20294, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "足球场", "is_correct": false, "explanation": "语义：足球场是人们大声呼喊的场所，与“不能大声说话”的语境矛盾。"}, {"text": "图书馆", "is_correct": true, "explanation": "图书馆是安静看书的地方，所以不能大声说话，句意通顺。"}, {"text": "歌厅", "is_correct": false, "explanation": "语义：歌厅是唱歌、喧闹的场所，与“不能大声说话”矛盾。"}, {"text": "朋友", "is_correct": false, "explanation": "配价：“在……里”后接处所，不接人，“在朋友里”不成立。"}], "explanations": {"足球场": "语义：足球场是人们大声呼喊的场所，与“不能大声说话”的语境矛盾。", "图书馆": "图书馆是安静看书的地方，所以不能大声说话，句意通顺。", "歌厅": "语义：歌厅是唱歌、喧闹的场所，与“不能大声说话”矛盾。", "朋友": "配价：“在……里”后接处所，不接人，“在朋友里”不成立。"}, "sentence_index": 6, "correct_answer": "图书馆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "图书馆里的医生正在给病人看病。", "explanation": "这里应该用〈医院〉。图书馆供人借阅书籍，给病人看病要在医院进行。"}, {"text": "图书馆里的游泳池很干净，大家都在游泳。", "explanation": "这里应该用〈游泳馆〉。图书馆是借阅书籍的地方，游泳要在游泳馆进行。"}, {"text": "图书馆里很热闹，大家都在看电影。", "explanation": "这里应该用〈电影院〉。图书馆供人安静看书，看电影要去电影院。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20294, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只图书馆很大。", "corrected_sentence": "这座图书馆很大。", "error_description": "量词错误：图书馆是建筑，量词应用“座”，“只”用于动物等，不能用于建筑。正确说法是“这座图书馆很大”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20294, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家附近新建了一张图书馆。", "corrected_sentence": "我家附近新建了一座图书馆。", "error_description": "量词错误：图书馆是建筑，应搭配量词“座”，“张”用于纸、桌子等平面的东西。正确说法是“新建了一座图书馆”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
