INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20298, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "识字就是学会认字。", "primary_collocate": null, "pronunciation": "shí zì", "ipa": "ʂɻ̩˧˥ tsɹ̩˥˩", "syllable_count": 2, "sentences": [{"text": "奶奶小时候没上过学，所以不识字。", "target_word": "识字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子才三岁，已经开始识字了。", "target_word": "识字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷不识字，但是会做很多事。", "target_word": "识字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师每天教小朋友识字。", "target_word": "识字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "以前村里很多人不识字，不会看书。", "target_word": "识字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈用卡片教孩子识字。", "target_word": "识字", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他五岁就会识字，也能读简单的故事。", "target_word": "识字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校办了夜校，帮大人识字。", "target_word": "识字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外婆不识字，所以看不懂信。", "target_word": "识字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们先识字，然后才学写字。", "target_word": "识字", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "識字", "label": "繁体"}, {"form": "识了字", "label": "体标"}, {"form": "识过字", "label": "体标"}], "register": "中性", "sense_fingerprint": "学会认识汉字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb662756-0b78-4edf-9c5e-051c04c57dff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20298, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "识字", "is_correct": true, "explanation": "识字指学会认识汉字，与“没上过学”前后呼应，句意通顺。"}, {"text": "做饭", "is_correct": false, "explanation": "语义：“没上过学”与“做饭”之间没有因果关系，“所以不做饭”句意不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“没上过学”与“游泳”之间没有因果关系，句意不通。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“没上过学”与“唱歌”之间没有因果关系，句意不通。"}], "explanations": {"识字": "识字指学会认识汉字，与“没上过学”前后呼应，句意通顺。", "做饭": "语义：“没上过学”与“做饭”之间没有因果关系，“所以不做饭”句意不通。", "游泳": "语义：“没上过学”与“游泳”之间没有因果关系，句意不通。", "唱歌": "语义：“没上过学”与“唱歌”之间没有因果关系，句意不通。"}, "sentence_index": 0, "correct_answer": "识字"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天在电脑前识字，写的程序很好用。", "explanation": "这里应该用〈编程〉。识字指学会认字，与编写程序无关；写程序要说编程。"}, {"text": "他每天练习识字，字越来越漂亮。", "explanation": "这里应该用〈写字〉。识字指认识汉字，练习写出漂亮的字要说写字。"}, {"text": "她毕业后一直从事识字。", "explanation": "这里应该用〈写作〉。识字指学会认字，不是从事写作这类职业活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20298, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "识字", "is_correct": true, "explanation": "识字指学会认字，“五岁就会识字”符合常识，句意通顺。"}, {"text": "开车", "is_correct": false, "explanation": "语义：五岁的孩子不会开车，“五岁就会开车”与句意矛盾。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：五岁的孩子不会结婚，且后面“也能读简单的故事”说的是认字读书，句意不通。"}, {"text": "喝酒", "is_correct": false, "explanation": "语义：五岁的孩子不能喝酒，“五岁就会喝酒”与句意矛盾。"}], "explanations": {"识字": "识字指学会认字，“五岁就会识字”符合常识，句意通顺。", "开车": "语义：五岁的孩子不会开车，“五岁就会开车”与句意矛盾。", "结婚": "语义：五岁的孩子不会结婚，且后面“也能读简单的故事”说的是认字读书，句意不通。", "喝酒": "语义：五岁的孩子不能喝酒，“五岁就会喝酒”与句意矛盾。"}, "sentence_index": 6, "correct_answer": "识字"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她每天在厨房识字，做得一手好菜。", "explanation": "这里应该用〈做饭〉。识字指学会认字，不是做饭；厨房里做菜要说做饭。"}, {"text": "她在小学识字，每天给学生上课。", "explanation": "这里应该用〈教书〉。识字是学会认字，给学生上课是教书，两者不能互换。"}, {"text": "她在舞台上识字，观众很喜欢。", "explanation": "这里应该用〈唱歌〉。识字指学会认字，不是舞台上的表演；舞台上唱歌要说唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20298, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他五岁时已经识字了一些字。", "corrected_sentence": "他五岁时已经识了一些字。", "error_description": "错误在“识字”的离合用法：“识字”是离合词，带宾语时要拆开，应说“识了一些字”，不能说“识字了一些字”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20298, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们识字得很快。", "corrected_sentence": "孩子们识字识得很快。", "error_description": "错误在补语结构：“识字”后接补语时要重复动词，应说“识字识得很快”，少了第二个“识”就不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
