INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20302, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "书店是卖书的地方。", "primary_collocate": null, "pronunciation": "shū diàn", "ipa": "ʂu˥˥ tjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我家旁边有一个书店。", "target_word": "书店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他周末常去书店看书。", "target_word": "书店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家书店的书很多。", "target_word": "书店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店几点关门？", "target_word": "书店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在书店买了两本书。", "target_word": "书店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店里很安静。", "target_word": "书店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈带我去书店买词典。", "target_word": "书店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个书店在地铁站旁边。", "target_word": "书店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在书店工作。", "target_word": "书店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校对面新开了一家书店。", "target_word": "书店", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一家书店", "label": "量词"}, {"form": "网上书店", "label": "复合"}, {"form": "書店", "label": "繁体"}], "register": "中性", "sense_fingerprint": "书店：卖书的商店", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09aebaf0-be95-4ef2-b319-0da839c40a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20302, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "书店", "is_correct": true, "explanation": "书店：卖书的地方，符合“我家旁边有一个……”的句意。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天体，不是可以放在家旁边的店铺。"}, {"text": "树", "is_correct": false, "explanation": "搭配：树要用“棵”，不能说“一个树”。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不是商店，不能位于“我家旁边”。"}], "explanations": {"书店": "书店：卖书的地方，符合“我家旁边有一个……”的句意。", "太阳": "语义：太阳是天体，不是可以放在家旁边的店铺。", "树": "搭配：树要用“棵”，不能说“一个树”。", "月亮": "语义：月亮是天体，不是商店，不能位于“我家旁边”。"}, "sentence_index": 0, "correct_answer": "书店"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我周末常去书店借书。", "explanation": "这里应该用〈图书馆〉。书店是卖书的地方，借书要去图书馆。"}, {"text": "我去书店看病。", "explanation": "这里应该用〈医院〉。看病要去医院，书店不能看病。"}, {"text": "学校旁边有一只书店。", "explanation": "这里应该用〈家〉。店铺用“家”，“只”通常用于动物，不能用于书店。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20302, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书店", "is_correct": true, "explanation": "书店：卖书的地方，符合“妈妈带我去……买词典”的句意。"}, {"text": "饭店", "is_correct": false, "explanation": "语义：饭店不卖词典，去饭店买词典说不通。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院不卖词典，不能去那里买词典。"}, {"text": "朋友", "is_correct": false, "explanation": "配价：“去”后面要接处所，“朋友”不是处所，不能说“去朋友”。"}], "explanations": {"书店": "书店：卖书的地方，符合“妈妈带我去……买词典”的句意。", "饭店": "语义：饭店不卖词典，去饭店买词典说不通。", "医院": "语义：医院不卖词典，不能去那里买词典。", "朋友": "配价：“去”后面要接处所，“朋友”不是处所，不能说“去朋友”。"}, "sentence_index": 6, "correct_answer": "书店"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我去书店剪头发。", "explanation": "这里应该用〈理发店〉。剪头发要去理发店，书店卖书，不办理这项服务。"}, {"text": "我去书店取钱。", "explanation": "这里应该用〈银行〉。取钱要去银行，书店不办理这类业务。"}, {"text": "我去书店买药。", "explanation": "这里应该用〈药店〉。买药要去药店，书店不卖药。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20302, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "商场三楼有一本书店。", "corrected_sentence": "商场三楼有一家书店。", "error_description": "“一本书店”错误，“本”用于书籍，店铺要用“家”，应改为“一家书店”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20302, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈昨天书店买了一套词典。", "corrected_sentence": "妈妈昨天去书店买了一套词典。", "error_description": "“书店买了”错误，表示到某处做事时，“书店”前要加动词“去”，应改为“去书店买了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
