INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20304, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "世界上所有的地方，比如我们住的地球。", "primary_collocate": null, "pronunciation": "shì jiè", "ipa": "ʂɻ̩˥˩ tɕje˥˩", "syllable_count": 2, "sentences": [{"text": "世界很大，我想去看看。", "target_word": "世界", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这是世界上最高的山。", "target_word": "世界", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她坐飞机去过世界的很多地方。", "target_word": "世界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界上有八十多亿人。", "target_word": "世界", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "朋友们来自世界的不同地方，说不同的话。", "target_word": "世界", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教室的墙上挂着一张地图，画的是整个世界。", "target_word": "世界", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个消息很快传遍了世界。", "target_word": "世界", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想坐船看看这个世界。", "target_word": "世界", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学好汉语，你就能坐飞机去看看世界。", "target_word": "世界", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "世界这么大，我们应该多出去走走。", "target_word": "世界", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "世界地图", "label": "复合"}, {"form": "世界各地", "label": "复合"}], "register": "通用", "sense_fingerprint": "名词，指地球上所有的地方和国家，即整个地球", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60fb9430-b8df-4950-a53e-fc0e3676837a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20304, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "世界", "is_correct": true, "explanation": "“世界”指地球上所有的地方，“世界很大”说的是整个地球。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”不能说“很大”，与整句的意思不合。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”说“很高”或“很贵”，不说“很大”。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“作业”说“很多”，不说“很大”。"}], "explanations": {"世界": "“世界”指地球上所有的地方，“世界很大”说的是整个地球。", "时间": "语义：“时间”不能说“很大”，与整句的意思不合。", "价格": "搭配：“价格”说“很高”或“很贵”，不说“很大”。", "作业": "搭配：“作业”说“很多”，不说“很大”。"}, "sentence_index": 0, "correct_answer": "世界"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "北京是世界的首都。", "explanation": "这里不能用〈世界〉。〈世界〉指整个地球，不是国家，没有首都，应说“北京是中国的首都”。"}, {"text": "我们班的世界有四十个学生。", "explanation": "这里应该用〈班级〉。〈世界〉指地球上的所有地方，不能指班级。"}, {"text": "这个国家的世界很大。", "explanation": "这里应该用〈国土〉。〈世界〉指整个地球，不能用来说一个国家的范围。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20304, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "世界", "is_correct": true, "explanation": "“传遍了世界”指消息传到了地球上的各个地方。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“传遍”后接范围大的地方，不接身体器官。"}, {"text": "书包", "is_correct": false, "explanation": "语义：消息能传遍的是地方或人群，“书包”不能被传遍。"}, {"text": "饭", "is_correct": false, "explanation": "语义：“饭”不是消息可以传遍的范围，句子不成立。"}], "explanations": {"世界": "“传遍了世界”指消息传到了地球上的各个地方。", "眼睛": "搭配：“传遍”后接范围大的地方，不接身体器官。", "书包": "语义：消息能传遍的是地方或人群，“书包”不能被传遍。", "饭": "语义：“饭”不是消息可以传遍的范围，句子不成立。"}, "sentence_index": 6, "correct_answer": "世界"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个问题的世界很简单。", "explanation": "这里应该用〈难度〉。〈世界〉指地球上的所有地方，不能用来说问题的难易，应说“这个问题的难度很低”。"}, {"text": "他的世界非常聪明。", "explanation": "这里应该用〈头脑〉。〈世界〉指地球上的所有地方，不能用来形容人的聪明，应说“他的头脑非常聪明”。"}, {"text": "我们开会的世界很长。", "explanation": "这里不能用〈世界〉。〈世界〉不能用来说时间的长短，应说“我们的会议很长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20304, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本世界很大，我们要多学习。", "corrected_sentence": "这个世界很大，我们要多学习。", "error_description": "错误：“世界”的量词用了“本”（这本世界）。正确：应用“个”（这个世界），“本”用于书等物品。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20304, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "世界下有很多不同的国家。", "corrected_sentence": "世界上有很多不同的国家。", "error_description": "方位词错误：表示在地球范围内要说“世界上”，不说“世界下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
