INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20308, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种用来算东西、玩游戏、看动画的机器。", "primary_collocate": null, "pronunciation": "diàn nǎo", "ipa": "tjɛn˥˩ naʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我的电脑坏了。", "target_word": "电脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天用电脑工作。", "target_word": "电脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电脑很新。", "target_word": "电脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下班前别忘了关电脑。", "target_word": "电脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟喜欢用电脑玩游戏。", "target_word": "电脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在电脑上看动画。", "target_word": "电脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一台新电脑。", "target_word": "电脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑里有很多照片。", "target_word": "电脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电脑的屏幕很大。", "target_word": "电脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在电脑上写字。", "target_word": "电脑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一台电脑", "label": "量词"}, {"form": "笔记本电脑", "label": "复合"}, {"form": "電腦", "label": "繁体"}], "register": "中性", "sense_fingerprint": "电脑：用来计算、上网、娱乐的电子机器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09aebaf0-be95-4ef2-b319-0da839c40a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20308, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电脑", "is_correct": true, "explanation": "电脑：用来计算、上网、娱乐的电子机器，可以坏，这里指我的电脑坏了。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天体，不会“坏了”，句子不通。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“坏了”搭配的是器物或机器，不搭配“空气”。"}, {"text": "学生", "is_correct": false, "explanation": "语义：“坏了”用来说器物，不用来说人。"}], "explanations": {"电脑": "电脑：用来计算、上网、娱乐的电子机器，可以坏，这里指我的电脑坏了。", "太阳": "语义：太阳是天体，不会“坏了”，句子不通。", "空气": "搭配：“坏了”搭配的是器物或机器，不搭配“空气”。", "学生": "语义：“坏了”用来说器物，不用来说人。"}, "sentence_index": 0, "correct_answer": "电脑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用电脑洗衣服。", "explanation": "这里应该用〈洗衣机〉。洗衣服要用洗衣机，电脑不能洗衣服。"}, {"text": "我把牛奶放进电脑。", "explanation": "这里应该用〈冰箱〉。放进冰箱是存放食物，电脑不能用来存放牛奶。"}, {"text": "我晚上在电脑上吃饭。", "explanation": "这里应该用〈饭桌〉。吃饭要在饭桌上，电脑不是吃饭的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20308, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电脑", "is_correct": true, "explanation": "电脑：用来计算、上网、娱乐的电子机器，这里指想买的新机器。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：量词“台”不用于房子，房子应说“一套”或“一栋”。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师是人，不是可以买的物件，“买一台新老师”不通。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：量词“台”不用于面包，面包应说“一个”或“一块”。"}], "explanations": {"电脑": "电脑：用来计算、上网、娱乐的电子机器，这里指想买的新机器。", "房子": "搭配：量词“台”不用于房子，房子应说“一套”或“一栋”。", "老师": "语义：老师是人，不是可以买的物件，“买一台新老师”不通。", "面包": "搭配：量词“台”不用于面包，面包应说“一个”或“一块”。"}, "sentence_index": 6, "correct_answer": "电脑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用电脑喝水。", "explanation": "这里应该用〈杯子〉。喝水要用杯子，电脑不能用来盛水。"}, {"text": "他躺在电脑上睡觉。", "explanation": "这里应该用〈床〉。睡觉要躺在床上，不能躺在电脑上。"}, {"text": "妈妈用电脑量体温。", "explanation": "这里应该用〈体温计〉。量体温要用体温计，电脑不是测量体温的工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20308, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了三只电脑。", "corrected_sentence": "我买了三台电脑。", "error_description": "量词错误：“电脑”应用量词“台”，不用“只”。正确：“我买了三台电脑。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20308, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师把电脑关。", "corrected_sentence": "老师把电脑关了。", "error_description": "错误：“把”字句中动词后缺少“了”，句子不完整。正确：“老师把电脑关了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
