INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20312, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小说是讲一个故事的书。", "primary_collocate": null, "pronunciation": "xiǎo shuō", "ipa": "ɕjɑʊ²¹⁴ ʂwo⁵⁵", "syllable_count": 2, "sentences": [{"text": "我喜欢看小说。", "target_word": "小说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本小说讲一个女孩的故事。", "target_word": "小说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了一本很厚的小说。", "target_word": "小说", "complexity_tier": "T3", "furigana": "tā xiě le yì běn hěn hòu de xiǎo shuō", "sentence_source": "generated"}, {"text": "这本小说很长，我看了三天。", "target_word": "小说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看完了那本小说，哭了好久。", "target_word": "小说", "complexity_tier": "T3", "furigana": "tā kàn wán le nà běn xiǎo shuō, kū le hǎo jiǔ", "sentence_source": "generated"}, {"text": "姐姐在图书馆借了两本小说。", "target_word": "小说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在床上看小说，看着看着就睡了。", "target_word": "小说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本小说是中国作家写的。", "target_word": "小说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说里的人很有意思。", "target_word": "小说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友送我一本小说。", "target_word": "小说", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本", "label": "量词"}, {"form": "小說", "label": "繁体"}, {"form": "小说家", "label": "复合"}, {"form": "长篇小说", "label": "复合"}], "register": "中性", "sense_fingerprint": "讲故事的书", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f67254c-2b72-48f7-a62f-6cc95d11eae2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20312, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小说", "is_correct": true, "explanation": "正确：小说是讲故事的书，可以用“看”。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“看”一般不和“声音”搭配，要说“听”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是看不见的气体，不能拿来“看”着读。"}, {"text": "滋味", "is_correct": false, "explanation": "语义：滋味是味道，不是可以用眼睛“看”的东西。"}], "explanations": {"小说": "正确：小说是讲故事的书，可以用“看”。", "声音": "搭配：“看”一般不和“声音”搭配，要说“听”。", "空气": "语义：空气是看不见的气体，不能拿来“看”着读。", "滋味": "语义：滋味是味道，不是可以用眼睛“看”的东西。"}, "sentence_index": 0, "correct_answer": "小说"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只小说。", "explanation": "这里应该用〈本〉。小说是书，量词用“本”，“只”多用于动物。"}, {"text": "姐姐借给我一张小说。", "explanation": "这里应该用〈本〉。“张”用于纸张、桌子等平面的东西，书要用“本”。"}, {"text": "我每天用小说查生词。", "explanation": "这里应该用〈词典〉。小说讲故事，不用来查生词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20312, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小说", "is_correct": true, "explanation": "正确：床上看小说，看着看着就睡了，符合语境。"}, {"text": "节奏", "is_correct": false, "explanation": "搭配：“看”一般不和“节奏”搭配，节奏要用耳朵听。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气是性格表现，不是可以用眼睛“看”的内容。"}, {"text": "香味", "is_correct": false, "explanation": "语义：香味是用鼻子闻的，不能说“在床上看香味”。"}], "explanations": {"小说": "正确：床上看小说，看着看着就睡了，符合语境。", "节奏": "搭配：“看”一般不和“节奏”搭配，节奏要用耳朵听。", "脾气": "语义：脾气是性格表现，不是可以用眼睛“看”的内容。", "香味": "语义：香味是用鼻子闻的，不能说“在床上看香味”。"}, "sentence_index": 6, "correct_answer": "小说"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一位著名的小说。", "explanation": "这里应该用〈作家〉。小说指书，不指人，写书的人要说“作家”或“小说家”。"}, {"text": "我们靠小说找路。", "explanation": "这里应该用〈地图〉。小说是讲故事的书，不能用来指路。"}, {"text": "我每天早上吃小说。", "explanation": "这里应该用〈面包〉。小说是书，不能用“吃”来表示阅读。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20312, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天看了着一本小说。", "corrected_sentence": "我昨天看了一本小说。", "error_description": "体标错误：“了”与“着”不能同时用在同一动词后，应说“看了一本小说”，去掉“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20312, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐给我买了一座小说。", "corrected_sentence": "姐姐给我买了一本小说。", "error_description": "量词错误：小说是书，应用“本”，不能用“座”（“座”用于山、房屋等大型固定的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
