INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20314, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20314, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "还是和以前一样", "primary_collocate": null, "pronunciation": "réng rán", "ipa": "ɻɤŋ˧˥ ɻan˧˥", "syllable_count": 2, "sentences": [{"text": "过了十年，他仍然住在这里。", "target_word": "仍然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天已经黑了，她仍然在工作。", "target_word": "仍然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然很累，他仍然笑着。", "target_word": "仍然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的饭仍然很好吃。", "target_word": "仍然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨很大，比赛仍然开始了。", "target_word": "仍然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我说了很多次，他仍然不明白。", "target_word": "仍然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多年以后，老师仍然记得我。", "target_word": "仍然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生病了，仍然去上班。", "target_word": "仍然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题仍然没有答案。", "target_word": "仍然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她搬家以后，我们仍然是好朋友。", "target_word": "仍然", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "情况没有改变，和以前一样继续", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b8f789-626d-40d7-a308-633398a91259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20314, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”指不久前，与“过了十年”的时间跨度矛盾。"}, {"text": "仍然", "is_correct": true, "explanation": "仍然表示情况没有改变，与“过了十年”相符，他一直住在这里。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示即将发生，与“过了十年”的回顾语境矛盾。"}, {"text": "突然", "is_correct": false, "explanation": "搭配：“突然”修饰瞬间发生的动作，不修饰“住”这种长期状态。"}], "explanations": {"刚刚": "语义：“刚刚”指不久前，与“过了十年”的时间跨度矛盾。", "仍然": "仍然表示情况没有改变，与“过了十年”相符，他一直住在这里。", "马上": "语义：“马上”表示即将发生，与“过了十年”的回顾语境矛盾。", "突然": "搭配：“突然”修饰瞬间发生的动作，不修饰“住”这种长期状态。"}, "sentence_index": 0, "correct_answer": "仍然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他仍然搬走了，没有告诉我。", "explanation": "这里应该用〈竟然〉。“仍然”表示情况没有改变，“搬走”是变化，要用“竟然”表示出乎意料。"}, {"text": "他仍然昨天才搬来这里。", "explanation": "这里应该去掉〈仍然〉。“仍然”表示情况延续，与表示新近发生的“昨天才搬来”矛盾。"}, {"text": "他仍然上个月才开始学习英语。", "explanation": "这里应该去掉〈仍然〉。“仍然”表示情况没有改变、一直延续，与表示最近才开始的“上个月才开始”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20314, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”指马上，与“多年以后”的时间跨度矛盾。"}, {"text": "仍然", "is_correct": true, "explanation": "仍然表示长期的状态延续，与“多年以后”呼应，老师一直记得我。"}, {"text": "刚才", "is_correct": false, "explanation": "语义：“刚才”指不久前，与“多年以后”矛盾。"}, {"text": "当场", "is_correct": false, "explanation": "搭配：“当场”指在场的当时，不修饰“记得”这种回忆状态。"}], "explanations": {"立刻": "语义：“立刻”指马上，与“多年以后”的时间跨度矛盾。", "仍然": "仍然表示长期的状态延续，与“多年以后”呼应，老师一直记得我。", "刚才": "语义：“刚才”指不久前，与“多年以后”矛盾。", "当场": "搭配：“当场”指在场的当时，不修饰“记得”这种回忆状态。"}, "sentence_index": 6, "correct_answer": "仍然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "消防队员仍然刚刚赶到了现场。", "explanation": "这里应该去掉〈仍然〉。“仍然”表示情况延续，与表示新近发生的“刚刚赶到”矛盾。"}, {"text": "他仍然刚学会游泳。", "explanation": "这里应该去掉〈仍然〉。“仍然”表示情况延续，与表示新近发生的“刚学会”矛盾。"}, {"text": "病人仍然刚刚入院。", "explanation": "这里应该去掉〈仍然〉。“仍然”表示情况延续，与表示新近发生的“刚刚入院”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20314, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他仍然地在那家公司工作。", "corrected_sentence": "他仍然在那家公司工作。", "error_description": "词性错误：“仍然”已是副词，后面不能再加“地”，应说“他仍然在那家公司工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20314, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条路仍然了很堵。", "corrected_sentence": "这条路仍然很堵。", "error_description": "体标错误：“仍然”后不能直接加“了”，“了”多余，应说“这条路仍然很堵”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
