INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20316, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "专门就是特意去做一件事。", "primary_collocate": null, "pronunciation": "zhuān mén", "ipa": "ʈʂwan˥ mən˧˥", "syllable_count": 2, "sentences": [{"text": "我专门去机场接你。", "target_word": "专门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈专门为我做了一碗面。", "target_word": "专门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他专门坐火车来看奶奶。", "target_word": "专门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他专门从北京赶来参加我的婚礼。", "target_word": "专门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师专门留下来帮我学汉字。", "target_word": "专门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我专门买了一本书送给朋友。", "target_word": "专门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了见你，他专门请了一天假。", "target_word": "专门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她专门带着地图来找这家店。", "target_word": "专门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司专门为老人开了一个小班。", "target_word": "专门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他专门打电话告诉我这个好消息。", "target_word": "专门", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "特意为某事而做，不是顺便", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '352aafc0-c763-41dd-ae5f-940379d8e408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20316, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "专门", "is_correct": true, "explanation": "正确：“专门”表示特意为某事而做，“我专门去机场接你”即为了接你而去。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”修饰形容词或心理动词，不能修饰“去”这样的动作。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”通常修饰形容词，不能直接修饰“去”。"}, {"text": "渐渐", "is_correct": false, "explanation": "语义：“渐渐”指逐步变化，接人是一次完成的动作，句意不合。"}], "explanations": {"专门": "正确：“专门”表示特意为某事而做，“我专门去机场接你”即为了接你而去。", "非常": "搭配：“非常”修饰形容词或心理动词，不能修饰“去”这样的动作。", "很": "搭配：“很”通常修饰形容词，不能直接修饰“去”。", "渐渐": "语义：“渐渐”指逐步变化，接人是一次完成的动作，句意不合。"}, "sentence_index": 0, "correct_answer": "专门"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他专门打了个喷嚏。", "explanation": "这里应该用〈不由自主〉。“专门”表示有意去做，打喷嚏是不由自主的，不能用“专门”。"}, {"text": "这棵树专门长高了一米。", "explanation": "这里应该用〈慢慢〉。“专门”表示有意去做，树木长高是自然的过程，不能说“专门长高”，应该用“慢慢”。"}, {"text": "这场雨专门下了一整天。", "explanation": "这里应该用〈一直〉。“专门”表示有意去做，下雨是自然现象，不能说“专门下”，持续的状态用“一直”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20316, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "专门", "is_correct": true, "explanation": "正确：“专门”表示有目的地特意去做，与“为了见你”相合。"}, {"text": "顺便", "is_correct": false, "explanation": "语义：“顺便”表示顺带去做，与“为了见你”的明确目的矛盾。"}, {"text": "恰好", "is_correct": false, "explanation": "语义：“恰好”表示碰巧，与“为了见你”的有意安排不符。"}, {"text": "千万", "is_correct": false, "explanation": "搭配：“千万”多用于劝告或命令，不能修饰已经发生的“请假”。"}], "explanations": {"专门": "正确：“专门”表示有目的地特意去做，与“为了见你”相合。", "顺便": "语义：“顺便”表示顺带去做，与“为了见你”的明确目的矛盾。", "恰好": "语义：“恰好”表示碰巧，与“为了见你”的有意安排不符。", "千万": "搭配：“千万”多用于劝告或命令，不能修饰已经发生的“请假”。"}, "sentence_index": 6, "correct_answer": "专门"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们专门在车站遇见了。", "explanation": "这里应该用〈正好〉。“专门”强调有意去做，遇见是偶然的，应该用“正好”。"}, {"text": "他专门心跳加快了。", "explanation": "这里应该用〈不由自主地〉。“专门”表示有意去做，心跳加快是不由自主的，不能用“专门”。"}, {"text": "我们到的时候，电影专门开始了。", "explanation": "这里应该用〈恰好〉。“专门”表示有意去做，电影开始是时间上的凑巧，不能用“专门”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20316, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他专门的买了一台相机。", "corrected_sentence": "他专门买了一台相机。", "error_description": "“专门”是副词，后面不能加“的”（“专门的”是形容词，修饰名词）。错误形式是“专门的买了”，正确形式是“专门买了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20316, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们很专门去看了那场比赛。", "corrected_sentence": "我们专门去看了那场比赛。", "error_description": "错误：表示“特意去做”的副词“专门”不能被程度副词“很”修饰，应删去“很”。正确：“我们专门去看了那场比赛”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
