INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20318, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做事情的办法。", "primary_collocate": null, "pronunciation": "fāng shì", "ipa": "faŋ⁵⁵ ʂʅ⁵¹", "syllable_count": 2, "sentences": [{"text": "每个人学习的方式都不一样。", "target_word": "方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢用写信的方式表达爱。", "target_word": "方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种生活方式对身体很好。", "target_word": "方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "付款方式有现金和手机支付两种。", "target_word": "方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师换了一种教学方式，学生更爱听课了。", "target_word": "方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用开玩笑的方式把问题说清楚了。", "target_word": "方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母和孩子的相处方式很重要。", "target_word": "方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不同意他处理问题的方式。", "target_word": "方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐火车是最省钱的出行方式。", "target_word": "方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用这种方式解决了问题。", "target_word": "方式", "complexity_tier": "T3", "furigana": "fāngshì", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "生活方式", "label": "复合"}, {"form": "思维方式", "label": "复合"}], "register": "中性", "sense_fingerprint": "做事、表达、生活所采用的办法或形式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T1: 3 words above tier T1 (max 2): 坐火车 (Zipf 3.01), 省钱 (Zipf 3.52), 出行 (Zipf 3.87)']::text[], '3f67254c-2b72-48f7-a62f-6cc95d11eae2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20318, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "方式", "is_correct": true, "explanation": "正确。“方式”指做事的办法，与“学习的”搭配，表示每人学习的做法不同。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，不能用来指学习的做法，与句意不符。"}, {"text": "鼻子", "is_correct": false, "explanation": "语义：“鼻子”是身体部位，不能指学习的做法，“学习的鼻子”说不通。"}, {"text": "房子", "is_correct": false, "explanation": "语义：“房子”指建筑，不是学习的做法，与句意不符。"}], "explanations": {"方式": "正确。“方式”指做事的办法，与“学习的”搭配，表示每人学习的做法不同。", "颜色": "语义：“颜色”指色彩，不能用来指学习的做法，与句意不符。", "鼻子": "语义：“鼻子”是身体部位，不能指学习的做法，“学习的鼻子”说不通。", "房子": "语义：“房子”指建筑，不是学习的做法，与句意不符。"}, "sentence_index": 0, "correct_answer": "方式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的方式很大，一顿能吃三碗。", "explanation": "这里应该用〈饭量〉。“方式”指做事的办法，说吃得多少要用“饭量”。"}, {"text": "他找到了一只方式解决问题。", "explanation": "这里应该用〈种〉。“只”多用于动物或成对物品中的一个，“方式”要用量词“种”。"}, {"text": "这辆车的方式很快。", "explanation": "这里应该用〈速度〉。“方式”指做法，说快慢要用“速度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20318, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "方式", "is_correct": true, "explanation": "正确。“方式”指相处的做法，与“相处”搭配，句意通顺。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指身体的重量，不能用来说人与人相处的做法。"}, {"text": "亮度", "is_correct": false, "explanation": "搭配：“亮度”多用于光线或屏幕，不能说“相处亮度”。"}, {"text": "手指", "is_correct": false, "explanation": "语义：“手指”是身体部位，不能指相处的方式，与句意不符。"}], "explanations": {"方式": "正确。“方式”指相处的做法，与“相处”搭配，句意通顺。", "体重": "语义：“体重”指身体的重量，不能用来说人与人相处的做法。", "亮度": "搭配：“亮度”多用于光线或屏幕，不能说“相处亮度”。", "手指": "语义：“手指”是身体部位，不能指相处的方式，与句意不符。"}, "sentence_index": 6, "correct_answer": "方式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个房间的方式有二十平方米。", "explanation": "这里应该用〈面积〉。“方式”指做事的办法，房间的大小要用“面积”。"}, {"text": "我的鞋子方式是四十三码。", "explanation": "这里应该用〈尺码〉。“方式”指做法，鞋的大小要用“尺码”。"}, {"text": "他的方式是一米八。", "explanation": "这里应该用〈身高〉。“方式”指做事的办法，说人的高矮要用“身高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20318, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们用不同地方式学习。", "corrected_sentence": "他们用不同的方式学习。", "error_description": "“不同”修饰名词“方式”时，中间应用“的”，不用“地”。“地”用于修饰动词或形容词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20318, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父母用这么方式教育孩子。", "corrected_sentence": "父母用这种方式教育孩子。", "error_description": "“方式”前的指示代词应用“这种”，不用“这么”。“这么”修饰形容词或动词，不修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
