INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20322, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "印刷技术就是用来印出很多一样图画或文字的方法。", "primary_collocate": null, "pronunciation": "yìn shuā jì shù", "ipa": "in˥˩ ʂwa˥ tɕi˥˩ ʂu˥˩", "syllable_count": 4, "sentences": [{"text": "印刷技术很重要。", "target_word": "印刷技术", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "中国人发明了印刷技术。", "target_word": "印刷技术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有了印刷技术，书就多了。", "target_word": "印刷技术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司的印刷技术很好。", "target_word": "印刷技术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "印刷技术让报纸便宜了。", "target_word": "印刷技术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在学校学习印刷技术。", "target_word": "印刷技术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人用印刷技术大量生产书籍。", "target_word": "印刷技术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现代印刷技术可以印出很漂亮的图画。", "target_word": "印刷技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为有印刷技术，很多人都能买到书。", "target_word": "印刷技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想了解一下印刷技术是怎么发展的。", "target_word": "印刷技术", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词：大量复制图画和文字的技术方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9421cf6-24de-499f-a0bb-a94d3893ac19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20322, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "印刷技术", "is_correct": true, "explanation": "正确。“印刷技术”是技术概念，可以作主语说“很重要”。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾通常不被说成“很重要”，与常理不合。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：小偷不是值得称赞“很重要”的对象，这句话的意思不合常理。"}, {"text": "噪音", "is_correct": false, "explanation": "语义：噪音是让人不舒服的声音，通常不说噪音很重要。"}], "explanations": {"印刷技术": "正确。“印刷技术”是技术概念，可以作主语说“很重要”。", "垃圾": "语义：垃圾通常不被说成“很重要”，与常理不合。", "小偷": "语义：小偷不是值得称赞“很重要”的对象，这句话的意思不合常理。", "噪音": "语义：噪音是让人不舒服的声音，通常不说噪音很重要。"}, "sentence_index": 0, "correct_answer": "印刷技术"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅的印刷技术很好吃。", "explanation": "这里应该用〈菜〉。“好吃”形容食物，印刷技术是方法，不能说好吃。"}, {"text": "他每天擦印刷技术。", "explanation": "这里应该用〈桌子〉。“擦”的对象是有形的物体，印刷技术是方法，不能擦。"}, {"text": "他把印刷技术搬到了仓库。", "explanation": "这里应该用〈机器〉。“搬”的对象是有形的机器，印刷技术是方法，不能搬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20322, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "印刷技术", "is_correct": true, "explanation": "正确。“大量生产书籍”需要能大量复制文字的方法，“印刷技术”符合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是生产书籍的方法，不能用来大量生产书籍。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：午饭是一顿饭，不是生产书籍的手段，句子说不通。"}, {"text": "麻袋", "is_correct": false, "explanation": "语义：麻袋是盛物的口袋，不能用来大量生产书籍。"}], "explanations": {"印刷技术": "正确。“大量生产书籍”需要能大量复制文字的方法，“印刷技术”符合。", "天气": "语义：天气不是生产书籍的方法，不能用来大量生产书籍。", "午饭": "语义：午饭是一顿饭，不是生产书籍的手段，句子说不通。", "麻袋": "语义：麻袋是盛物的口袋，不能用来大量生产书籍。"}, "sentence_index": 6, "correct_answer": "印刷技术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的印刷技术很热情。", "explanation": "这里应该用〈人〉。“热情”形容人的态度，印刷技术是方法，不能说热情。"}, {"text": "我每天穿印刷技术。", "explanation": "这里应该用〈衣服〉。“穿”的对象是衣服，印刷技术是方法，不能穿。"}, {"text": "我们在印刷技术上课。", "explanation": "这里应该用〈教室〉。“上课”的地点应是教室等场所，印刷技术不是地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20322, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他掌握了一只印刷技术。", "corrected_sentence": "他掌握了一项印刷技术。", "error_description": "量词错误：“技术”应用“项”，“只”用于动物等，不能修饰“技术”。错误形式是“一只印刷技术”，正确形式是“一项印刷技术”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20322, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前学过印刷技术过。", "corrected_sentence": "我以前学过印刷技术。", "error_description": "重复体标：经历体“过”已紧跟动词“学”，宾语后不能再加“过”。错误形式是“学过印刷技术过”，只多出一个“过”；正确形式是“学过印刷技术”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
