INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20324, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示事情一定，没有疑问。", "primary_collocate": null, "pronunciation": "wú yí", "ipa": "u˧˥ i˧˥", "syllable_count": 2, "sentences": [{"text": "他无疑是我们班最高的学生。", "target_word": "无疑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事无疑很难，但我们要试一试。", "target_word": "无疑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样做无疑是对的。", "target_word": "无疑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她唱得这么好，无疑会得第一名。", "target_word": "无疑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对孩子来说，读书无疑很重要。", "target_word": "无疑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法无疑比那个办法好。", "target_word": "无疑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天这么黑，无疑要下雨了。", "target_word": "无疑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他无疑是个好老师。", "target_word": "无疑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "无疑，这是今年最好的电影。", "target_word": "无疑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多吃水果无疑对身体好。", "target_word": "无疑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "副词，表示确定、没有疑问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05710f7d-b7af-44a9-a7be-d2504441099b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20324, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "无疑", "is_correct": true, "explanation": "wú yí（第二声）意思是事情一定，没有疑问，表示确定。"}, {"text": "无意", "is_correct": false, "explanation": "wú yì（第四声）与 wú yí（第二声）第二音节声调不同，意思是不是有意的。"}, {"text": "无益", "is_correct": false, "explanation": "wú yì（第四声）与 wú yí（第二声）第二音节声调不同，意思是没有好处。"}, {"text": "武艺", "is_correct": false, "explanation": "wǔ yì（第三、四声）与 wú yí（第二、二声）两个音节的声调都不同，意思是武术的技艺。"}, {"text": "五一", "is_correct": false, "explanation": "wǔ yī（第三、一声）与 wú yí（第二、二声）两个音节的声调都不同，意思是五月一日，即劳动节。"}], "explanations": {"无疑": "wú yí（第二声）意思是事情一定，没有疑问，表示确定。", "无意": "wú yì（第四声）与 wú yí（第二声）第二音节声调不同，意思是不是有意的。", "无益": "wú yì（第四声）与 wú yí（第二声）第二音节声调不同，意思是没有好处。", "武艺": "wǔ yì（第三、四声）与 wú yí（第二、二声）两个音节的声调都不同，意思是武术的技艺。", "五一": "wǔ yī（第三、一声）与 wú yí（第二、二声）两个音节的声调都不同，意思是五月一日，即劳动节。"}, "sentence_index": null, "correct_answer": "无疑"}, "level_3": {"options": [{"text": "无疑", "is_correct": true, "explanation": "正确：「无疑」表示确定没有疑问，与句中“他是我们班最高的学生”这一肯定判断相符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：「偶尔」表示间或、不常发生，与“是最高的学生”这种稳定的判断矛盾。"}, {"text": "渐渐", "is_correct": false, "explanation": "体貌：「渐渐」表示逐步变化的过程，句中是静态的身份判断，不能说“渐渐是……”。"}, {"text": "差点", "is_correct": false, "explanation": "语义：「差点」表示几乎发生却没有发生，与肯定的判断“是最高的学生”相反。"}], "explanations": {"无疑": "正确：「无疑」表示确定没有疑问，与句中“他是我们班最高的学生”这一肯定判断相符。", "偶尔": "语义：「偶尔」表示间或、不常发生，与“是最高的学生”这种稳定的判断矛盾。", "渐渐": "体貌：「渐渐」表示逐步变化的过程，句中是静态的身份判断，不能说“渐渐是……”。", "差点": "语义：「差点」表示几乎发生却没有发生，与肯定的判断“是最高的学生”相反。"}, "sentence_index": 0, "correct_answer": "无疑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我也不太清楚，他无疑是老师。", "explanation": "这里应该用〈也许〉。“不太清楚”表示不确定，「无疑」表示确定，二者矛盾，不确定时要用〈也许〉。"}, {"text": "我们明天无疑去爬山，如果天气好的话。", "explanation": "这里应该用〈可能〉。「无疑」断定一定会发生，不能用于“如果天气好的话”这类有条件的设想。"}, {"text": "我恐怕无疑要迟到了。", "explanation": "这里不能用〈无疑〉。句中表示担心的语气是不确定的，而「无疑」表示确定、没有疑问，应换成〈很可能〉，表示推测而非确定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '435200ee-fff5-4965-8391-ccfd57e61a1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20324, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "无疑", "is_correct": true, "explanation": "wú yí（第二声）意思是事情一定，没有疑问，表示确定。"}, {"text": "无异", "is_correct": false, "explanation": "wú yì（第四声）与 wú yí（第二声）第二音节声调不同，意思是没有差别。"}, {"text": "无依", "is_correct": false, "explanation": "wú yī（第一声）与 wú yí（第二声）第二音节声调不同，意思是没有依靠。"}, {"text": "舞衣", "is_correct": false, "explanation": "wǔ yī（第三、一声）与 wú yí（第二、二声）两个音节的声调都不同，意思是跳舞时穿的衣服。"}], "explanations": {"无疑": "wú yí（第二声）意思是事情一定，没有疑问，表示确定。", "无异": "wú yì（第四声）与 wú yí（第二声）第二音节声调不同，意思是没有差别。", "无依": "wú yī（第一声）与 wú yí（第二声）第二音节声调不同，意思是没有依靠。", "舞衣": "wǔ yī（第三、一声）与 wú yí（第二、二声）两个音节的声调都不同，意思是跳舞时穿的衣服。"}, "sentence_index": null, "correct_answer": "无疑"}, "level_3": {"options": [{"text": "无疑", "is_correct": true, "explanation": "正确：「无疑」表示确定会发生，符合“天这么黑”推出“要下雨了”的判断。"}, {"text": "曾经", "is_correct": false, "explanation": "体貌：「曾经」表示过去的经历，与“要下雨了”指向将来的情况冲突。"}, {"text": "从来", "is_correct": false, "explanation": "语义：「从来」表示一直如此或从未如此，与眼前即将发生的降雨不合。"}, {"text": "从前", "is_correct": false, "explanation": "时间：「从前」指过去，与“要下雨了”指向将来的情况矛盾。"}], "explanations": {"无疑": "正确：「无疑」表示确定会发生，符合“天这么黑”推出“要下雨了”的判断。", "曾经": "体貌：「曾经」表示过去的经历，与“要下雨了”指向将来的情况冲突。", "从来": "语义：「从来」表示一直如此或从未如此，与眼前即将发生的降雨不合。", "从前": "时间：「从前」指过去，与“要下雨了”指向将来的情况矛盾。"}, "sentence_index": 6, "correct_answer": "无疑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明天我们无疑去看电影吧。", "explanation": "这里应该用〈不如〉。「无疑」表示事情确定，不能用于商量或提议，提建议要用〈不如〉。"}, {"text": "你无疑喜欢这部电影？", "explanation": "这里应该用〈是不是〉。「无疑」表示确定的判断，不能用于疑问句，询问对方的看法要用〈是不是〉。"}, {"text": "我猜这座城市无疑有两百万人。", "explanation": "这里应该用〈大概〉。「猜」表示推测，语气不确定，而「无疑」表示确定，二者矛盾，应换成〈大概〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '435200ee-fff5-4965-8391-ccfd57e61a1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20324, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次比赛，他无疑的会赢。", "corrected_sentence": "这次比赛，他无疑会赢。", "error_description": "错误：「无疑」作副词修饰动词「会」，其后不能加结构助词「的」（「无疑的」是形容词用法，如「无疑的胜利」）。正确：“他无疑会赢”，「无疑」置于主语之后、助动词「会」之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '435200ee-fff5-4965-8391-ccfd57e61a1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20324, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这道题无疑了很难，我们都做不出来。", "corrected_sentence": "这道题无疑很难，我们都做不出来。", "error_description": "错误：副词「无疑」后面不能直接加动态助词「了」，“无疑了很难”不通。正确：“这道题无疑很难”，「无疑」修饰整个句子，后面直接接“很难”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '435200ee-fff5-4965-8391-ccfd57e61a1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20326, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20326, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20326, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用眼睛仔细看，发现东西。", "primary_collocate": null, "pronunciation": "guān chá", "ipa": "kwan˥ ʈʂʰɑ˧˥", "syllable_count": 2, "sentences": [{"text": "小明每天观察小鸟怎么吃东西。", "target_word": "观察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生仔细观察了他的眼睛。", "target_word": "观察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在晚上观察月亮的变化。", "target_word": "观察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子趴在地上，观察一只小虫子。", "target_word": "观察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们观察这朵花的颜色。", "target_word": "观察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在窗边，观察着外面的人。", "target_word": "观察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家观察这些小鱼已经一个月了。", "target_word": "观察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你观察一下，这两个字有什么不同？", "target_word": "观察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先观察路上的车，然后才过马路。", "target_word": "观察", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很会观察，一眼就看出我不高兴。", "target_word": "观察", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "观察了", "label": "完成体"}, {"form": "观察着", "label": "持续体"}, {"form": "观察过", "label": "经历体"}, {"form": "观察员", "label": "复合词"}], "register": "中性", "sense_fingerprint": "仔细地看，为了发现情况或变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b8f789-626d-40d7-a308-633398a91259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20326, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "观察", "is_correct": true, "explanation": "正确：“观察”指仔细看以了解情况，与“小鸟怎么吃东西”相合。"}, {"text": "收拾", "is_correct": false, "explanation": "语义：“收拾”指整理，不能用来说看小鸟的进食。"}, {"text": "搬", "is_correct": false, "explanation": "配价：“搬”的宾语应是具体的物品，不能接“小鸟怎么吃东西”这样的小句。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象应是食物，不能说煮“小鸟怎么吃东西”。"}], "explanations": {"观察": "正确：“观察”指仔细看以了解情况，与“小鸟怎么吃东西”相合。", "收拾": "语义：“收拾”指整理，不能用来说看小鸟的进食。", "搬": "配价：“搬”的宾语应是具体的物品，不能接“小鸟怎么吃东西”这样的小句。", "煮": "搭配：“煮”的对象应是食物，不能说煮“小鸟怎么吃东西”。"}, "sentence_index": 0, "correct_answer": "观察"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我去邮局观察了一封信。", "explanation": "这里应该用〈寄〉。“观察”是仔细看以发现情况，寄信要用〈寄〉。"}, {"text": "他在舞台上观察了一首歌。", "explanation": "这里应该用〈唱〉。“观察”指仔细看事物，唱歌要用〈唱〉。"}, {"text": "妈妈用鼻子观察了这锅汤的香味。", "explanation": "这里应该用〈闻〉。“观察”依靠眼睛仔细看，辨别香味要用〈闻〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20326, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "观察", "is_correct": true, "explanation": "正确：“观察”可以持续一段时间，与“已经一个月了”相合。"}, {"text": "发明", "is_correct": false, "explanation": "语义：小鱼是已经存在的生物，不能说被发明。"}, {"text": "修理", "is_correct": false, "explanation": "配价：“修理”的宾语应是机器或器物，不能用于活的小鱼。"}, {"text": "煎", "is_correct": false, "explanation": "语义：煎鱼的过程通常很短，不能持续一个月。"}], "explanations": {"观察": "正确：“观察”可以持续一段时间，与“已经一个月了”相合。", "发明": "语义：小鱼是已经存在的生物，不能说被发明。", "修理": "配价：“修理”的宾语应是机器或器物，不能用于活的小鱼。", "煎": "语义：煎鱼的过程通常很短，不能持续一个月。"}, "sentence_index": 6, "correct_answer": "观察"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下午我在图书馆观察了一本历史书。", "explanation": "这里应该用〈阅读〉。“观察”强调亲眼仔细看以发现情况，读书要用〈阅读〉。"}, {"text": "妈妈让我观察这道菜的味道。", "explanation": "这里应该用〈品尝〉。“观察”依靠视觉，判断味道要用〈品尝〉。"}, {"text": "妈妈认真观察了我的歌声。", "explanation": "这里应该用〈欣赏〉。“观察”依靠眼睛看，听歌声要用〈欣赏〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20326, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我观察很清楚。", "corrected_sentence": "我观察得很清楚。", "error_description": "错误：“观察”后带补语“很清楚”时漏掉了“得”。“得”用来引出补语，正确应为“观察得很清楚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20326, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我观察了过这种鸟。", "corrected_sentence": "我观察过这种鸟。", "error_description": "错误：“观察”后已用“过”表示经历，又加了“了”，“了”和“过”不能同时用。正确应为“观察过这种鸟”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
