INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20328, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "东西在镜子或照片里看起来的样子。", "primary_collocate": null, "pronunciation": "chéng xiàng", "ipa": "ʈʂʰɤŋ˧˥ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这部手机的成像很清楚，夜里也不模糊。", "target_word": "成像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这面镜子的成像有点歪。", "target_word": "成像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新相机的成像比旧的好多了。", "target_word": "成像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片的成像太暗，什么都看不清。", "target_word": "成像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个镜头的成像很漂亮，人物特别清楚。", "target_word": "成像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水面不平，所以水里的成像一直在晃动。", "target_word": "成像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哈哈镜的成像又胖又矮，大家都笑了。", "target_word": "成像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买手机主要看成像好不好。", "target_word": "成像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧相机的成像不太好，拍出来的照片很模糊。", "target_word": "成像", "complexity_tier": "T3", "furigana": "jiù xiàngjī de chéngxiàng bù tài hǎo, pāi chūlai de zhàopiàn hěn móhu.", "sentence_source": "generated"}, {"text": "这台相机的成像又大又清楚，连远处的字都看得见。", "target_word": "成像", "complexity_tier": "T3", "furigana": "zhè tái xiàngjī de chéngxiàng yòu dà yòu qīngchu, lián yuǎnchù de zì dōu kàn de jiàn.", "sentence_source": "generated"}], "morphological_forms": [{"form": "成像仪", "label": "复合"}, {"form": "成像质量", "label": "复合"}], "register": "口语", "sense_fingerprint": "东西在镜子、照片或屏幕里呈现出的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a1e58b4-b32d-462a-a4f9-a33161b902c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20328, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "成像", "is_correct": true, "explanation": "成像：镜子、照片或屏幕里东西呈现的样子，即本词的读音和意思。"}, {"text": "城乡", "is_correct": false, "explanation": "xiāng（第一声）与 xiàng（第四声）声调不同，意思是城市与农村。"}, {"text": "呈现", "is_correct": false, "explanation": "xiàn 与 xiàng 韵尾不同（-n 与 -ng），意思是显现出来。"}, {"text": "承想", "is_correct": false, "explanation": "xiǎng（第三声）与 xiàng（第四声）声调不同，意思是没有想到。"}, {"text": "成效", "is_correct": false, "explanation": "xiào 与 xiàng 韵母不同，意思是效果、成果。"}], "explanations": {"成像": "成像：镜子、照片或屏幕里东西呈现的样子，即本词的读音和意思。", "城乡": "xiāng（第一声）与 xiàng（第四声）声调不同，意思是城市与农村。", "呈现": "xiàn 与 xiàng 韵尾不同（-n 与 -ng），意思是显现出来。", "承想": "xiǎng（第三声）与 xiàng（第四声）声调不同，意思是没有想到。", "成效": "xiào 与 xiàng 韵母不同，意思是效果、成果。"}, "sentence_index": null, "correct_answer": "成像"}, "level_3": {"options": [{"text": "成像", "is_correct": true, "explanation": "成像：手机拍出的画面效果，与“清楚、不模糊”相合。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“清楚”“模糊”不能用来形容价格。"}, {"text": "电量", "is_correct": false, "explanation": "搭配：电量不用“清楚”“模糊”来描述。"}, {"text": "外观", "is_correct": false, "explanation": "语义：外观指外形，夜里是否模糊不是它的特征，与后句不相合。"}], "explanations": {"成像": "成像：手机拍出的画面效果，与“清楚、不模糊”相合。", "价格": "搭配：“清楚”“模糊”不能用来形容价格。", "电量": "搭配：电量不用“清楚”“模糊”来描述。", "外观": "语义：外观指外形，夜里是否模糊不是它的特征，与后句不相合。"}, "sentence_index": 0, "correct_answer": "成像"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部手机的成像很轻，拿在手里很舒服。", "explanation": "这里应该用〈重量〉。“成像”指镜子、照片或屏幕里东西的样子，不能用来说物体的轻重。"}, {"text": "这张桌子的成像很便宜，我买下了。", "explanation": "这里应该用〈价格〉。“成像”指镜子、照片或屏幕里东西的样子，不能用来说家具的价钱。"}, {"text": "这段音乐的成像很动听，我每天都听。", "explanation": "这里应该用〈音质〉。“成像”指镜子、照片或屏幕里东西的样子，不能用来形容声音好听与否。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10dc944a-10d1-46c4-9ef6-f1fe938a86b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20328, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "成像", "is_correct": true, "explanation": "成像：镜子、照片或屏幕里东西呈现的样子，即本词的读音和意思。"}, {"text": "呈祥", "is_correct": false, "explanation": "xiáng（第二声）与 xiàng（第四声）声调不同，意思是呈现吉祥。"}, {"text": "成想", "is_correct": false, "explanation": "xiǎng（第三声）与 xiàng（第四声）声调不同，意思是料到、想到（多用于否定）。"}, {"text": "长项", "is_correct": false, "explanation": "cháng 与 chéng 韵母不同（ang 与 eng），意思是擅长的方面、长处。"}], "explanations": {"成像": "成像：镜子、照片或屏幕里东西呈现的样子，即本词的读音和意思。", "呈祥": "xiáng（第二声）与 xiàng（第四声）声调不同，意思是呈现吉祥。", "成想": "xiǎng（第三声）与 xiàng（第四声）声调不同，意思是料到、想到（多用于否定）。", "长项": "cháng 与 chéng 韵母不同（ang 与 eng），意思是擅长的方面、长处。"}, "sentence_index": null, "correct_answer": "成像"}, "level_3": {"options": [{"text": "成像", "is_correct": true, "explanation": "成像：哈哈镜里人或物的样子，与“又胖又矮”相合。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指性格，不能用“胖”“矮”来形容。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：颜色不用“胖”“矮”来描述。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：年龄不说“又胖又矮”，与后句的描述不相合。"}], "explanations": {"成像": "成像：哈哈镜里人或物的样子，与“又胖又矮”相合。", "脾气": "语义：“脾气”指性格，不能用“胖”“矮”来形容。", "颜色": "搭配：颜色不用“胖”“矮”来描述。", "年龄": "搭配：年龄不说“又胖又矮”，与后句的描述不相合。"}, "sentence_index": 6, "correct_answer": "成像"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "饭菜的成像很香，我都馋了。", "explanation": "这里应该用〈味道〉。“成像”指画面的样子，不能用来描述饭菜的香气。"}, {"text": "他对工作的成像很认真。", "explanation": "这里应该用〈态度〉。“成像”不表示人的做事态度，只指镜子、照片或屏幕里呈现的样子。"}, {"text": "这次假期的成像很长。", "explanation": "这里应该用〈时长〉。“成像”指镜子、照片或屏幕里东西的样子，不能用来说假期的长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10dc944a-10d1-46c4-9ef6-f1fe938a86b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20328, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个镜头的成像了边缘有点模糊。", "corrected_sentence": "这个镜头的成像边缘有点模糊。", "error_description": "错误形式：“成像了边缘”；正确形式：“成像边缘”。“成像”作定语修饰“边缘”时，中间不能插入“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10dc944a-10d1-46c4-9ef6-f1fe938a86b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20328, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买手机主要看成像的的清楚程度。", "corrected_sentence": "我买手机主要看成像的清楚程度。", "error_description": "错误形式：“成像的的清楚程度”，“的”重复；正确形式：“成像的清楚程度”。只多出一个“的”，去掉即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10dc944a-10d1-46c4-9ef6-f1fe938a86b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20330, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分散", "is_correct": false, "explanation": "“分散”指分开、不集中，与“步调一致”没有对立关系，不是“同步”的反义词。"}, {"text": "异步", "is_correct": true, "explanation": "“异步”与“同步”相对，指步调不一致、不同时进行。"}, {"text": "停止", "is_correct": false, "explanation": "“停止”指不再进行，与“步调一致地同时进行”不构成反义关系。"}, {"text": "离开", "is_correct": false, "explanation": "“离开”指离去，与“同步”的步调一致没有对立关系。"}], "correct_answer": "异步", "explanations": {"分散": "“分散”指分开、不集中，与“步调一致”没有对立关系，不是“同步”的反义词。", "异步": "“异步”与“同步”相对，指步调不一致、不同时进行。", "停止": "“停止”指不再进行，与“步调一致地同时进行”不构成反义关系。", "离开": "“离开”指离去，与“同步”的步调一致没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5662fccc-30e3-49e0-84ee-8776c0577d32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20330, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "争吵", "is_correct": false, "explanation": "“争吵”指争执，与“同步”没有反义关系。"}, {"text": "异步", "is_correct": true, "explanation": "“异步”与“同步”相对，指步调不一致、不同时进行。"}, {"text": "思考", "is_correct": false, "explanation": "“思考”指动脑筋，与“同步”的步调问题无关。"}, {"text": "旅行", "is_correct": false, "explanation": "“旅行”指外出游览，与“同步”没有对立关系。"}], "correct_answer": "异步", "explanations": {"争吵": "“争吵”指争执，与“同步”没有反义关系。", "异步": "“异步”与“同步”相对，指步调不一致、不同时进行。", "思考": "“思考”指动脑筋，与“同步”的步调问题无关。", "旅行": "“旅行”指外出游览，与“同步”没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5662fccc-30e3-49e0-84ee-8776c0577d32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20330, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "大家一起做一样的事情。", "primary_collocate": null, "pronunciation": "tóng bù", "ipa": "tʰʊŋ˧˥ pu˥˩", "syllable_count": 2, "sentences": [{"text": "两个人的脚步要同步。", "target_word": "同步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家的动作一定要同步。", "target_word": "同步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞蹈演员们同步转身。", "target_word": "同步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们同步举起手。", "target_word": "同步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家同步出发，不要有人先走。", "target_word": "同步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合唱时，每个人的声音要同步。", "target_word": "同步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "划船时，大家的动作不同步，船就走不快。", "target_word": "同步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳队员同步入水，非常好看。", "target_word": "同步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们俩同步迈出左脚。", "target_word": "同步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让全班同学同步读课文。", "target_word": "同步", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "多人或多个动作步调一致、同时进行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51c5aa7d-598b-40b2-9bba-04033b920a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20330, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "合作", "is_correct": false, "explanation": "搭配：“脚步”不能与“合作”搭配，脚步不能合作。"}, {"text": "同步", "is_correct": true, "explanation": "“同步”指步调一致，与“两个人的脚步要……”的语境相符。"}, {"text": "交谈", "is_correct": false, "explanation": "搭配：“交谈”的主语须是人，“脚步”不能交谈。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：脚步不能唱歌，句意不通。"}], "explanations": {"合作": "搭配：“脚步”不能与“合作”搭配，脚步不能合作。", "同步": "“同步”指步调一致，与“两个人的脚步要……”的语境相符。", "交谈": "搭配：“交谈”的主语须是人，“脚步”不能交谈。", "唱歌": "语义：脚步不能唱歌，句意不通。"}, "sentence_index": 0, "correct_answer": "同步"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他同步是班长，也是足球队长。", "explanation": "这里应该用〈同时〉。“同步”指多人或多个动作步调一致地进行，不能用来说一个人同时担任两个职务。"}, {"text": "他们同步值班，每人一天。", "explanation": "这里应该用〈轮流〉。“同步”指同时进行，而“每人一天”说明是依次进行，不能用“同步”。"}, {"text": "他同步陪妈妈去了医院。", "explanation": "这里应该用〈陪同〉。“同步”指大家一起做同一件事、步调一致，不能用来说一个人陪伴另一人去做别的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5662fccc-30e3-49e0-84ee-8776c0577d32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20330, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "写作业", "is_correct": false, "explanation": "语义：划船时的动作不是写作业，“动作不写作业”与句意不符。"}, {"text": "聊天", "is_correct": false, "explanation": "搭配：“动作”不能与“聊天”搭配，动作不能聊天。"}, {"text": "同步", "is_correct": true, "explanation": "“同步”指动作步调一致，“不同步”导致船走不快，语境吻合。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：划船时的动作不是游泳，“动作不游泳”与语境不符。"}], "explanations": {"写作业": "语义：划船时的动作不是写作业，“动作不写作业”与句意不符。", "聊天": "搭配：“动作”不能与“聊天”搭配，动作不能聊天。", "同步": "“同步”指动作步调一致，“不同步”导致船走不快，语境吻合。", "游泳": "语义：划船时的动作不是游泳，“动作不游泳”与语境不符。"}, "sentence_index": 6, "correct_answer": "同步"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她同步唱完了整首歌。", "explanation": "这里应该用〈独自〉。“同步”指多人或多个动作步调一致，一个人唱歌不能说“同步”。"}, {"text": "两人同步到达，有先有后。", "explanation": "这里应该用〈先后〉。“同步”指同时进行，与“有先有后”的意思矛盾。"}, {"text": "新来的同学同步了我的岗位。", "explanation": "这里应该用〈接替〉。“同步”不能带“岗位”作宾语，它不指取代他人的职位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5662fccc-30e3-49e0-84ee-8776c0577d32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20330, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三名队员了同步转身。", "corrected_sentence": "三名队员同步转身。", "error_description": "错误：“了”放在动词“同步”前面，成了“了同步”。正确：“了”不应出现在这里，应说“三名队员同步转身”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5662fccc-30e3-49e0-84ee-8776c0577d32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20330, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三名队员同步转身着。", "corrected_sentence": "三名队员同步转身了。", "error_description": "错误：“同步转身”后应用“了”表示动作完成，误用“着”表示持续状态。正确：“三名队员同步转身了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5662fccc-30e3-49e0-84ee-8776c0577d32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20332, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "困难", "is_correct": true, "explanation": "困难：与“容易”（做起来不费力）相反，做起来费力。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”与“容易”没有反义关系，形容外貌或事物的美观。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”与“容易”没有反义关系，形容声音小、环境静。"}, {"text": "热闹", "is_correct": false, "explanation": "“热闹”与“容易”没有反义关系，形容场面喧闹。"}], "correct_answer": "困难", "explanations": {"困难": "困难：与“容易”（做起来不费力）相反，做起来费力。", "漂亮": "“漂亮”与“容易”没有反义关系，形容外貌或事物的美观。", "安静": "“安静”与“容易”没有反义关系，形容声音小、环境静。", "热闹": "“热闹”与“容易”没有反义关系，形容场面喧闹。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20332, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难", "is_correct": true, "explanation": "难：与“容易”（做起来不费力）相反，做起来费力。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”与“容易”没有反义关系，形容看得明白、说得明白。"}, {"text": "宽敞", "is_correct": false, "explanation": "“宽敞”与“容易”没有反义关系，形容空间大。"}, {"text": "活泼", "is_correct": false, "explanation": "“活泼”与“容易”没有反义关系，形容性格或动作生动。"}], "correct_answer": "难", "explanations": {"难": "难：与“容易”（做起来不费力）相反，做起来费力。", "清楚": "“清楚”与“容易”没有反义关系，形容看得明白、说得明白。", "宽敞": "“宽敞”与“容易”没有反义关系，形容空间大。", "活泼": "“活泼”与“容易”没有反义关系，形容性格或动作生动。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20332, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "做起来不费力气。", "primary_collocate": null, "pronunciation": "róngyi", "ipa": "ɻʊŋ˧˥ i", "syllable_count": 2, "sentences": [{"text": "这道题很容易，我一分钟就做完了。", "target_word": "容易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学写汉字不太容易。", "target_word": "容易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏很容易，小孩也会玩。", "target_word": "容易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找到他家不容易，路很多。", "target_word": "容易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的考试比昨天容易。", "target_word": "容易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说起来容易，做起来难。", "target_word": "容易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的字很大，读起来很容易。", "target_word": "容易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要在大城市找房子不容易。", "target_word": "容易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个菜做法很容易，你也能学会。", "target_word": "容易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这个问题很容易回答。", "target_word": "容易", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不容易", "label": "否定"}], "register": "中性", "sense_fingerprint": "事情做起来不难、不费力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60fb9430-b8df-4950-a53e-fc0e3676837a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20332, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "容易", "is_correct": true, "explanation": "容易 róngyi：做起来不费力。"}, {"text": "荣誉", "is_correct": false, "explanation": "yù 与 yi 韵母不同，意思是荣誉。"}, {"text": "溶液", "is_correct": false, "explanation": "yè 与 yi 韵母不同，意思是溶液。"}, {"text": "绒衣", "is_correct": false, "explanation": "yī（第一声）与轻声 yi 声调不同，意思是绒衣。"}, {"text": "容器", "is_correct": false, "explanation": "qì 与 yi 声母不同，意思是容器。"}], "explanations": {"容易": "容易 róngyi：做起来不费力。", "荣誉": "yù 与 yi 韵母不同，意思是荣誉。", "溶液": "yè 与 yi 韵母不同，意思是溶液。", "绒衣": "yī（第一声）与轻声 yi 声调不同，意思是绒衣。", "容器": "qì 与 yi 声母不同，意思是容器。"}, "sentence_index": null, "correct_answer": "容易"}, "level_3": {"options": [{"text": "容易", "is_correct": true, "explanation": "容易：做起来不费力，与后半句“一分钟就做完了”相合。"}, {"text": "困难", "is_correct": false, "explanation": "语义：“困难”与后半句“一分钟就做完了”矛盾。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”多形容外貌、景物，不说题目很漂亮。"}, {"text": "聪明", "is_correct": false, "explanation": "搭配：“聪明”形容人的智力，不能用来形容题目。"}], "explanations": {"容易": "容易：做起来不费力，与后半句“一分钟就做完了”相合。", "困难": "语义：“困难”与后半句“一分钟就做完了”矛盾。", "漂亮": "搭配：“漂亮”多形容外貌、景物，不说题目很漂亮。", "聪明": "搭配：“聪明”形容人的智力，不能用来形容题目。"}, "sentence_index": 0, "correct_answer": "容易"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的性格很容易，大家都喜欢他。", "explanation": "这里应该用〈随和〉。“容易”说做事不费力，形容性格好相处要用“随和”。"}, {"text": "我今天心情很容易。", "explanation": "这里应该用〈轻松〉。容易指做事不费力，形容心情要用“轻松”。"}, {"text": "这个小区的超市很容易。", "explanation": "这里应该用〈方便〉。容易说做事不费力，形容超市、设施让人用起来省事要用“方便”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20332, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "容易", "is_correct": true, "explanation": "容易 róngyi：做起来不费力。"}, {"text": "同意", "is_correct": false, "explanation": "tóng 与 róng 声母不同，意思是同意。"}, {"text": "农艺", "is_correct": false, "explanation": "nóng 与 róng 声母不同，意思是农业技术。"}, {"text": "荣誉", "is_correct": false, "explanation": "yù 与 yi 韵母、声调不同，意思是光荣的名誉。"}], "explanations": {"容易": "容易 róngyi：做起来不费力。", "同意": "tóng 与 róng 声母不同，意思是同意。", "农艺": "nóng 与 róng 声母不同，意思是农业技术。", "荣誉": "yù 与 yi 韵母、声调不同，意思是光荣的名誉。"}, "sentence_index": null, "correct_answer": "容易"}, "level_3": {"options": [{"text": "容易", "is_correct": true, "explanation": "容易：做起来不费力，与“读起来”的语境相合。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：“吵闹”形容声音嘈杂，不能说书读起来吵闹。"}, {"text": "辣", "is_correct": false, "explanation": "语义：“辣”形容味道，不能用来形容读书的感觉。"}, {"text": "高兴", "is_correct": false, "explanation": "搭配：“高兴”形容人的情绪，不用来形容读书的感觉。"}], "explanations": {"容易": "容易：做起来不费力，与“读起来”的语境相合。", "吵闹": "语义：“吵闹”形容声音嘈杂，不能说书读起来吵闹。", "辣": "语义：“辣”形容味道，不能用来形容读书的感觉。", "高兴": "搭配：“高兴”形容人的情绪，不用来形容读书的感觉。"}, "sentence_index": 6, "correct_answer": "容易"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服很容易，只要十块钱。", "explanation": "这里应该用〈便宜〉。“容易”指做起来不费力，说价格低要用“便宜”。"}, {"text": "这个苹果很容易，又甜又脆。", "explanation": "这里应该用〈好吃〉。“容易”指做起来不费力，形容食物的味道要用“好吃”。"}, {"text": "这个书包很容易，装下了全部的书。", "explanation": "这里应该用〈大〉。“容易”指做事不费力，形容物体的容量要用“大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20332, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套练习的容易，我十分钟就做完了。", "corrected_sentence": "这套练习很容易，我十分钟就做完了。", "error_description": "用词错误：结构助词“的”不能用于形容词前表示程度，应使用程度副词“很”，应说“很容易”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20332, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次考试上次容易。", "corrected_sentence": "这次考试比上次容易。", "error_description": "缺少比较标记：比较两件事物的难易程度要用“比”，应说“比上次容易”，不能省去“比”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
