INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20338, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一种病，让人不容易跟别人说话和玩。", "primary_collocate": null, "pronunciation": "zì bì zhèng", "ipa": "tsɨ⁵¹ pi⁵¹ ʈʂɤŋ⁵¹", "syllable_count": 3, "sentences": [{"text": "小明有自闭症，不太爱和人说话。", "target_word": "自闭症", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为自闭症，他很少和同学一起玩。", "target_word": "自闭症", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈带儿子去医院，医生说他没有自闭症。", "target_word": "自闭症", "complexity_tier": "T3", "furigana": "mā ma dài érzi qù yīyuàn, yīshēng shuō tā méiyǒu zì bì zhèng。", "sentence_source": "generated"}, {"text": "自闭症不是因为孩子不听话。", "target_word": "自闭症", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的表弟有自闭症，喜欢一个人玩。", "target_word": "自闭症", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说自闭症的孩子很怕大声音。", "target_word": "自闭症", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师耐心地帮助有自闭症的同学。", "target_word": "自闭症", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自闭症不会传染给别人。", "target_word": "自闭症", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有自闭症，所以很怕和陌生人说话。", "target_word": "自闭症", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视里有一个关于自闭症的故事。", "target_word": "自闭症", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自閉症", "label": "繁体"}, {"form": "自闭症谱系障碍", "label": "复合"}], "register": "中性", "sense_fingerprint": "自闭症：一种病，患者不容易跟别人说话和玩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b9e127-76e2-48c8-a316-ec41d410e34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20338, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自闭症", "is_correct": true, "explanation": "「自闭症」是一种病，「小明有自闭症」与后半句「不太爱和人说话」的因果一致。"}, {"text": "冠军", "is_correct": false, "explanation": "语义：「冠军」不是病症，「有冠军，不太爱说话」之间没有逻辑联系。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：「有体温」不是描述人的病况的说法，与「不太爱和人说话」不构成解释。"}, {"text": "风浪", "is_correct": false, "explanation": "语义：「风浪」指自然现象或困境，不是人的病症，与「不太爱说话」无关。"}], "explanations": {"自闭症": "「自闭症」是一种病，「小明有自闭症」与后半句「不太爱和人说话」的因果一致。", "冠军": "语义：「冠军」不是病症，「有冠军，不太爱说话」之间没有逻辑联系。", "体温": "搭配：「有体温」不是描述人的病况的说法，与「不太爱和人说话」不构成解释。", "风浪": "语义：「风浪」指自然现象或困境，不是人的病症，与「不太爱说话」无关。"}, "sentence_index": 0, "correct_answer": "自闭症"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的表弟叫自闭症，喜欢一个人玩。", "explanation": "这里应该用〈人名〉。自闭症是病名，不能当人名，「叫」后接的应该是人名。"}, {"text": "他是一位自闭症，不太爱和人说话。", "explanation": "这里应该用〈病人〉。自闭症是病名，不能用来指人，指人要说「自闭症患者」或「有自闭症的人」。"}, {"text": "自闭症是他最好的玩伴。", "explanation": "这里应该用〈朋友〉。自闭症是病名，不能作为玩伴；能陪他玩的应该是人，要说「朋友」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc825534-adc9-48cb-9526-1e54bcd38e11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20338, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自闭症", "is_correct": true, "explanation": "「有自闭症的同学」指患有这种病的同学，「耐心地帮助」与之相合。"}, {"text": "星空", "is_correct": false, "explanation": "语义：「星空」不是人的状况，「有星空的同学」不通，与「帮助」的对象不符。"}, {"text": "海拔", "is_correct": false, "explanation": "搭配：「海拔」是地理概念，不能用于形容同学，「有海拔的同学」说不通。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：「雨水」是自然现象，不能指人，与「帮助」的语境不符。"}], "explanations": {"自闭症": "「有自闭症的同学」指患有这种病的同学，「耐心地帮助」与之相合。", "星空": "语义：「星空」不是人的状况，「有星空的同学」不通，与「帮助」的对象不符。", "海拔": "搭配：「海拔」是地理概念，不能用于形容同学，「有海拔的同学」说不通。", "雨水": "语义：「雨水」是自然现象，不能指人，与「帮助」的语境不符。"}, "sentence_index": 6, "correct_answer": "自闭症"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她性格有点自闭症，总把自己关在屋里。", "explanation": "这里应该用〈自闭〉。「自闭」形容性格，「自闭症」是病名，不能说「性格有点自闭症」。"}, {"text": "妈妈说，他每天都吃自闭症，不太爱说话。", "explanation": "这里应该用〈药〉。自闭症是病名，不能当食物吃，要吃的应该是「药」。"}, {"text": "老师耐心地帮助这个自闭症。", "explanation": "这里应该用〈孩子〉。自闭症是病名，不能指人，「帮助这个自闭症」不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc825534-adc9-48cb-9526-1e54bcd38e11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20338, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他得的是一只自闭症，需要长期训练。", "corrected_sentence": "他得的是一种自闭症，需要长期训练。", "error_description": "「自闭症」作为病名，应用量词「种」，不能用「只」。「只」用于动物或成对的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc825534-adc9-48cb-9526-1e54bcd38e11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20338, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的朋友得了自闭症病，很少和人说话。", "corrected_sentence": "我的朋友得了自闭症，很少和人说话。", "error_description": "「自闭症」的「症」已经表示病，后面不能再加「病」。应说「得了自闭症」，不说「得了自闭症病」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc825534-adc9-48cb-9526-1e54bcd38e11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
