INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20340, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "人和动物一起生活、互相帮助的特点。", "primary_collocate": null, "pronunciation": "shè huì xìng", "ipa": "ʂɤ˥˩ xweɪ˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "蚂蚁是有社会性的动物。", "target_word": "社会性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人的社会性很强，需要朋友。", "target_word": "社会性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狼群一起打猎，说明它们有社会性。", "target_word": "社会性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜜蜂的社会性表现在分工合作上。", "target_word": "社会性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校可以帮助孩子培养社会性。", "target_word": "社会性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猴子生活在一起，互相帮忙，社会性很明显。", "target_word": "社会性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，人是有社会性的。", "target_word": "社会性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "独自生活的老虎，社会性不如狮子。", "target_word": "社会性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种鸟的社会性很强，从不独自生活。", "target_word": "社会性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究者观察了这些鱼的社会性。", "target_word": "社会性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "社會性", "label": "繁体"}], "register": "书面", "sense_fingerprint": "人和动物群体生活、互相帮助的特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '071f4daf-d2f5-4352-a46c-90263f231feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20340, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "社会性", "is_correct": true, "explanation": "“社会性”指群居互助的特点，蚂蚁具有这种特点，句中“有社会性的动物”符合句意。"}, {"text": "金属性", "is_correct": false, "explanation": "语义：蚂蚁不具有金属性，“有金属性的动物”说不通。"}, {"text": "抽象性", "is_correct": false, "explanation": "语义：动物不是抽象概念，“有抽象性的动物”说不通。"}, {"text": "文学性", "is_correct": false, "explanation": "搭配：“文学性”多用于作品或语言，不用来说动物。"}], "explanations": {"社会性": "“社会性”指群居互助的特点，蚂蚁具有这种特点，句中“有社会性的动物”符合句意。", "金属性": "语义：蚂蚁不具有金属性，“有金属性的动物”说不通。", "抽象性": "语义：动物不是抽象概念，“有抽象性的动物”说不通。", "文学性": "搭配：“文学性”多用于作品或语言，不用来说动物。"}, "sentence_index": 0, "correct_answer": "社会性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "城市里的社会性很复杂。", "explanation": "这里应该用〈情况〉。“社会性”指群居互助的特点，不指城市的状况，不能说“城市里的社会性很复杂”。"}, {"text": "他很擅长社会性。", "explanation": "这里应该用〈社交〉。“擅长”的是社交这种行为能力，“社会性”是特点，不能说擅长。"}, {"text": "这个社会性很热闹。", "explanation": "这里应该用〈社区〉。“热闹”形容有人聚居的地方，“社会性”是抽象特点，不能说很热闹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20340, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "社会性", "is_correct": true, "explanation": "“社会性”指群居互助的特点，人具有这种特点，句中“人是有社会性的”符合句意。"}, {"text": "矿物性", "is_correct": false, "explanation": "语义：人不是矿物，“人是有矿物性的”说不通。"}, {"text": "化学性", "is_correct": false, "explanation": "搭配：“化学性”多指物质的性质，不用来说人。"}, {"text": "地质性", "is_correct": false, "explanation": "语义：人不具有地质特征，句意不通。"}], "explanations": {"社会性": "“社会性”指群居互助的特点，人具有这种特点，句中“人是有社会性的”符合句意。", "矿物性": "语义：人不是矿物，“人是有矿物性的”说不通。", "化学性": "搭配：“化学性”多指物质的性质，不用来说人。", "地质性": "语义：人不具有地质特征，句意不通。"}, "sentence_index": 6, "correct_answer": "社会性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个社会性有很多会员。", "explanation": "这里应该用〈组织〉。“社会性”是群居互助的特点，不能指具体的组织。"}, {"text": "两国的社会性很密切。", "explanation": "这里应该用〈交往〉。“社会性”是特点，不指两国之间的往来。"}, {"text": "社会性是一门学科。", "explanation": "这里应该用〈社会学〉。“社会性”是特点，不是学科。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20340, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只鸟很社会性。", "corrected_sentence": "这只鸟很有社会性。", "error_description": "词语错误：“社会性”是名词，要说“很有社会性”，前面需要动词“有”，不能直接说“很社会性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20340, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些鱼的社会性性很强。", "corrected_sentence": "这些鱼的社会性很强。", "error_description": "词形错误：“社会性”后多写了一个“性”，成了“社会性性”。“性”只加一次，应为“这些鱼的社会性很强”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
