INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20342, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "障碍就是挡住路的东西。", "primary_collocate": null, "pronunciation": "zhàng ài", "ipa": "ʈʂɑŋ˥˩ aɪ˥˩", "syllable_count": 2, "sentences": [{"text": "路中间的大石头是个障碍。", "target_word": "障碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机看见前面有障碍，马上停车。", "target_word": "障碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把路上的障碍搬走。", "target_word": "障碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛时，运动员要跳过一个个障碍。", "target_word": "障碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盲人走路时，怕遇到障碍。", "target_word": "障碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口放着很多箱子，成了走路的障碍。", "target_word": "障碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪太大，路上到处都是障碍。", "target_word": "障碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器人能自己躲开前面的障碍。", "target_word": "障碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马跑得很快，跳过了所有障碍。", "target_word": "障碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消防员先清除路上的障碍，再进去救人。", "target_word": "障碍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个障碍", "label": "量词"}, {"form": "障碍物", "label": "复合"}, {"form": "障礙", "label": "繁体"}], "register": "中性", "sense_fingerprint": "挡在路上的具体物体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6746157-9edb-4c07-be8c-21eb24acfb5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20342, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "障碍", "is_correct": true, "explanation": "“障碍”指挡在路上的具体物体，与句意一致。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是石头的一类，“是个天气”说不通。"}, {"text": "答案", "is_correct": false, "explanation": "语义：答案不是具体的石头，句子说不通。"}, {"text": "杰作", "is_correct": false, "explanation": "语义：“杰作”指优秀的艺术或文学成果，不能指路中间挡道的石头，句子说不通。"}], "explanations": {"障碍": "“障碍”指挡在路上的具体物体，与句意一致。", "天气": "语义：天气不是石头的一类，“是个天气”说不通。", "答案": "语义：答案不是具体的石头，句子说不通。", "杰作": "语义：“杰作”指优秀的艺术或文学成果，不能指路中间挡道的石头，句子说不通。"}, "sentence_index": 0, "correct_answer": "障碍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一边吃着障碍，一边看电视。", "explanation": "这里应该用〈零食〉。“吃”的对象是食物，障碍不能吃。"}, {"text": "他用障碍把书架搭好了，大家都很满意。", "explanation": "这里应该用〈木板〉。搭书架要用木板等建材，障碍不是建材。"}, {"text": "他用障碍写作业，写得很认真。", "explanation": "这里应该用〈笔〉。写字要用笔，障碍不是书写工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe89666-11d3-41f8-be37-0b6e8f921eaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20342, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "障碍", "is_correct": true, "explanation": "“障碍”指挡住路的具体物体，与句意相符。"}, {"text": "课程", "is_correct": false, "explanation": "语义：课程不是能堆在路上的东西，句子说不通。"}, {"text": "护照", "is_correct": false, "explanation": "语义：护照不会到处都是，句子说不通。"}, {"text": "名额", "is_correct": false, "explanation": "搭配：“到处都是”后接可见的物件，“名额”是抽象配额，不能说到处都是名额。"}], "explanations": {"障碍": "“障碍”指挡住路的具体物体，与句意相符。", "课程": "语义：课程不是能堆在路上的东西，句子说不通。", "护照": "语义：护照不会到处都是，句子说不通。", "名额": "搭配：“到处都是”后接可见的物件，“名额”是抽象配额，不能说到处都是名额。"}, "sentence_index": 6, "correct_answer": "障碍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个障碍连接了两岸，人们终于可以过河了。", "explanation": "这里应该用〈桥梁〉。桥梁能连接两岸，“障碍”是挡住路的东西，不能用来连接。"}, {"text": "他把这个障碍送给了朋友，朋友很高兴。", "explanation": "这里应该用〈礼物〉。障碍是挡在路上的东西，不能拿来送人。"}, {"text": "妈妈把这个障碍放进冰箱，准备做晚饭。", "explanation": "这里应该用〈食材〉。放进冰箱的是食物，障碍不是食材。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe89666-11d3-41f8-be37-0b6e8f921eaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20342, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "运动员一个个地跳过了障碍们。", "corrected_sentence": "运动员一个个地跳过了障碍。", "error_description": "错误：“们”只用于人或拟人化的对象，“障碍”是物体，不能加“们”，应删去“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe89666-11d3-41f8-be37-0b6e8f921eaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20342, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "路上还放了着一个障碍。", "corrected_sentence": "路上还放着一个障碍。", "error_description": "体态错误：表示状态持续用“着”，“放了着”不成立，应改为“放着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe89666-11d3-41f8-be37-0b6e8f921eaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
