INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20344, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "生病的人。", "primary_collocate": null, "pronunciation": "huàn zhě", "ipa": "xwan˥˩ ʈʂɤ˨˩˦", "syllable_count": 2, "sentences": [{"text": "那位患者头很疼，一直躺着。", "target_word": "患者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "患者每天都要吃药。", "target_word": "患者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在医院看到一位老年患者。", "target_word": "患者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病的患者越来越多。", "target_word": "患者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是一名感冒患者。", "target_word": "患者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "患者的脸色很不好。", "target_word": "患者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生让患者先坐下。", "target_word": "患者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李是个糖尿病患者，不能吃太甜的东西。", "target_word": "患者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "患者想喝水，护士给他倒了一杯。", "target_word": "患者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "患者很多，医生忙得没有时间吃饭。", "target_word": "患者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位患者", "label": "量词"}, {"form": "一名患者", "label": "量词"}], "register": "书面", "sense_fingerprint": "患者：生病的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bc8c19a-b344-4816-9e61-2e91b5fa9608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20344, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "患者", "is_correct": true, "explanation": "正确。“那位”指人，“患者”是接受治疗的病人，头疼并躺着符合语境。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车没有头，不会头疼，也不会躺着休息。"}, {"text": "小狗", "is_correct": false, "explanation": "搭配：量词“位”只用于人，狗应说“那只”，句子不成立。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：量词“位”只用于人，窗户不能用“位”来数，且不会头疼躺着。"}], "explanations": {"患者": "正确。“那位”指人，“患者”是接受治疗的病人，头疼并躺着符合语境。", "汽车": "语义：汽车没有头，不会头疼，也不会躺着休息。", "小狗": "搭配：量词“位”只用于人，狗应说“那只”，句子不成立。", "窗户": "搭配：量词“位”只用于人，窗户不能用“位”来数，且不会头疼躺着。"}, "sentence_index": 0, "correct_answer": "患者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅的患者点了三份牛排，服务员很忙。", "explanation": "这里应该用〈顾客〉。患者指生病、接受治疗的人，不用于指在餐厅点餐的人。"}, {"text": "这支巡逻队的患者每晚都出去抓坏人。", "explanation": "这里应该用〈警察〉。患者指生病、接受治疗的人，不指值夜巡逻、抓捕坏人的人。"}, {"text": "这场音乐会的患者都站起来鼓掌。", "explanation": "这里应该用〈观众〉。患者指生病、接受治疗的人，不指来听音乐会的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08d6a5a-8a71-44e5-b4f0-723d74e024c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20344, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "患者", "is_correct": true, "explanation": "正确。“医生让患者先坐下”中的对象是人，“患者”符合语境。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能坐下，也不能听从医生的指令。"}, {"text": "药", "is_correct": false, "explanation": "搭配：“坐下”要求有生命的施事，“药”不能与“医生让……先坐下”搭配。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是器物，不能坐下。"}], "explanations": {"患者": "正确。“医生让患者先坐下”中的对象是人，“患者”符合语境。", "桌子": "语义：桌子不能坐下，也不能听从医生的指令。", "药": "搭配：“坐下”要求有生命的施事，“药”不能与“医生让……先坐下”搭配。", "花瓶": "语义：花瓶是器物，不能坐下。"}, "sentence_index": 6, "correct_answer": "患者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那座古城的患者很多，大家都在拍照。", "explanation": "这里应该用〈游客〉。患者指生病、接受治疗的人，不指到古城参观的人。"}, {"text": "这座博物馆的患者都是专家，很会讲解。", "explanation": "这里应该用〈讲解员〉。患者指生病、接受治疗的人，不指在博物馆讲解的人。"}, {"text": "场上的患者配合默契，传球非常准。", "explanation": "这里应该用〈球员〉。患者指生病、接受治疗的人，不指在球场上比赛的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08d6a5a-8a71-44e5-b4f0-723d74e024c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20344, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只患者刚从医院回家。", "corrected_sentence": "这位患者刚从医院回家。", "error_description": "“患者”指人，量词应用“位”或“名”。“只”用于动物，指人时是错误的，应改为“这位患者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08d6a5a-8a71-44e5-b4f0-723d74e024c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20344, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "病房里住着两患者，护士正在照顾。", "corrected_sentence": "病房里住着两位患者，护士正在照顾。", "error_description": "数词“两”与名词之间漏了量词，“患者”指人，应说“两位患者”，不能说“两患者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08d6a5a-8a71-44e5-b4f0-723d74e024c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
