INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20346, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "看到别人难过，你心里也跟着难过。", "primary_collocate": null, "pronunciation": "gòng qíng", "ipa": "kʊŋ˥˩ tɕʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "看到朋友哭了，我也产生了共情。", "target_word": "共情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个故事，大家都产生了共情。", "target_word": "共情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对病人的痛苦有很深的共情。", "target_word": "共情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有共情，只是站在旁边看着。", "target_word": "共情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的小孩很可怜，我对他特别有共情。", "target_word": "共情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈难过的时候，孩子也会有共情。", "target_word": "共情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的共情让她不再孤单。", "target_word": "共情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听完老人的话，我对他产生了共情。", "target_word": "共情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗受伤了，女儿对它充满共情。", "target_word": "共情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为有共情，他才明白朋友为什么哭。", "target_word": "共情", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "共情力", "label": "复合"}, {"form": "共情能力", "label": "复合"}], "register": "中性", "sense_fingerprint": "共情：看到别人难过自己也跟着难过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bc8c19a-b344-4816-9e61-2e91b5fa9608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20346, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "共情", "is_correct": true, "explanation": "正确。gòng qíng，指看到别人难过时自己也跟着难过。"}, {"text": "动情", "is_correct": false, "explanation": "声母不同：dòng（d）与 gòng（g），意思是感情被打动。"}, {"text": "纵情", "is_correct": false, "explanation": "声母不同：zòng（z）与 gòng（g），意思是放纵感情、无拘无束。"}, {"text": "共庆", "is_correct": false, "explanation": "声调不同：qìng（第四声）与 qíng（第二声），意思是共同庆祝。"}], "explanations": {"共情": "正确。gòng qíng，指看到别人难过时自己也跟着难过。", "动情": "声母不同：dòng（d）与 gòng（g），意思是感情被打动。", "纵情": "声母不同：zòng（z）与 gòng（g），意思是放纵感情、无拘无束。", "共庆": "声调不同：qìng（第四声）与 qíng（第二声），意思是共同庆祝。"}, "sentence_index": null, "correct_answer": "共情"}, "level_3": {"options": [{"text": "共情", "is_correct": true, "explanation": "正确。“我也产生了共情”表示看到朋友哭，我心里也跟着难过，符合语境。"}, {"text": "词典", "is_correct": false, "explanation": "语义：“看到朋友哭了”之后说“我也有词典”，与语境毫无关联。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图不是情感，与“看到朋友哭了”的语境不符。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：“有”后接的应是情感或能力，“蛋糕”不能表示对朋友哭泣的心理反应。"}], "explanations": {"共情": "正确。“我也产生了共情”表示看到朋友哭，我心里也跟着难过，符合语境。", "词典": "语义：“看到朋友哭了”之后说“我也有词典”，与语境毫无关联。", "地图": "语义：地图不是情感，与“看到朋友哭了”的语境不符。", "蛋糕": "搭配：“有”后接的应是情感或能力，“蛋糕”不能表示对朋友哭泣的心理反应。"}, "sentence_index": 0, "correct_answer": "共情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部电影的共情很长，看了整整三个小时。", "explanation": "这里应该用〈时长〉。共情指看到别人难过时自己也跟着难过，不能用来形容电影的长短。"}, {"text": "这家公司的共情很大，占地有三万平方米。", "explanation": "这里应该用〈规模〉。共情指看到别人难过时自己也跟着难过，不能用来形容公司的大小。"}, {"text": "她的共情很难看，像是病了一样。", "explanation": "这里应该用〈脸色〉。共情指看到别人难过时自己也跟着难过，不用来描述人的脸色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08d6a5a-8a71-44e5-b4f0-723d74e024c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20346, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共情", "is_correct": true, "explanation": "正确。“你的共情”指你对她感受的理解，使她不再孤单，句意通顺。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是疾病，不能让人不再孤单。"}, {"text": "台灯", "is_correct": false, "explanation": "语义：台灯是器物，与“让她不再孤单”没有关联。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“你的……让她不再孤单”要求施事是人的情感或陪伴，“石头”不能与之搭配。"}], "explanations": {"共情": "正确。“你的共情”指你对她感受的理解，使她不再孤单，句意通顺。", "感冒": "语义：感冒是疾病，不能让人不再孤单。", "台灯": "语义：台灯是器物，与“让她不再孤单”没有关联。", "石头": "搭配：“你的……让她不再孤单”要求施事是人的情感或陪伴，“石头”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "共情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那个箱子的共情很大，装得下三台电脑。", "explanation": "这里应该用〈体积〉。共情指看到别人难过时自己也跟着难过，不能用来形容箱子的大小。"}, {"text": "这条路的共情很长，开车要开一个小时。", "explanation": "这里应该用〈长度〉。共情指看到别人难过时自己也跟着难过，不能用来形容路的长短。"}, {"text": "这件衣服的共情很便宜，只要十块钱。", "explanation": "这里应该用〈价格〉。共情指看到别人难过时自己也跟着难过，不用来说明东西的价钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08d6a5a-8a71-44e5-b4f0-723d74e024c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20346, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对朋友的难过有一只很强的共情。", "corrected_sentence": "他对朋友的难过有一种很强的共情。", "error_description": "“共情”是抽象名词，量词应用“种”。“只”用于动物，不能修饰抽象的“共情”，应改为“一种很强的共情”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08d6a5a-8a71-44e5-b4f0-723d74e024c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20346, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她对别人有很深共情，邻居有困难时总是第一个赶来。", "corrected_sentence": "她对别人有很深的共情，邻居有困难时总是第一个赶来。", "error_description": "错误形式：“很深共情”；正确形式：“很深的共情”。形容词被“很”修饰后再修饰名词“共情”，中间要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08d6a5a-8a71-44e5-b4f0-723d74e024c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
