INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20352, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用不直接说的话让别人明白。", "primary_collocate": null, "pronunciation": "àn shì", "ipa": "an˥˩ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他指了指杯子，暗示我给他倒水。", "target_word": "暗示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明暗示妈妈，他想要一只小狗。", "target_word": "暗示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友一直看表，暗示我们该走了。", "target_word": "暗示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着暗示我，这件事别告诉别人。", "target_word": "暗示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板暗示大家，明年可能不加工资。", "target_word": "暗示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我听出来了，他在暗示我帮忙。", "target_word": "暗示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你不用暗示，我明白你的意思。", "target_word": "暗示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "王老师暗示学生，答案在第二页。", "target_word": "暗示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没有直说，只是暗示我该努力了。", "target_word": "暗示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她拍了拍我的肩，暗示我别紧张。", "target_word": "暗示", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "暗示了", "label": "体标"}, {"form": "暗示着", "label": "体标"}, {"form": "暗示过", "label": "体标"}], "register": "中性", "sense_fingerprint": "不直接说出来，用话或动作让别人自己明白想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb8ad67b-239f-4a6f-82cc-ce442b51a334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20352, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "暗示", "is_correct": true, "explanation": "暗示指不直接说而用动作让对方明白。“他指了指杯子，暗示我给他倒水”，只有“暗示”符合。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：“祝贺”表示庆贺，与指杯子的动作不相关。"}, {"text": "检查", "is_correct": false, "explanation": "搭配：“检查”的对象是事物或工作，不能说“检查我给他倒水”。"}, {"text": "原谅", "is_correct": false, "explanation": "语义：“原谅”表示不计较过错，与指杯子的动作无关。"}], "explanations": {"暗示": "暗示指不直接说而用动作让对方明白。“他指了指杯子，暗示我给他倒水”，只有“暗示”符合。", "祝贺": "语义：“祝贺”表示庆贺，与指杯子的动作不相关。", "检查": "搭配：“检查”的对象是事物或工作，不能说“检查我给他倒水”。", "原谅": "语义：“原谅”表示不计较过错，与指杯子的动作无关。"}, "sentence_index": 0, "correct_answer": "暗示"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "班主任正式暗示同学们，下周要进行期末考试。", "explanation": "这里应该用〈通知〉。暗示是含蓄表达，正式的通知要直接说明，不能用暗示。"}, {"text": "这张表格暗示了每个人的分数，大家都很满意。", "explanation": "这里应该用〈列出〉。暗示是含蓄表达，分数应直接列出，不能用暗示。"}, {"text": "他暗示得很大声，连隔壁的人都听见了。", "explanation": "这里应该用〈喊〉。暗示是含蓄表达，不能与“很大声”这样直接的说法搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3448ed1d-9f75-4fae-beb3-c278fb39073e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20352, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "暗示", "is_correct": true, "explanation": "暗示指含蓄地表达。“你不用暗示，我明白你的意思”说明对方的表达方式含蓄，只有“暗示”符合。"}, {"text": "计算", "is_correct": false, "explanation": "语义：“计算”指算数，与“明白你的意思”无关。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是物品，不能说“洗你的意思”。"}, {"text": "绘画", "is_correct": false, "explanation": "语义：“绘画”指作画，与表达意思的语境不符。"}], "explanations": {"暗示": "暗示指含蓄地表达。“你不用暗示，我明白你的意思”说明对方的表达方式含蓄，只有“暗示”符合。", "计算": "语义：“计算”指算数，与“明白你的意思”无关。", "洗": "搭配：“洗”的对象是物品，不能说“洗你的意思”。", "绘画": "语义：“绘画”指作画，与表达意思的语境不符。"}, "sentence_index": 6, "correct_answer": "暗示"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在纸上暗示了所有答案，写得一清二楚。", "explanation": "这里应该用〈写出〉。暗示是含蓄表达，不能与“写得一清二楚”这样明确的说法搭配。"}, {"text": "我在电话里一个数字一个数字地暗示了她我的手机号码。", "explanation": "这里应该用〈告诉〉。一个数字一个数字地说出号码是直接告知，“暗示”是含蓄表达，不能这样用。"}, {"text": "这份合同暗示了全部条款，请大家认真阅读。", "explanation": "这里应该用〈写明〉。暗示是含蓄表达，合同条款必须明确写出，不能用暗示。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3448ed1d-9f75-4fae-beb3-c278fb39073e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20352, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他暗示了过我两次，但我没有听懂。", "corrected_sentence": "他暗示过我两次，但我没有听懂。", "error_description": "“暗示”后面同时加了“了”和“过”。两种体标不能同时使用，应只说“暗示过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3448ed1d-9f75-4fae-beb3-c278fb39073e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20352, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没有直接说，只是把暗示了我的想法。", "corrected_sentence": "他没有直接说，只是暗示了我的想法。", "error_description": "“把”字结构用错了。“暗示”前面没有需要提前的宾语，不能加“把”，应直接说“暗示了我的想法”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3448ed1d-9f75-4fae-beb3-c278fb39073e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20354, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20354, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20354, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "别人做了什么事，你心里怎么想或怎么做。", "primary_collocate": null, "pronunciation": "fǎn yìng", "ipa": "fan˨˩˦ iŋ˥˩", "syllable_count": 2, "sentences": [{"text": "听到这个消息，她的反应很平静。", "target_word": "反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师批评他，他没有什么反应。", "target_word": "反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家对新办法的反应都很好。", "target_word": "反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我讲了个笑话，可是没人有反应。", "target_word": "反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的第一反应是打电话给妈妈。", "target_word": "反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到蛇，小孩的反应特别大。", "target_word": "反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你告诉他以后，他有什么反应？", "target_word": "反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "观众的反应让导演很高兴。", "target_word": "反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友说了坏消息，我不知道该有什么反应。", "target_word": "反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸看到成绩单，反应并不大。", "target_word": "反应", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "第一反应", "label": "复合"}, {"form": "反應", "label": "繁体"}], "register": "口语", "sense_fingerprint": "人对事情或消息的态度与行为上的回应", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1464a407-3635-4c26-9c56-965320c82102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20354, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反应", "is_correct": true, "explanation": "正确：“她的反应很平静”指她听到消息后的态度，与句意相符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能用“很平静”来形容，搭配不通。"}, {"text": "事故", "is_correct": false, "explanation": "语义：“她的事故很平静”不合理，“事故”不是人的态度或心理。"}, {"text": "原料", "is_correct": false, "explanation": "语义：“她的原料很平静”无法成立，“原料”不指人的态度。"}], "explanations": {"反应": "正确：“她的反应很平静”指她听到消息后的态度，与句意相符。", "颜色": "搭配：“颜色”不能用“很平静”来形容，搭配不通。", "事故": "语义：“她的事故很平静”不合理，“事故”不是人的态度或心理。", "原料": "语义：“她的原料很平静”无法成立，“原料”不指人的态度。"}, "sentence_index": 0, "correct_answer": "反应"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "图书馆的反应很安静，适合看书。", "explanation": "这里应该用〈氛围〉。“反应”指对事情的回应，不能用来形容环境；应说“氛围很安静”。"}, {"text": "他第一只反应是笑出声。", "explanation": "这里应该用〈个〉。“只”不用于反应，反应的量词应是“个”或“种”。"}, {"text": "他很少反应自己的错误。", "explanation": "这里应该用〈反省〉。反省指回想并检查自己的过失；反应指对外界事情的回应，不能用于检查自己的错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20354, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反应", "is_correct": true, "explanation": "正确：问“他有什么反应”是在问他听到消息后的回应，与句意相符。"}, {"text": "公式", "is_correct": false, "explanation": "语义：“他有什么公式”与“告诉他以后”的语境不符，问的是对消息的回应。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：“椅子”不是对消息的回应，此处问的是他的态度。"}, {"text": "海洋", "is_correct": false, "explanation": "搭配：问“有什么”时应接表示回应的名词，“海洋”与此搭配不通。"}], "explanations": {"反应": "正确：问“他有什么反应”是在问他听到消息后的回应，与句意相符。", "公式": "语义：“他有什么公式”与“告诉他以后”的语境不符，问的是对消息的回应。", "椅子": "语义：“椅子”不是对消息的回应，此处问的是他的态度。", "海洋": "搭配：问“有什么”时应接表示回应的名词，“海洋”与此搭配不通。"}, "sentence_index": 6, "correct_answer": "反应"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司制定了新的反应。", "explanation": "这里应该用〈计划〉。“制定”搭配计划；反应是对事情的回应，不能被制定。"}, {"text": "他说话的反应很温和。", "explanation": "这里应该用〈语气〉。“温和”形容说话的语气，不能修饰“反应”。"}, {"text": "他的反应需要加热才能开始。", "explanation": "这里误用了化学反应的说法。“反应”在此指人对事情的回应，人的反应不能“需要加热才能开始”，这种说法只适用于物质变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20354, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这只反应让我很意外。", "corrected_sentence": "他这种反应让我很意外。", "error_description": "量词错误：“反应”在此应使用量词“种”，不能用“只”。正确说法是“这种反应”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20354, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的反应了很大，把我吓了一跳。", "corrected_sentence": "他的反应很大，把我吓了一跳。", "error_description": "助词错误：“反应”与“很大”之间不能插入“了”，应说“他的反应很大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20356, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "增强", "is_correct": true, "explanation": "“增强”指变得比以前强，与“变弱、没有以前那么强”意义相反，构成反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”是一种日常活动，与“减弱”没有反义关系。"}, {"text": "休息", "is_correct": false, "explanation": "“休息”指停止工作或活动以恢复精力，与“减弱”没有反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "“思考”指用脑子分析问题，与“减弱”没有反义关系。"}], "correct_answer": "增强", "explanations": {"增强": "“增强”指变得比以前强，与“变弱、没有以前那么强”意义相反，构成反义关系。", "散步": "“散步”是一种日常活动，与“减弱”没有反义关系。", "休息": "“休息”指停止工作或活动以恢复精力，与“减弱”没有反义关系。", "思考": "“思考”指用脑子分析问题，与“减弱”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb381c-9fec-4f33-841d-281ecf246fc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20356, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "增强", "is_correct": true, "explanation": "“增强”指变得比以前强，与“变弱、没有以前那么强”意义相反，构成反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "“游泳”是一种体育活动，与“减弱”没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "“唱歌”指用声音表演歌曲，与“减弱”没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "“旅行”指到外地游览，与“减弱”没有反义关系。"}], "correct_answer": "增强", "explanations": {"增强": "“增强”指变得比以前强，与“变弱、没有以前那么强”意义相反，构成反义关系。", "游泳": "“游泳”是一种体育活动，与“减弱”没有反义关系。", "唱歌": "“唱歌”指用声音表演歌曲，与“减弱”没有反义关系。", "旅行": "“旅行”指到外地游览，与“减弱”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb381c-9fec-4f33-841d-281ecf246fc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20356, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "变弱了，没有以前那么强。", "primary_collocate": null, "pronunciation": "jiǎn ruò", "ipa": "tɕjɛn˨˩˦ ʐwo˧˥", "syllable_count": 2, "sentences": [{"text": "他的影响力比以前减弱了很多。", "target_word": "减弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年纪大了，奶奶的听力比以前减弱了。", "target_word": "减弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机的信号一进电梯就减弱了。", "target_word": "减弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比起去年，这家店的人气减弱了不少。", "target_word": "减弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "喝了热水以后，咳嗽比早上减弱了。", "target_word": "减弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那场雨过后，河水的流速已经减弱了。", "target_word": "减弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天来了，冬天的寒意已经减弱了。", "target_word": "减弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子长大后，对妈妈的依赖比小时候减弱了。", "target_word": "减弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗帘拉上以后，房间里的光线减弱了。", "target_word": "减弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他生病以后，体力比以前减弱了很多。", "target_word": "减弱", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "减弱了", "label": "完成体"}, {"form": "减弱过", "label": "经历体"}, {"form": "減弱", "label": "繁体"}], "register": "中性", "sense_fingerprint": "与以前相比变弱了，不如从前强", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fb865e3-8ed5-4241-8c43-69bb91bb5b7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20356, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "减弱", "is_correct": true, "explanation": "“减弱”指影响力变小，与“比以前…了很多”搭配，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象是歌曲，影响力不能“唱”。"}, {"text": "修理", "is_correct": false, "explanation": "配价：“修理”是人对具体物品的动作，“影响力”不能作“修理”的主语。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：“搬”的对象是有形的物体，不能用于“影响力”。"}], "explanations": {"减弱": "“减弱”指影响力变小，与“比以前…了很多”搭配，符合句意。", "唱": "语义：“唱”的对象是歌曲，影响力不能“唱”。", "修理": "配价：“修理”是人对具体物品的动作，“影响力”不能作“修理”的主语。", "搬": "搭配：“搬”的对象是有形的物体，不能用于“影响力”。"}, "sentence_index": 0, "correct_answer": "减弱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房间的面积比以前减弱了。", "explanation": "这里应该用〈缩小〉。“减弱”说力量、强度变弱，面积、空间变小要用“缩小”。"}, {"text": "这个月的销量比上个月减弱了。", "explanation": "这里应该用〈下降〉。“减弱”指力量、强度变小，销量这类数量的下降要用“下降”。"}, {"text": "今年的游客比去年减弱了。", "explanation": "这里应该用〈减少〉。“减弱”说力量、强度变弱，游客人数这类数量要用“减少”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb381c-9fec-4f33-841d-281ecf246fc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20356, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "减弱", "is_correct": true, "explanation": "“减弱”指寒意逐渐变弱，与“寒意已经…了”搭配，符合句意。"}, {"text": "报名", "is_correct": false, "explanation": "语义：“报名”是人参加活动的行为，寒意不能“报名”。"}, {"text": "烧毁", "is_correct": false, "explanation": "搭配：“烧毁”的对象是实物，不能用于“寒意”。"}, {"text": "发表", "is_correct": false, "explanation": "配价：“发表”需要宾语（发表文章、言论），不能用于“寒意”。"}], "explanations": {"减弱": "“减弱”指寒意逐渐变弱，与“寒意已经…了”搭配，符合句意。", "报名": "语义：“报名”是人参加活动的行为，寒意不能“报名”。", "烧毁": "搭配：“烧毁”的对象是实物，不能用于“寒意”。", "发表": "配价：“发表”需要宾语（发表文章、言论），不能用于“寒意”。"}, "sentence_index": 6, "correct_answer": "减弱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今年的开支减弱了一半。", "explanation": "这里应该用〈削减〉。“减弱”说力量、强度变弱，开支等数额的削减要用“削减”。"}, {"text": "这家公司的股价减弱了一成。", "explanation": "这里应该用〈下跌〉。“减弱”不用于股价的下降，股价下跌要用“下跌”。"}, {"text": "商品的价格减弱了不少。", "explanation": "这里应该用〈下降〉。“减弱”指力量、强度变小，商品价格的下降要用“下降”，不用“减弱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb381c-9fec-4f33-841d-281ecf246fc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20356, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店的人气比以前减弱地很厉害。", "corrected_sentence": "这家店的人气比以前减弱得很厉害。", "error_description": "补语前应用“得”，不用“地”。“地”修饰动词，如“慢慢地减弱”；“减弱得很厉害”中的“得”引出补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb381c-9fec-4f33-841d-281ecf246fc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20356, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子长大后，依赖慢慢减弱出来了。", "corrected_sentence": "孩子长大后，依赖慢慢减弱下来了。", "error_description": "表示逐渐变弱的结果，补语应用“下来”，不用“出来”；“减弱出来”不符合汉语的搭配习惯。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb381c-9fec-4f33-841d-281ecf246fc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
