INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20357, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "生物慢慢变成新的样子。", "primary_collocate": null, "pronunciation": "jìn huà", "ipa": "tɕin˥˩ xua˥˩", "syllable_count": 2, "sentences": [{"text": "有些恐龙慢慢进化成了鸟。", "target_word": "进化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "熊猫的祖先吃肉，后来慢慢进化成了爱吃竹子的动物。", "target_word": "进化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生物要适应环境，才会进化。", "target_word": "进化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鲸的祖先住在陆地上，后来进化成海里的动物。", "target_word": "进化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人类的祖先是猿，慢慢进化成人。", "target_word": "进化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种鸟的翅膀进化得很小，已经不会飞了。", "target_word": "进化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物进化需要很长很长的时间。", "target_word": "进化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你看，这只鸟的嘴进化得又细又长。", "target_word": "进化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过很多代，这种小鸟的脚进化得更适合抓树枝了。", "target_word": "进化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了躲开敌人，这种虫子进化得像树叶。", "target_word": "进化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "进化了", "label": "体标"}, {"form": "进化着", "label": "体标"}, {"form": "进化过", "label": "体标"}], "register": "中性", "sense_fingerprint": "生物随时间慢慢变成与以前不同的新样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb8ad67b-239f-4a6f-82cc-ce442b51a334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20357, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "进化", "is_correct": true, "explanation": "进化（jìn huà）：生物慢慢变成与以前不同的新样子。"}, {"text": "进货", "is_correct": false, "explanation": "进货（jìn huò）：第二音节 huò 与 huà 韵母不同，意思是购进商品。"}, {"text": "净化", "is_correct": false, "explanation": "净化（jìng huà）：第一音节 jìng 与 jìn 韵尾不同（ng 与 n），意思是使干净。"}, {"text": "金花", "is_correct": false, "explanation": "金花（jīn huā）：两个音节的声调都与 jìn huà 不同，意思是金色的花。"}], "explanations": {"进化": "进化（jìn huà）：生物慢慢变成与以前不同的新样子。", "进货": "进货（jìn huò）：第二音节 huò 与 huà 韵母不同，意思是购进商品。", "净化": "净化（jìng huà）：第一音节 jìng 与 jìn 韵尾不同（ng 与 n），意思是使干净。", "金花": "金花（jīn huā）：两个音节的声调都与 jìn huà 不同，意思是金色的花。"}, "sentence_index": null, "correct_answer": "进化"}, "level_3": {"options": [{"text": "进化", "is_correct": true, "explanation": "进化：表示生物慢慢变成新的样子，与“恐龙变成鸟”的语义一致。"}, {"text": "雕刻", "is_correct": false, "explanation": "语义：“雕刻”需要人施工，恐龙不能自己慢慢雕刻成鸟。"}, {"text": "烤", "is_correct": false, "explanation": "搭配：“烤”的结果多是食物，不能说恐龙烤成了鸟。"}, {"text": "织", "is_correct": false, "explanation": "搭配：“织”的结果是织物，与“鸟”搭配不当。"}], "explanations": {"进化": "进化：表示生物慢慢变成新的样子，与“恐龙变成鸟”的语义一致。", "雕刻": "语义：“雕刻”需要人施工，恐龙不能自己慢慢雕刻成鸟。", "烤": "搭配：“烤”的结果多是食物，不能说恐龙烤成了鸟。", "织": "搭配：“织”的结果是织物，与“鸟”搭配不当。"}, "sentence_index": 0, "correct_answer": "进化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这几天的气温进化了不少。", "explanation": "这里应该用〈下降〉或〈升高〉。进化指生物的适应性变化，气温的升降要用下降或升高。"}, {"text": "这条路比以前进化了一半。", "explanation": "这里应该用〈缩短〉。进化不用于长度的变短，路程变短要用缩短。"}, {"text": "这个月的花费进化了很多。", "explanation": "这里应该用〈增加〉。进化指生物的适应性变化，花费变多要用增加。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3448ed1d-9f75-4fae-beb3-c278fb39073e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20357, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进化", "is_correct": true, "explanation": "进化：指物种长期变化，与“动物需要很长时间”的语义一致。"}, {"text": "写作", "is_correct": false, "explanation": "语义：“写作”是人的创作活动，动物不能写作。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：“装饰”的主体通常是人，不说“动物装饰”。"}, {"text": "烹饪", "is_correct": false, "explanation": "搭配：“烹饪”需要人来做，与“动物”搭配不当。"}], "explanations": {"进化": "进化：指物种长期变化，与“动物需要很长时间”的语义一致。", "写作": "语义：“写作”是人的创作活动，动物不能写作。", "装饰": "搭配：“装饰”的主体通常是人，不说“动物装饰”。", "烹饪": "搭配：“烹饪”需要人来做，与“动物”搭配不当。"}, "sentence_index": 6, "correct_answer": "进化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个家的房子进化得很漂亮。", "explanation": "这里应该用〈装修〉。进化指生物的长期适应性变化，房屋的修饰要用装修。"}, {"text": "这门课我进化得很认真。", "explanation": "这里应该用〈学习〉。进化指物种的长期变化，学功课要用学习。"}, {"text": "他每天在健身房里进化得很结实。", "explanation": "这里应该用〈锻炼〉。进化不指人的体能训练，身体练得结实要用锻炼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3448ed1d-9f75-4fae-beb3-c278fb39073e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20357, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种恐龙慢慢进化了一种新的鸟。", "corrected_sentence": "这种恐龙慢慢进化成了一种新的鸟。", "error_description": "“进化”表示变成另一种东西时要带“成”。漏掉“成”，应为“进化成了一种新的鸟”。原句把“进化”当作及物动词带宾语，不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3448ed1d-9f75-4fae-beb3-c278fb39073e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20357, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "为了躲开敌人，这种虫子的颜色进化的很像树叶。", "corrected_sentence": "为了躲开敌人，这种虫子的颜色进化得很像树叶。", "error_description": "程度补语前要用“得”，不能用“的”。应为“进化得很像树叶”，写成“进化的很像树叶”不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3448ed1d-9f75-4fae-beb3-c278fb39073e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
