INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20360, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "对这件事", "primary_collocate": null, "pronunciation": "duì cǐ", "ipa": "tweɪ˥˩ tsʰɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "李明考得很好，老师对此很高兴。", "target_word": "对此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上堵车了，对此谁也没有办法。", "target_word": "对此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们吵架了，我对此不想多说。", "target_word": "对此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校要开新课，对此你有什么看法？", "target_word": "对此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛要改时间，对此大家都表示理解。", "target_word": "对此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生弄丢了图书馆的书，对此学校制定了新的规定。", "target_word": "对此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆很贵，客人们对此常常抱怨。", "target_word": "对此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友说要搬家，你对此是怎么想的？", "target_word": "对此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有来开会，对此经理很生气。", "target_word": "对此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说明年地铁会免费，对此你了解多少？", "target_word": "对此", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "对前面说的这件事，引出看法或做法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bc8c19a-b344-4816-9e61-2e91b5fa9608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20360, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对此", "is_correct": true, "explanation": "正确：指代前面说的“李明考得很好”这件事，引出老师的态度。"}, {"text": "对于", "is_correct": false, "explanation": "配价：「对于」后须接宾语，“老师对于很高兴”不成句。"}, {"text": "关于", "is_correct": false, "explanation": "配价：「关于」后须接话题，此处缺少宾语，不成句。"}, {"text": "至于", "is_correct": false, "explanation": "语义：「至于」引出另起的话题，不能表示老师对李明成绩的态度。"}], "explanations": {"对此": "正确：指代前面说的“李明考得很好”这件事，引出老师的态度。", "对于": "配价：「对于」后须接宾语，“老师对于很高兴”不成句。", "关于": "配价：「关于」后须接话题，此处缺少宾语，不成句。", "至于": "语义：「至于」引出另起的话题，不能表示老师对李明成绩的态度。"}, "sentence_index": 0, "correct_answer": "对此"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我正在做饭，对此门铃响了。", "explanation": "这里应该用〈此时〉。“对此”指针对前文的事情，不能表示时间。"}, {"text": "这个城市的交通很方便，对此，它的空气也很好。", "explanation": "这里应该用〈此外〉。“对此”针对前文的事情作出回应，补充新情况要用“此外”。"}, {"text": "他是我的好朋友，我对此很想念。", "explanation": "这里应该用〈他〉。“对此”只指事情或情况，不能指人，想念的对象要用人称代词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08d6a5a-8a71-44e5-b4f0-723d74e024c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20360, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对此", "is_correct": true, "explanation": "正确：指代前文“这家饭馆很贵”这件事，引出客人们的抱怨。"}, {"text": "根据", "is_correct": false, "explanation": "配价：「根据」后须接依据，“客人们根据常常抱怨”不成句。"}, {"text": "按照", "is_correct": false, "explanation": "配价：「按照」后须接依据或标准，此处没有宾语，不成句。"}, {"text": "鉴于", "is_correct": false, "explanation": "语义：「鉴于」表示原因，而这里表达的是客人的抱怨，前后意思不合。"}], "explanations": {"对此": "正确：指代前文“这家饭馆很贵”这件事，引出客人们的抱怨。", "根据": "配价：「根据」后须接依据，“客人们根据常常抱怨”不成句。", "按照": "配价：「按照」后须接依据或标准，此处没有宾语，不成句。", "鉴于": "语义：「鉴于」表示原因，而这里表达的是客人的抱怨，前后意思不合。"}, "sentence_index": 6, "correct_answer": "对此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次旅行很远，我对此坐了一天的火车。", "explanation": "这里应去掉〈对此〉。“对此”要引出对前文事情的态度，不能修饰动作。"}, {"text": "他走了很久的路，对此累坏了。", "explanation": "这里应该用〈于是〉。“对此”指针对前文的事情，不能表示因果。"}, {"text": "明天就考试了，对此我们今天去看电影。", "explanation": "这里应去掉〈对此〉。“对此”指代的内容与这句的动作没有关系，语义不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08d6a5a-8a71-44e5-b4f0-723d74e024c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20360, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天气变冷了，对此的我们都要多穿衣服。", "corrected_sentence": "天气变冷了，对此我们都要多穿衣服。", "error_description": "“对此”后的“的”使前面成为定语，修饰“我们”不通顺；“对此”作状语时应直接接主语：对此我们都要多穿衣服。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08d6a5a-8a71-44e5-b4f0-723d74e024c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20360, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个计划很好，对此了大家都同意。", "corrected_sentence": "这个计划很好，对此大家都同意。", "error_description": "“对此”后不能加“了”，“了”不能附在介词上。正确说法是“对此大家都同意”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08d6a5a-8a71-44e5-b4f0-723d74e024c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
