INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20366, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "最早开始的，还没有改变的。", "primary_collocate": null, "pronunciation": "yuán shǐ", "ipa": "ɥɛn˧˥ ʂʐ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "他们在原始森林里走了三天。", "target_word": "原始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很久以前，原始人住在山洞里。", "target_word": "原始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子还保持着原始的样子。", "target_word": "原始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有一些原始社会的石头工具。", "target_word": "原始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张图片是原始文件，没有改过。", "target_word": "原始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请保留原始数据，不要随便修改。", "target_word": "原始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座古城还留着原始的街道。", "target_word": "原始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是画家最原始的想法，后来改了很多。", "target_word": "原始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买东西要留好原始发票。", "target_word": "原始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的原始版本已经很难找到了。", "target_word": "原始", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "原始人", "label": "复合"}, {"form": "原始社会", "label": "复合"}, {"form": "原始森林", "label": "复合"}], "register": "中性", "sense_fingerprint": "最初的、未经改变的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e06a5-aa40-4d69-893b-a969f8b578f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20366, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "原始", "is_correct": true, "explanation": "原始 yuán shǐ：最早开始的，还没有改变的。"}, {"text": "原诗", "is_correct": false, "explanation": "原诗 yuán shī 第二音节为第一声，与原始 yuán shǐ（第三声）声调不同，意思是原作的诗。"}, {"text": "原石", "is_correct": false, "explanation": "原石 yuán shí 第二音节为第二声，与原始 yuán shǐ（第三声）声调不同，意思是未加工的矿石。"}, {"text": "远视", "is_correct": false, "explanation": "远视 yuǎn shì 两个音节的声调都与原始 yuán shǐ 不同，意思是远视眼。"}, {"text": "原水", "is_correct": false, "explanation": "原水 yuán shuǐ 第二音节多出 u 介音，与原始 shǐ 的韵母不同，意思是未经处理的水。"}], "explanations": {"原始": "原始 yuán shǐ：最早开始的，还没有改变的。", "原诗": "原诗 yuán shī 第二音节为第一声，与原始 yuán shǐ（第三声）声调不同，意思是原作的诗。", "原石": "原石 yuán shí 第二音节为第二声，与原始 yuán shǐ（第三声）声调不同，意思是未加工的矿石。", "远视": "远视 yuǎn shì 两个音节的声调都与原始 yuán shǐ 不同，意思是远视眼。", "原水": "原水 yuán shuǐ 第二音节多出 u 介音，与原始 shǐ 的韵母不同，意思是未经处理的水。"}, "sentence_index": null, "correct_answer": "原始"}, "level_3": {"options": [{"text": "原始", "is_correct": true, "explanation": "正确：原始森林指未经人类开发的天然森林，与“走了三天”的描述相符。"}, {"text": "繁华", "is_correct": false, "explanation": "语义：“繁华”指商业街市热闹，不能用来形容森林。"}, {"text": "现代", "is_correct": false, "explanation": "语义：“现代”指当代，与未经开发的森林状态相矛盾。"}, {"text": "高级", "is_correct": false, "explanation": "搭配：“高级”多修饰档次和等级，不能说高级森林。"}], "explanations": {"原始": "正确：原始森林指未经人类开发的天然森林，与“走了三天”的描述相符。", "繁华": "语义：“繁华”指商业街市热闹，不能用来形容森林。", "现代": "语义：“现代”指当代，与未经开发的森林状态相矛盾。", "高级": "搭配：“高级”多修饰档次和等级，不能说高级森林。"}, "sentence_index": 0, "correct_answer": "原始"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们原始住在城里，后来才搬到乡下。", "explanation": "这里应该用〈原来〉。原始是形容词，不能作状语表示以前的情况，应说〈原来〉。"}, {"text": "这座桥原始通车了，大家都很高兴。", "explanation": "这里应该用〈已经〉。原始是形容词，不能修饰动词“通车”，应说“已经通车”。"}, {"text": "他把房间原始了一下，看起来干净多了。", "explanation": "这里应该用〈收拾〉。原始是形容词，不能当动词用，整理房间要说收拾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8e394ba-5d70-4d05-976c-ff686d21fbf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20366, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "原始", "is_correct": true, "explanation": "原始 yuán shǐ：最早开始的，还没有改变的。"}, {"text": "原式", "is_correct": false, "explanation": "原式 yuán shì 第二音节为第四声，与原始 yuán shǐ（第三声）声调不同，意思是原来的算式或格式。"}, {"text": "院士", "is_correct": false, "explanation": "院士 yuàn shì 两个音节的声调都与原始 yuán shǐ 不同，意思是院士。"}, {"text": "缘石", "is_correct": false, "explanation": "缘石 yuán shí 第二音节为第二声，与原始 yuán shǐ（第三声）声调不同，意思是路边的路缘石。"}], "explanations": {"原始": "原始 yuán shǐ：最早开始的，还没有改变的。", "原式": "原式 yuán shì 第二音节为第四声，与原始 yuán shǐ（第三声）声调不同，意思是原来的算式或格式。", "院士": "院士 yuàn shì 两个音节的声调都与原始 yuán shǐ 不同，意思是院士。", "缘石": "缘石 yuán shí 第二音节为第二声，与原始 yuán shǐ（第三声）声调不同，意思是路边的路缘石。"}, "sentence_index": null, "correct_answer": "原始"}, "level_3": {"options": [{"text": "原始", "is_correct": true, "explanation": "正确：原始的街道指保持最初样貌、未经改动的街道，与“还留着”相符。"}, {"text": "崭新", "is_correct": false, "explanation": "语义：“崭新”指刚出现的新样子，与“还留着”的旧貌相矛盾。"}, {"text": "透明", "is_correct": false, "explanation": "搭配：“透明”形容物体可以透光，不能形容街道。"}, {"text": "摩登", "is_correct": false, "explanation": "语义：“摩登”指时髦现代，与古城的旧街道相矛盾。"}], "explanations": {"原始": "正确：原始的街道指保持最初样貌、未经改动的街道，与“还留着”相符。", "崭新": "语义：“崭新”指刚出现的新样子，与“还留着”的旧貌相矛盾。", "透明": "搭配：“透明”形容物体可以透光，不能形容街道。", "摩登": "语义：“摩登”指时髦现代，与古城的旧街道相矛盾。"}, "sentence_index": 6, "correct_answer": "原始"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他原始没来上课，老师很担心。", "explanation": "这里应该用〈一直〉。原始是形容词，不能作副词表示“一直没来”，应说“一直没来上课”。"}, {"text": "妈妈原始做了一桌好菜，大家都夸她。", "explanation": "这里应该用〈亲手〉。原始是形容词，不能作动词状语，亲自动手做菜要说〈亲手〉。"}, {"text": "他把书架原始了一遍，摆得整整齐齐。", "explanation": "这里应该用〈整理〉。原始是形容词，不能当动词用，整理书架要说整理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8e394ba-5d70-4d05-976c-ff686d21fbf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20366, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片湖还保持着原始了的模样。", "corrected_sentence": "这片湖还保持着原始的模样。", "error_description": "错误在于“原始”后的“的”误写成“了”：“原始”修饰名词时要用“的”，不能用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8e394ba-5d70-4d05-976c-ff686d21fbf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20366, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请把原始地照片发给我。", "corrected_sentence": "请把原始的照片发给我。", "error_description": "错误在于“原始”后的结构助词：“原始”修饰名词“照片”时要用“的”，不能用“地”（“地”用于修饰动词）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8e394ba-5d70-4d05-976c-ff686d21fbf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
