INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20368, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示过去曾经发生过某种行为或存在过某种情况。", "primary_collocate": null, "pronunciation": "céng", "ipa": "tsʰɤŋ˧˥", "syllable_count": 1, "sentences": [{"text": "我小时候曾在这里住过。", "target_word": "曾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他曾去过三次日本。", "target_word": "曾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师曾教过我数学。", "target_word": "曾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时曾当过兵。", "target_word": "曾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们曾是好朋友，现在不常联系了。", "target_word": "曾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她曾说过，将来要去国外工作。", "target_word": "曾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市十年前曾有一条小河。", "target_word": "曾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他曾想放弃，但朋友一直鼓励他。", "target_word": "曾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我曾在那家医院工作了五年。", "target_word": "曾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小喜欢画画，也曾得过奖。", "target_word": "曾", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "曾经", "label": "复合"}, {"form": "未曾", "label": "复合"}], "register": "书面", "sense_fingerprint": "副词，表示以前发生过某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c4848e3-df86-4870-9771-0c70385a07a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20368, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "曾", "is_correct": true, "explanation": "正确：曾（第二声）表示以前发生过某事。"}, {"text": "岑", "is_correct": false, "explanation": "cén 与 céng 韵母不同（en/eng），声调相同，是姓氏。"}, {"text": "城", "is_correct": false, "explanation": "chéng 与 céng 声母不同（ch/c），声调相同，意思是城市。"}, {"text": "蹭", "is_correct": false, "explanation": "cèng 与 céng 声调不同，意思是蹭（如蹭饭）。"}], "explanations": {"曾": "正确：曾（第二声）表示以前发生过某事。", "岑": "cén 与 céng 韵母不同（en/eng），声调相同，是姓氏。", "城": "chéng 与 céng 声母不同（ch/c），声调相同，意思是城市。", "蹭": "cèng 与 céng 声调不同，意思是蹭（如蹭饭）。"}, "sentence_index": null, "correct_answer": "曾"}, "level_3": {"options": [{"text": "曾", "is_correct": true, "explanation": "正确：“曾”表示以前发生过，与“小时候……住过”的过去经历相符。"}, {"text": "刚", "is_correct": false, "explanation": "语义：“刚”表示刚发生的事，与“小时候”的久远时间冲突。"}, {"text": "正在", "is_correct": false, "explanation": "语义：“正在”表示进行中，与“小时候住过”的过去经历不符。"}, {"text": "将", "is_correct": false, "explanation": "体貌：“将”表示将要发生，与“小时候”及“过”所表示的已完成经历冲突。"}], "explanations": {"曾": "正确：“曾”表示以前发生过，与“小时候……住过”的过去经历相符。", "刚": "语义：“刚”表示刚发生的事，与“小时候”的久远时间冲突。", "正在": "语义：“正在”表示进行中，与“小时候住过”的过去经历不符。", "将": "体貌：“将”表示将要发生，与“小时候”及“过”所表示的已完成经历冲突。"}, "sentence_index": 0, "correct_answer": "曾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他曾在写作业，别打扰他。", "explanation": "这里应该用〈正在〉。曾表示过去经历，描述眼下进行中的动作要用正在。"}, {"text": "我曾到家，还没吃饭。", "explanation": "这里应该用〈刚〉。曾指过去有过的经历，刚发生的动作要用刚。"}, {"text": "下个月，我曾陪父母去海边旅游。", "explanation": "这里应该用〈会〉。曾说明已经发生过的事，说明未来的事情要用会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20368, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "曾", "is_correct": true, "explanation": "正确：曾（第二声）表示以前发生过某事。"}, {"text": "从", "is_correct": false, "explanation": "cóng 与 céng 韵母不同（ong/eng），声调相同，意思是从、自。"}, {"text": "藏", "is_correct": false, "explanation": "cáng 与 céng 韵母不同（ang/eng），声调相同，意思是隐藏。"}, {"text": "增", "is_correct": false, "explanation": "zēng 与 céng 声母（z/c）和声调都不同，意思是增加。"}], "explanations": {"曾": "正确：曾（第二声）表示以前发生过某事。", "从": "cóng 与 céng 韵母不同（ong/eng），声调相同，意思是从、自。", "藏": "cáng 与 céng 韵母不同（ang/eng），声调相同，意思是隐藏。", "增": "zēng 与 céng 声母（z/c）和声调都不同，意思是增加。"}, "sentence_index": null, "correct_answer": "曾"}, "level_3": {"options": [{"text": "曾", "is_correct": true, "explanation": "正确：“曾”表示过去有过，与“十年前”的过去时间相符。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示即刻发生，与“十年前”的过去时间矛盾。"}, {"text": "很快", "is_correct": false, "explanation": "语义：“很快”表示不久之后，与“十年前”的过去时间矛盾。"}, {"text": "即将", "is_correct": false, "explanation": "体貌：“即将”表示将要发生，与“十年前”的已过去时间不符。"}], "explanations": {"曾": "正确：“曾”表示过去有过，与“十年前”的过去时间相符。", "马上": "语义：“马上”表示即刻发生，与“十年前”的过去时间矛盾。", "很快": "语义：“很快”表示不久之后，与“十年前”的过去时间矛盾。", "即将": "体貌：“即将”表示将要发生，与“十年前”的已过去时间不符。"}, "sentence_index": 6, "correct_answer": "曾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们明天曾去北京旅行。", "explanation": "这里应该用〈要〉。曾说明已经发生过的事，说明明天的计划要用要。"}, {"text": "他曾在等你，现在还没走。", "explanation": "这里应该用〈一直〉。曾指过去有过的经历，持续到现在要用一直。"}, {"text": "我昨天曾收到他的信，比预想的晚。", "explanation": "这里应该用〈才〉。才表示时间晚或刚刚发生，曾只说明过去有过这种经历。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20368, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我小时候养曾过一只猫。", "corrected_sentence": "我小时候曾养过一只猫。", "error_description": "“曾”是副词，应放在动词前：“养曾过”应为“曾养过”，不能放在动词后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20368, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈明年曾去很多城市。", "corrected_sentence": "妈妈明年要去很多城市。", "error_description": "“曾”表示过去的经历，不能用于“明年”这样的将来时间；将来的安排应改用“要”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
