INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20370, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "喜欢成群住在一起、互相帮助的动物。", "primary_collocate": null, "pronunciation": "qún jū dòng wù", "ipa": "tɕʰyn˧˥ tɕy˥ tʊŋ˥˩ u˥˩", "syllable_count": 4, "sentences": [{"text": "企鹅是群居动物，天冷时挤在一起。", "target_word": "群居动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猴子是群居动物，每天一起玩。", "target_word": "群居动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "羊是群居动物，总是跟着羊群走。", "target_word": "群居动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜜蜂是群居动物，一个蜂巢里有很多蜜蜂。", "target_word": "群居动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "群居动物会互相帮助，一起找吃的。", "target_word": "群居动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "斑马是群居动物，它们总是一起吃草。", "target_word": "群居动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狮子也是群居动物，一家子住在一起。", "target_word": "群居动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "群居动物不喜欢独自生活。", "target_word": "群居动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狗是群居动物，不喜欢一直独自在家。", "target_word": "群居动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海豚是群居动物，常常几十只一起游。", "target_word": "群居动物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种群居动物", "label": "量词"}, {"form": "群居動物", "label": "繁体"}], "register": "中性", "sense_fingerprint": "群居动物:喜欢住在一起、互相帮助的动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e27744d-182f-47c3-87f2-2fd95c884f94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20370, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "群居动物", "is_correct": true, "explanation": "正确：企鹅属于群居动物，天冷时挤在一起，与句意一致。"}, {"text": "独居动物", "is_correct": false, "explanation": "语义：独居动物不会挤在一起，与“天冷时挤在一起”冲突。"}, {"text": "植物", "is_correct": false, "explanation": "语义：企鹅是动物，植物不能“挤在一起”取暖，句意不通。"}, {"text": "机器人", "is_correct": false, "explanation": "体貌：机器人没有羽毛和体温，不会因天冷而挤在一起取暖。"}], "explanations": {"群居动物": "正确：企鹅属于群居动物，天冷时挤在一起，与句意一致。", "独居动物": "语义：独居动物不会挤在一起，与“天冷时挤在一起”冲突。", "植物": "语义：企鹅是动物，植物不能“挤在一起”取暖，句意不通。", "机器人": "体貌：机器人没有羽毛和体温，不会因天冷而挤在一起取暖。"}, "sentence_index": 0, "correct_answer": "群居动物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这棵大树是群居动物，树枝上挤满了鸟。", "explanation": "“群居动物”指动物，大树是植物，不能用这个词称呼树。"}, {"text": "这家公司是群居动物，员工大多住在一起。", "explanation": "“群居动物”指生物，公司是组织，不能这样称呼它。"}, {"text": "这张书桌是群居动物，上面摆满了书。", "explanation": "“群居动物”指动物，书桌是家具，这里误用了这个词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ca0217-3edd-42bd-960a-febe13752150') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20370, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "群居动物", "is_correct": true, "explanation": "正确：狮子属于群居动物，“一家子住在一起”与群居的特点相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：狮子不是石头，石头没有家庭，句意不通。"}, {"text": "玩具", "is_correct": false, "explanation": "体貌：玩具没有生命，无法像狮子那样组成一家子住在一起。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵是植物，不能与狮子并列，也不能“一家子住在一起”。"}], "explanations": {"群居动物": "正确：狮子属于群居动物，“一家子住在一起”与群居的特点相符。", "石头": "语义：狮子不是石头，石头没有家庭，句意不通。", "玩具": "体貌：玩具没有生命，无法像狮子那样组成一家子住在一起。", "花朵": "语义：花朵是植物，不能与狮子并列，也不能“一家子住在一起”。"}, "sentence_index": 6, "correct_answer": "群居动物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台冰箱是群居动物，里面装满了食物。", "explanation": "“群居动物”指动物，冰箱是家电，不能这样称呼它。"}, {"text": "这条河流是群居动物，两岸住着很多人。", "explanation": "“群居动物”指动物，河流是自然地理事物，这里误用了这个词。"}, {"text": "这本课本是群居动物，每一章都有练习。", "explanation": "“群居动物”指动物，课本是书，不能用这个词来描述它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ca0217-3edd-42bd-960a-febe13752150') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20370, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "猴子是一只群居动物，喜欢一起玩耍。", "corrected_sentence": "猴子是一种群居动物，喜欢一起玩耍。", "error_description": "量词错误：“只”用于具体的一只动物，说“群居动物”这一类别时应用“种”。正确说法是“猴子是一种群居动物，喜欢一起玩耍。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ca0217-3edd-42bd-960a-febe13752150') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20370, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种的群居动物不喜欢独自生活。", "corrected_sentence": "这种群居动物不喜欢独自生活。", "error_description": "多余的“的”：“这种”直接修饰名词，中间不加“的”。正确说法是“这种群居动物不喜欢独自生活。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ca0217-3edd-42bd-960a-febe13752150') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
