INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20374, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用来做某件事。", "primary_collocate": null, "pronunciation": "yòng yú", "ipa": "jʊŋ˥˩ y˧˥", "syllable_count": 2, "sentences": [{"text": "这笔钱用于买新书。", "target_word": "用于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间只用于开会。", "target_word": "用于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水不能用于做饭。", "target_word": "用于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些书主要用于教学。", "target_word": "用于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器用于做蛋糕。", "target_word": "用于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔资金主要用于改善农村的医疗条件。", "target_word": "用于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把时间都用于学习。", "target_word": "用于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种纸可以用于画画。", "target_word": "用于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校把这块地用于运动。", "target_word": "用于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个本子用于写日记。", "target_word": "用于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "用於", "label": "繁体"}], "register": "书面", "sense_fingerprint": "用于：用在某方面或用来做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09aebaf0-be95-4ef2-b319-0da839c40a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20374, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "用于", "is_correct": true, "explanation": "用于：用来做某事。这里指这笔钱用来买书，与语境相符。"}, {"text": "决定", "is_correct": false, "explanation": "语义：“决定”的主语须是能做决定的人，“这笔钱”不能决定买书。"}, {"text": "想", "is_correct": false, "explanation": "语义：“想”表示心里有念头，“这笔钱”不能想买书。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，“这笔钱”不能吃，句子不通。"}], "explanations": {"用于": "用于：用来做某事。这里指这笔钱用来买书，与语境相符。", "决定": "语义：“决定”的主语须是能做决定的人，“这笔钱”不能决定买书。", "想": "语义：“想”表示心里有念头，“这笔钱”不能想买书。", "吃": "语义：“吃”的对象是食物，“这笔钱”不能吃，句子不通。"}, "sentence_index": 0, "correct_answer": "用于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把这笔钱用于朋友。", "explanation": "这里应该用〈给〉。用于后接的是事情或领域，不直接指人，送给人要用〈给〉。"}, {"text": "这个旧箱子用于桌子。", "explanation": "这里应该用〈用作〉。用于表示用在某方面，把东西当作某物要用〈用作〉。"}, {"text": "他用于这些钱买电脑。", "explanation": "这里应该用〈用〉。用于后接的是用途或领域，不能直接带钱款作工具；用这些钱买东西要用〈用〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20374, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "用于", "is_correct": true, "explanation": "用于：用在某方面。这里指时间都用在学习上，与语境相符。"}, {"text": "浪费", "is_correct": false, "explanation": "搭配：“浪费”后接的是时间、钱等，不能直接带“学习”。"}, {"text": "考虑", "is_correct": false, "explanation": "语义：“时间”不能考虑什么，“把时间都考虑”不通。"}, {"text": "花费", "is_correct": false, "explanation": "搭配：“花费”要带数量或成本，如“花费时间”，不能直接接“学习”。"}], "explanations": {"用于": "用于：用在某方面。这里指时间都用在学习上，与语境相符。", "浪费": "搭配：“浪费”后接的是时间、钱等，不能直接带“学习”。", "考虑": "语义：“时间”不能考虑什么，“把时间都考虑”不通。", "花费": "搭配：“花费”要带数量或成本，如“花费时间”，不能直接接“学习”。"}, "sentence_index": 6, "correct_answer": "用于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用于铅笔写字。", "explanation": "这里应该用〈用〉。用铅笔写字表示工具；用于后接的是用途或领域，不接工具。"}, {"text": "我每天用于公交车上学。", "explanation": "这里应该用〈坐〉。用于后接用途，不接交通工具；坐公交车上学要用〈坐〉。"}, {"text": "我们在这个房间用于午饭。", "explanation": "这里应该用〈吃〉。用于后接的是用途，不接饭食；在房间里吃午饭要用〈吃〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20374, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些钱用于了买书。", "corrected_sentence": "这些钱用于买书。", "error_description": "错误：“用于”之后不应直接加“了”。正确：“这些钱用于买书。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20374, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些纸只用于的写字。", "corrected_sentence": "这些纸只用于写字。", "error_description": "错误：“用于”之后多加了“的”，应直接接动词“写字”，不能加“的”。正确：“这些纸只用于写字。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
