INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20376, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示可能，但不太确定。", "primary_collocate": null, "pronunciation": "huò xǔ", "ipa": "xwo˥˩ ɕy˨˩˦", "syllable_count": 2, "sentences": [{"text": "他今天没来，或许生病了。", "target_word": "或许", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天或许会下雨。", "target_word": "或许", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她或许不知道这件事。", "target_word": "或许", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你再试一次，或许能成功。", "target_word": "或许", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在走，或许还来得及。", "target_word": "或许", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的电话关机了，或许在开会。", "target_word": "或许", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们或许可以坐地铁去。", "target_word": "或许", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今年冬天或许会比去年冷。", "target_word": "或许", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题很难，或许老师知道答案。", "target_word": "或许", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看起来很累，或许昨晚没睡好。", "target_word": "或许", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "表示推测，事情可能发生但不确定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '245410d8-ef7c-4e0b-b864-35d4e472cd06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20376, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "或许", "is_correct": true, "explanation": "“或许”表示推测，说话人不确定他是否生病，符合“今天没来”的原因猜测。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示即刻发生，与“今天没来”这一已发生的事实不符。"}, {"text": "通常", "is_correct": false, "explanation": "语义：“通常”表示习惯性的情况，与“今天没来”这一次性事件矛盾。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”需与“没”“不”等否定词呼应，不能直接用于肯定句“生病了”。"}], "explanations": {"或许": "“或许”表示推测，说话人不确定他是否生病，符合“今天没来”的原因猜测。", "马上": "语义：“马上”表示即刻发生，与“今天没来”这一已发生的事实不符。", "通常": "语义：“通常”表示习惯性的情况，与“今天没来”这一次性事件矛盾。", "从来": "搭配：“从来”需与“没”“不”等否定词呼应，不能直接用于肯定句“生病了”。"}, "sentence_index": 0, "correct_answer": "或许"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的名字是李华，或许我叫李华。", "explanation": "“或许”表示不确定，而说话人对自己的名字非常确定，不能用“或许”来猜测。"}, {"text": "你或许赶快去医院吧。", "explanation": "“或许”只表示推测，不能用于“赶快去医院吧”这样的命令或催促。"}, {"text": "太阳从东边升起，或许是事实。", "explanation": "“或许”表示说话人不确定，而太阳从东边升起是确定的事实，不能用“或许”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20376, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "或许", "is_correct": true, "explanation": "“或许”表示推测和委婉的语气，符合“我们可以坐地铁去”的提议。"}, {"text": "只好", "is_correct": false, "explanation": "语义：“只好”表示无可奈何的选择，后面应接动作，不能放在能愿动词“可以”之前。"}, {"text": "千万", "is_correct": false, "explanation": "搭配：“千万”通常与“要”“别”“不要”等搭配，不能用于“可以”之前。"}, {"text": "特意", "is_correct": false, "explanation": "语义：“特意”表示有意而为，与“可以坐地铁去”所表示的可能性不搭。"}], "explanations": {"或许": "“或许”表示推测和委婉的语气，符合“我们可以坐地铁去”的提议。", "只好": "语义：“只好”表示无可奈何的选择，后面应接动作，不能放在能愿动词“可以”之前。", "千万": "搭配：“千万”通常与“要”“别”“不要”等搭配，不能用于“可以”之前。", "特意": "语义：“特意”表示有意而为，与“可以坐地铁去”所表示的可能性不搭。"}, "sentence_index": 6, "correct_answer": "或许"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我已经决定明天去上海，所以或许明天去上海。", "explanation": "“或许”表示不确定，与“已经决定”的确定语气矛盾，应直接说“明天去上海”。"}, {"text": "班里一共有三十个学生，或许有三十个。", "explanation": "“或许”表示推测，而人数是确定的，不能用“或许”来说明。"}, {"text": "我们每天晚上七点吃饭，或许七点吃饭。", "explanation": "“或许”表示不确定，而每天晚上七点吃饭是习惯，说话人对此很确定，不能用“或许”来说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20376, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他今天没来，或许的堵车了。", "corrected_sentence": "他今天没来，或许堵车了。", "error_description": "“或许”是副词，后面不能加“的”。应说“或许堵车了”，不能说“或许的堵车了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20376, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们或许的可以先吃饭再走。", "corrected_sentence": "我们或许可以先吃饭再走。", "error_description": "“或许”是副词，后面不能直接加“的”。应说“我们或许可以先吃饭再走”，不能说“我们或许的可以先吃饭再走”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20378, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "散步", "is_correct": false, "explanation": "与“存在”无反义关系：“散步”指慢慢走路，与存在的意思无关。"}, {"text": "唱歌", "is_correct": false, "explanation": "与“存在”无反义关系：“唱歌”是发声歌唱，与有、在的意思不相对。"}, {"text": "旅行", "is_correct": false, "explanation": "与“存在”无反义关系：“旅行”指到外地游览，与存在的意思无关。"}, {"text": "消失", "is_correct": true, "explanation": "反义：“消失”表示不再存在、不见了，与“存在”意思相对。"}], "correct_answer": "消失", "explanations": {"散步": "与“存在”无反义关系：“散步”指慢慢走路，与存在的意思无关。", "唱歌": "与“存在”无反义关系：“唱歌”是发声歌唱，与有、在的意思不相对。", "旅行": "与“存在”无反义关系：“旅行”指到外地游览，与存在的意思无关。", "消失": "反义：“消失”表示不再存在、不见了，与“存在”意思相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6a508f-426a-42aa-b89b-6dcb0bf909c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
