INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20378, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个问题在很多年前就存在着了。", "corrected_sentence": "这个问题在很多年前就存在了。", "error_description": "体标错误：“着”表示持续状态，与表示完成的“了”不能同时用在“存在”后面。应为「这个问题在很多年前就存在了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6a508f-426a-42aa-b89b-6dcb0bf909c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
