INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20380, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "小心坏人，注意安全。", "primary_collocate": null, "pronunciation": "jǐng jiè", "ipa": "tɕiŋ˨˩ tɕjɛ˥˩", "syllable_count": 2, "sentences": [{"text": "夜里走路，要对陌生人保持警戒。", "target_word": "警戒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈告诉我，对坏人要保持警戒。", "target_word": "警戒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个人走夜路时，要提高警戒。", "target_word": "警戒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区门口有保安在警戒。", "target_word": "警戒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走夜路时一直警戒着，怕有坏人跟着。", "target_word": "警戒", "complexity_tier": "T3", "furigana": "tā zǒu yè lù shí yì zhí jǐng jiè zhe，pà yǒu huài rén gēn zhe。", "sentence_source": "generated"}, {"text": "出门旅行，要对小偷保持警戒。", "target_word": "警戒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狗听到声音，马上警戒起来。", "target_word": "警戒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面人多，你要对小偷保持警戒，别丢了钱包。", "target_word": "警戒", "complexity_tier": "T3", "furigana": "wài miàn rén duō，nǐ yào duì xiǎo tōu bǎo chí jǐng jiè，bié diū le qián bāo。", "sentence_source": "generated"}, {"text": "上网时也要保持警戒，别告诉陌生人密码。", "target_word": "警戒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察说，夜里大家都要加强警戒。", "target_word": "警戒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "警戒着", "label": "体标"}, {"form": "警戒过", "label": "体标"}, {"form": "警戒线", "label": "复合"}, {"form": "警戒状态", "label": "复合"}], "register": "中性", "sense_fingerprint": "警戒:小心坏人、注意安全", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e27744d-182f-47c3-87f2-2fd95c884f94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20380, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "警戒", "is_correct": true, "explanation": "保持警戒指对陌生人保持防范之心，符合夜里走路注意安全的要求。"}, {"text": "放松", "is_correct": false, "explanation": "语义：“放松”与“对陌生人要保持……”的防范要求相反。"}, {"text": "亲近", "is_correct": false, "explanation": "语义：“亲近”与夜里走路时对陌生人的防范意思相反。"}, {"text": "信任", "is_correct": false, "explanation": "搭配：“保持信任”后接“陌生人”与夜里走路的安全语境矛盾，句意不通。"}], "explanations": {"警戒": "保持警戒指对陌生人保持防范之心，符合夜里走路注意安全的要求。", "放松": "语义：“放松”与“对陌生人要保持……”的防范要求相反。", "亲近": "语义：“亲近”与夜里走路时对陌生人的防范意思相反。", "信任": "搭配：“保持信任”后接“陌生人”与夜里走路的安全语境矛盾，句意不通。"}, "sentence_index": 0, "correct_answer": "警戒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "走路时要警戒台阶。", "explanation": "这里应该用〈小心〉。“小心”可用于台阶等具体事物，“警戒”针对坏人或危险，不能用于台阶。"}, {"text": "吃饭前要警戒卫生。", "explanation": "这里应该用〈注意〉。“注意卫生”是常用搭配，“警戒”不能与卫生搭配。"}, {"text": "老师警戒了我的作业。", "explanation": "这里应该用〈表扬〉。“表扬”用于对好的作业等给予称赞；“警戒”针对坏人或危险，作业不是防备对象，不能用“警戒”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ca0217-3edd-42bd-960a-febe13752150') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20380, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "警戒", "is_correct": true, "explanation": "警戒起来指狗听到声音后进入警觉状态，符合句意。"}, {"text": "笑", "is_correct": false, "explanation": "语义：狗听到声音后“笑起来”与警觉的反应矛盾。"}, {"text": "唱", "is_correct": false, "explanation": "体貌：狗不会唱歌，“唱起来”不符合动物听到声音的身体反应。"}, {"text": "讲", "is_correct": false, "explanation": "语义：“讲起来”指开口说话，狗听到声音不会说话，与句意不符。"}], "explanations": {"警戒": "警戒起来指狗听到声音后进入警觉状态，符合句意。", "笑": "语义：狗听到声音后“笑起来”与警觉的反应矛盾。", "唱": "体貌：狗不会唱歌，“唱起来”不符合动物听到声音的身体反应。", "讲": "语义：“讲起来”指开口说话，狗听到声音不会说话，与句意不符。"}, "sentence_index": 6, "correct_answer": "警戒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新年晚会上，大家都在警戒着彩灯。", "explanation": "这里应该用〈欣赏〉。“欣赏”用于观赏彩灯等美好的事物；“警戒”针对坏人或危险，彩灯不构成威胁，不能作为防备的对象。"}, {"text": "放学后，我一直警戒着我的好朋友。", "explanation": "这里应该用〈陪伴〉。“陪伴”指与朋友相处，表示友好；“警戒”含防备之意，把好朋友当作防范对象，与句意相悖。"}, {"text": "我们去海边玩，她警戒着大海的风景。", "explanation": "这里应该用〈眺望〉。“眺望”指远望风景，用于大海的风景；“警戒”针对坏人或危险，风景不是防备对象，不能用“警戒”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ca0217-3edd-42bd-960a-febe13752150') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20380, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她深夜回家时一直警戒过，怕有人跟踪。", "corrected_sentence": "她深夜回家时一直警戒着，怕有人跟踪。", "error_description": "错误：“警戒过”；正确：“警戒着”。“过”表示经历过某事，与“一直”表示的持续状态矛盾，持续状态应用“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ca0217-3edd-42bd-960a-febe13752150') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20380, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "深夜里，他一直警戒了，不敢睡觉。", "corrected_sentence": "深夜里，他一直警戒着，不敢睡觉。", "error_description": "错误：“一直警戒了”；正确：“一直警戒着”。“了”表示完成，与“一直”表示的持续戒备不符，持续状态应用“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ca0217-3edd-42bd-960a-febe13752150') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
