INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20388, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "承受并支撑重量，或担负责任、保存记忆。", "primary_collocate": null, "pronunciation": "chéng zài", "ipa": "ʈʂʰɤŋ³⁵ tsaɪ̯⁵¹", "syllable_count": 2, "sentences": [{"text": "这座桥能承载很重的卡车。", "target_word": "承载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条船最多承载五十个人。", "target_word": "承载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个书架承载不了这么多书。", "target_word": "承载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老城墙承载着这座城市的历史。", "target_word": "承载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本旧相册承载了我们家的回忆。", "target_word": "承载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地面承载着房子的全部重量。", "target_word": "承载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根绳子承载不了你的体重。", "target_word": "承载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的肩上承载着全家人的希望。", "target_word": "承载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高速公路每天承载大量的车辆。", "target_word": "承载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个货架最多承载两百公斤的货物。", "target_word": "承载", "complexity_tier": "T3", "furigana": "chéngzài", "sentence_source": "generated"}], "morphological_forms": [{"form": "承载了", "label": "体标"}, {"form": "承载着", "label": "体标"}, {"form": "承载力", "label": "复合"}, {"form": "承載", "label": "繁体"}], "register": "书面", "sense_fingerprint": "承受并装载重量、物品，或担负责任、记忆等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d56d81d-7b32-4ed2-b81f-faaa77360a2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20388, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "承载", "is_correct": true, "explanation": "“承载”意思是承受并装载重量，或担负责任。"}, {"text": "长在", "is_correct": false, "explanation": "cháng 与 chéng 韵母不同（ang／eng），“长在”意思是生长于某处。"}, {"text": "曾在", "is_correct": false, "explanation": "céng 与 chéng 声母不同（c／ch），“曾在”意思是以前在某处。"}, {"text": "成灾", "is_correct": false, "explanation": "zāi（第一声）与 zài（第四声）声调不同，“成灾”意思是形成灾害。"}], "explanations": {"承载": "“承载”意思是承受并装载重量，或担负责任。", "长在": "cháng 与 chéng 韵母不同（ang／eng），“长在”意思是生长于某处。", "曾在": "céng 与 chéng 声母不同（c／ch），“曾在”意思是以前在某处。", "成灾": "zāi（第一声）与 zài（第四声）声调不同，“成灾”意思是形成灾害。"}, "sentence_index": null, "correct_answer": "承载"}, "level_3": {"options": [{"text": "承载", "is_correct": true, "explanation": "“承载”指承受并支撑很重的物体，正符合桥梁承重的句意。"}, {"text": "修理", "is_correct": false, "explanation": "语义：桥梁不能修理卡车，“修理”的对象是坏了的物件，与句意不合。"}, {"text": "停留", "is_correct": false, "explanation": "配价：“停留”是不及物动词，不能带“卡车”作宾语。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：桥梁不能欣赏卡车，“欣赏”强调审美，与承重的语境不合。"}], "explanations": {"承载": "“承载”指承受并支撑很重的物体，正符合桥梁承重的句意。", "修理": "语义：桥梁不能修理卡车，“修理”的对象是坏了的物件，与句意不合。", "停留": "配价：“停留”是不及物动词，不能带“卡车”作宾语。", "欣赏": "语义：桥梁不能欣赏卡车，“欣赏”强调审美，与承重的语境不合。"}, "sentence_index": 0, "correct_answer": "承载"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他承载了我的建议。", "explanation": "这里应该用〈接受〉。承载多指承受重量或背负责任，不能用来说“承载建议”。"}, {"text": "这次考试承载了三个小时。", "explanation": "这里应该用〈持续〉。承载是承受或装载的意思，不能用来说时间的长短。"}, {"text": "昨天晚上承载了一场大雨。", "explanation": "这里应该用〈下〉。承载不用于说下雨，应说“下了一场大雨”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20388, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "承载", "is_correct": true, "explanation": "“承载”意思是承受并装载重量，或担负责任。"}, {"text": "重载", "is_correct": false, "explanation": "chóng 与 chéng 韵母不同（ong／eng），“重载”意思是载重很大。"}, {"text": "撑在", "is_correct": false, "explanation": "chēng（第一声）与 chéng（第二声）声调不同，“撑在”意思是支撑在某处。"}, {"text": "成灾", "is_correct": false, "explanation": "zāi（第一声）与 zài（第四声）声调不同，“成灾”意思是形成灾害。"}], "explanations": {"承载": "“承载”意思是承受并装载重量，或担负责任。", "重载": "chóng 与 chéng 韵母不同（ong／eng），“重载”意思是载重很大。", "撑在": "chēng（第一声）与 chéng（第二声）声调不同，“撑在”意思是支撑在某处。", "成灾": "zāi（第一声）与 zài（第四声）声调不同，“成灾”意思是形成灾害。"}, "sentence_index": null, "correct_answer": "承载"}, "level_3": {"options": [{"text": "承载", "is_correct": true, "explanation": "“承载不了”指承受不了，正符合绳子能否承受体重的语境。"}, {"text": "系", "is_correct": false, "explanation": "语义：“系”是捆扎，不表示承受重量，与句意不合。"}, {"text": "离开", "is_correct": false, "explanation": "语义：绳子不能“离开”人的体重，与承受重量的句意不合。"}, {"text": "修补", "is_correct": false, "explanation": "语义：“修补”指修复损坏的东西，绳子不能修补人的体重，句意不通。"}], "explanations": {"承载": "“承载不了”指承受不了，正符合绳子能否承受体重的语境。", "系": "语义：“系”是捆扎，不表示承受重量，与句意不合。", "离开": "语义：绳子不能“离开”人的体重，与承受重量的句意不合。", "修补": "语义：“修补”指修复损坏的东西，绳子不能修补人的体重，句意不通。"}, "sentence_index": 6, "correct_answer": "承载"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他承载了两个笑话。", "explanation": "这里应该用〈讲〉。承载是承受或装载的意思，不用于说笑话。"}, {"text": "她承载了一个电话。", "explanation": "这里应该用〈打〉。承载不用于说打电话，应说“打了一个电话”。"}, {"text": "这件衣服承载了五十块钱。", "explanation": "这里应该用〈值〉。承载不用于说价钱，应说“值五十块钱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20388, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条小路承载着不了大型卡车。", "corrected_sentence": "这条小路承载不了大型卡车。", "error_description": "体标错误：“承载不了”是可能补语，不能与表示持续的“着”同用，应去掉“着”。正确为“这条小路承载不了大型卡车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20388, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这辆货车很承载两吨货物。", "corrected_sentence": "这辆货车能承载两吨货物。", "error_description": "副词误用：“很”一般修饰形容词，不修饰动词“承载”；表示能力应用“能”。正确为“能承载”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
