INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20398, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让别人知道该怎么做。", "primary_collocate": null, "pronunciation": "tí shì", "ipa": "tʰi˧˥ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "妈妈提示我出门前要关好窗。", "target_word": "提示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试时，老师不能提示学生答案。", "target_word": "提示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演员忘词时，旁边的人小声提示他。", "target_word": "提示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红灯亮着，提示车辆停下来。", "target_word": "提示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直提示我小心，别摔倒。", "target_word": "提示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练提示队员，比赛时要多传球。", "target_word": "提示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "闹钟响了，提示我该起床了。", "target_word": "提示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作人员提示我，进门前要先登记。", "target_word": "提示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你提示一下新同事怎么用机器。", "target_word": "提示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路牌提示司机前面要慢行。", "target_word": "提示", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "提示了", "label": "体标（了）"}, {"form": "提示过", "label": "体标（过）"}, {"form": "提示着", "label": "体标（着）"}, {"form": "提示音", "label": "复合词"}], "register": "中性", "sense_fingerprint": "用话、动作或信号让别人知道下一步该怎么做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cbb69d1-c10a-43bf-b61d-02878f3420cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20398, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "提示", "is_correct": true, "explanation": "正确：“提示”是让对方知道该做什么，妈妈叮嘱出门前关窗，语境相符。"}, {"text": "夸奖", "is_correct": false, "explanation": "语义：“夸奖”是表扬，与“出门前要关好窗”的叮嘱不合。"}, {"text": "回答", "is_correct": false, "explanation": "配价：“回答”的宾语应是问题，不能接叙述性的注意事项。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”带有讽刺，与善意的叮嘱相矛盾。"}], "explanations": {"提示": "正确：“提示”是让对方知道该做什么，妈妈叮嘱出门前关窗，语境相符。", "夸奖": "语义：“夸奖”是表扬，与“出门前要关好窗”的叮嘱不合。", "回答": "配价：“回答”的宾语应是问题，不能接叙述性的注意事项。", "嘲笑": "语义：“嘲笑”带有讽刺，与善意的叮嘱相矛盾。"}, "sentence_index": 0, "correct_answer": "提示"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我非常提示你的帮助。", "explanation": "这里应该用〈感谢〉。提示是让对方知道该做什么，不能用来表达对别人帮助的感激。"}, {"text": "经理提示我的请假已经通过了。", "explanation": "这里应该用〈批准〉。提示只是让人知道该做什么，不能表示同意请假。"}, {"text": "她提示我考上了大学。", "explanation": "这里应该用〈告诉〉。提示只用于让对方知道该做什么或注意什么，告知考上大学这类已发生的事要用〈告诉〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bef40f7c-2eca-4531-8b41-17a944b3ddb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20398, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "提示", "is_correct": true, "explanation": "正确：“提示”是让人知道该做什么，闹钟提醒起床，语境相符。"}, {"text": "推荐", "is_correct": false, "explanation": "语义：“推荐”是介绍好的东西，闹钟不能“推荐”起床。"}, {"text": "询问", "is_correct": false, "explanation": "配价：“询问”的内容应是问题，不能接“该起床了”这样的陈述。"}, {"text": "阻止", "is_correct": false, "explanation": "语义：“阻止”是拦住某个行为，与“该起床了”的提醒意思相反。"}], "explanations": {"提示": "正确：“提示”是让人知道该做什么，闹钟提醒起床，语境相符。", "推荐": "语义：“推荐”是介绍好的东西，闹钟不能“推荐”起床。", "询问": "配价：“询问”的内容应是问题，不能接“该起床了”这样的陈述。", "阻止": "语义：“阻止”是拦住某个行为，与“该起床了”的提醒意思相反。"}, "sentence_index": 6, "correct_answer": "提示"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们提示了一桌菜招待客人。", "explanation": "这里应该用〈准备〉。提示是让人知道该怎么做，不能表示做饭、准备东西。"}, {"text": "老师提示我的字写得很漂亮。", "explanation": "这里应该用〈夸奖〉。提示是让对方知道该做什么或注意什么，不能用来称赞别人的字写得好。"}, {"text": "裁判提示了比赛的冠军是他。", "explanation": "这里应该用〈宣布〉。提示只是让人知道该做什么，不能用来正式宣布比赛结果，宣布冠军要用〈宣布〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bef40f7c-2eca-4531-8b41-17a944b3ddb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20398, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈了提示我带伞。", "corrected_sentence": "妈妈提示我带伞。", "error_description": "错误：“了”放在了动词“提示”前面。“了”只能紧跟动词之后，本句不需要“了”，正确写作“妈妈提示我带伞。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bef40f7c-2eca-4531-8b41-17a944b3ddb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20398, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师提示很清楚。", "corrected_sentence": "老师提示得很清楚。", "error_description": "错误：补语前缺少结构助词“得”。正确：“提示得很清楚”，“得”紧跟动词，后接补语“很清楚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bef40f7c-2eca-4531-8b41-17a944b3ddb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
