INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20400, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指标是用来测量东西有多少或好不好的数字。", "primary_collocate": null, "pronunciation": "zhǐ biāo", "ipa": "ʈʂɻ̩˨˩ piɑʊ˥", "syllable_count": 2, "sentences": [{"text": "这个月的销售指标是一百万元。", "target_word": "指标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，他的血压指标很正常。", "target_word": "指标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司今年定了新的生产指标。", "target_word": "指标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项指标显示空气质量很好。", "target_word": "指标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他完成了这个月的工作指标。", "target_word": "指标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "体检报告上有很多指标。", "target_word": "指标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检查结果里有一项指标太高了。", "target_word": "指标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些指标都合格，你可以出院了。", "target_word": "指标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济指标好，说明国家发展得不错。", "target_word": "指标", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校对老师的教学有明确的指标。", "target_word": "指标", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "指标体系", "label": "复合词"}], "register": "中性", "sense_fingerprint": "用数字衡量数量或水平的标准", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b8f789-626d-40d7-a308-633398a91259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20400, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "指标", "is_correct": true, "explanation": "指标：指销售数量的目标数字，与“一百万元”相配，符合句意。"}, {"text": "报告", "is_correct": false, "explanation": "语义：报告是文字材料，不能等于一百万元这个数额。"}, {"text": "员工", "is_correct": false, "explanation": "语义：员工指人，不是可以用金额表示的数字。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“销售”不能与“体温”搭配，体温也不能用“一百万元”表示。"}], "explanations": {"指标": "指标：指销售数量的目标数字，与“一百万元”相配，符合句意。", "报告": "语义：报告是文字材料，不能等于一百万元这个数额。", "员工": "语义：员工指人，不是可以用金额表示的数字。", "体温": "搭配：“销售”不能与“体温”搭配，体温也不能用“一百万元”表示。"}, "sentence_index": 0, "correct_answer": "指标"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "路口立着一项指标，提醒司机慢行。", "explanation": "这里应该用〈标志〉。指标是用数字测量的数值，不能指路口的标识牌。"}, {"text": "他的胳膊上有一项指标，颜色是红色的。", "explanation": "这里应该用〈标记〉。指标是数字，不能指身体上的记号。"}, {"text": "他把箭射向了指标。", "explanation": "这里应该用〈目标〉。指标指用数字衡量的数值，不能指射击的靶子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20400, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指标", "is_correct": true, "explanation": "指标：指检查项目中的数值标准，与“太高”相配，符合句意。"}, {"text": "活动", "is_correct": false, "explanation": "语义：活动是有计划的行动，不是可以“太高”的数值。"}, {"text": "制度", "is_correct": false, "explanation": "语义：制度是规定，不是数值，不能说“太高”。"}, {"text": "学科", "is_correct": false, "explanation": "搭配：“太高”一般用来形容数值或水平，不这样描述学科。"}], "explanations": {"指标": "指标：指检查项目中的数值标准，与“太高”相配，符合句意。", "活动": "语义：活动是有计划的行动，不是可以“太高”的数值。", "制度": "语义：制度是规定，不是数值，不能说“太高”。", "学科": "搭配：“太高”一般用来形容数值或水平，不这样描述学科。"}, "sentence_index": 6, "correct_answer": "指标"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个瓶子上贴着一项指标，写着生产日期。", "explanation": "这里应该用〈标签〉。指标是用数字测量的数值，不是瓶子上的标签。"}, {"text": "这件衣服上印着一项指标。", "explanation": "这里应该用〈图案〉。指标是数值，不能指衣服上印的图案。"}, {"text": "这首歌的指标很好听。", "explanation": "这里应该用〈名字〉。指标是用数字测量的数值，不能用来指歌曲的名字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20400, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂今年定了一条新的生产指标。", "corrected_sentence": "这家工厂今年定了一项新的生产指标。", "error_description": "量词错误：“一条新的生产指标”中的“条”应改为“项”。指标用量词“项”，“条”用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20400, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司把这项指标定很高。", "corrected_sentence": "公司把这项指标定得很高。", "error_description": "错误：“定”后带补语“很高”时漏掉了“得”。“得”用来引出补语，正确应为“把这项指标定得很高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20402, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "软化", "is_correct": true, "explanation": "正确：软化指由硬变软，与“硬化”（由软变硬）互为反义。"}, {"text": "融化", "is_correct": false, "explanation": "融化指固体变为液体，与“硬化”没有反义关系。"}, {"text": "腐烂", "is_correct": false, "explanation": "腐烂指有机物分解变质，与“硬化”没有反义关系。"}, {"text": "发酵", "is_correct": false, "explanation": "发酵指微生物作用使物质发生变化，与“硬化”没有反义关系。"}], "correct_answer": "软化", "explanations": {"软化": "正确：软化指由硬变软，与“硬化”（由软变硬）互为反义。", "融化": "融化指固体变为液体，与“硬化”没有反义关系。", "腐烂": "腐烂指有机物分解变质，与“硬化”没有反义关系。", "发酵": "发酵指微生物作用使物质发生变化，与“硬化”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bef40f7c-2eca-4531-8b41-17a944b3ddb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20402, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "软化", "is_correct": true, "explanation": "正确：软化指由硬变软，与“硬化”（由软变硬）互为反义。"}, {"text": "溶解", "is_correct": false, "explanation": "溶解指物质在液体中化开，与“硬化”没有反义关系。"}, {"text": "冻结", "is_correct": false, "explanation": "冻结指液体变为固体，与“硬化”没有反义关系。"}, {"text": "生锈", "is_correct": false, "explanation": "生锈指金属被氧化，与“硬化”没有反义关系。"}], "correct_answer": "软化", "explanations": {"软化": "正确：软化指由硬变软，与“硬化”（由软变硬）互为反义。", "溶解": "溶解指物质在液体中化开，与“硬化”没有反义关系。", "冻结": "冻结指液体变为固体，与“硬化”没有反义关系。", "生锈": "生锈指金属被氧化，与“硬化”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bef40f7c-2eca-4531-8b41-17a944b3ddb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20402, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西变硬了。", "primary_collocate": null, "pronunciation": "yìng huà", "ipa": "iŋ˥˩ xu̯a˥˩", "syllable_count": 2, "sentences": [{"text": "面包放久了，表面会硬化。", "target_word": "硬化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块湿泥巴放在太阳下晒了一天，就硬化了。", "target_word": "硬化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "胶水干了以后，很快就硬化了。", "target_word": "硬化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "皮鞋太久没穿，皮已经硬化了。", "target_word": "硬化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气太冷，刚铺的路面要很久才能硬化。", "target_word": "硬化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水泥倒进去以后，会慢慢硬化。", "target_word": "硬化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "糖浆冷了以后会硬化。", "target_word": "硬化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜡烛油滴在桌子上，很快就硬化了。", "target_word": "硬化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面团不盖起来，表面就会硬化。", "target_word": "硬化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种陶泥晒干后会硬化，可以做杯子。", "target_word": "硬化", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "硬化了", "label": "体标"}, {"form": "硬化过", "label": "体标"}, {"form": "硬化症", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西由软变硬", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cbb69d1-c10a-43bf-b61d-02878f3420cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20402, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "硬化", "is_correct": true, "explanation": "正确：放久的面包表面变硬，是由软变硬，符合“表面会硬化”。"}, {"text": "融化", "is_correct": false, "explanation": "语义：融化指固体变为液体，放久的面包不会融化。"}, {"text": "汽化", "is_correct": false, "explanation": "语义：“汽化”指液体变成气体，面包放久了不会变成气体。"}, {"text": "软化", "is_correct": false, "explanation": "语义：放久的面包会变硬、变干，不会变软，与句意相反。"}], "explanations": {"硬化": "正确：放久的面包表面变硬，是由软变硬，符合“表面会硬化”。", "融化": "语义：融化指固体变为液体，放久的面包不会融化。", "汽化": "语义：“汽化”指液体变成气体，面包放久了不会变成气体。", "软化": "语义：放久的面包会变硬、变干，不会变软，与句意相反。"}, "sentence_index": 0, "correct_answer": "硬化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "铁钉放在潮湿的地方，很快就硬化了。", "explanation": "这里应该用〈生锈〉。铁钉受潮氧化要说生锈，硬化指东西由软变硬。"}, {"text": "雪放在太阳下会硬化。", "explanation": "这里应该用〈融化〉。雪在阳光下变成水要说融化，硬化说的是变硬。"}, {"text": "气球打得太满，会硬化。", "explanation": "这里应该用〈破裂〉。气球打得太满会爆开，应说破裂，硬化不能描述这种变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bef40f7c-2eca-4531-8b41-17a944b3ddb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20402, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "硬化", "is_correct": true, "explanation": "正确：糖浆冷了以后会变硬，是由软变硬的过程，符合“会硬化”。"}, {"text": "沸腾", "is_correct": false, "explanation": "语义：沸腾需要加热，糖浆冷了不会沸腾，与句中“冷了”矛盾。"}, {"text": "发热", "is_correct": false, "explanation": "语义：发热指产生热量，糖浆变冷后不会发热，与句意不合。"}, {"text": "加热", "is_correct": false, "explanation": "配价：“加热”是及物动词，要带受事（如“加热糖浆”），不能不带对象自行发生。"}], "explanations": {"硬化": "正确：糖浆冷了以后会变硬，是由软变硬的过程，符合“会硬化”。", "沸腾": "语义：沸腾需要加热，糖浆冷了不会沸腾，与句中“冷了”矛盾。", "发热": "语义：发热指产生热量，糖浆变冷后不会发热，与句意不合。", "加热": "配价：“加热”是及物动词，要带受事（如“加热糖浆”），不能不带对象自行发生。"}, "sentence_index": 6, "correct_answer": "硬化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "饼干放在潮湿的地方，很快就硬化了。", "explanation": "这里应该用〈变软〉。饼干受潮会变软，硬化说的是由软变硬，两者方向相反。"}, {"text": "糖放进热水里，会硬化。", "explanation": "这里应该用〈溶解〉。糖遇水化开要说溶解，硬化说的是由软变硬。"}, {"text": "木头放进火里，会硬化。", "explanation": "这里应该用〈燃烧〉。木头放进火里要说燃烧，硬化不能描述这种变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bef40f7c-2eca-4531-8b41-17a944b3ddb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20402, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块泥巴晒干后，硬化的很快。", "corrected_sentence": "这块泥巴晒干后，硬化得很快。", "error_description": "“硬化”作动词，后面的补语要用“得”引出，写成“的”是错误，“的”不能引出补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bef40f7c-2eca-4531-8b41-17a944b3ddb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20402, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块泥巴很快硬化症了。", "corrected_sentence": "这块泥巴很快硬化了。", "error_description": "“硬化症”是疾病名称，是名词；这里“硬化”应作动词，表示东西由软变硬，不能加“症”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bef40f7c-2eca-4531-8b41-17a944b3ddb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
