INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20404, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一种病，会让人的身体突然抽动，不能控制自己。", "primary_collocate": null, "pronunciation": "diān xián", "ipa": "tjɛn˥ ɕjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "他有癫痫，有时会突然倒在地上。", "target_word": "癫痫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "癫痫发作时，人的身体会不停地抽动。", "target_word": "癫痫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明得了癫痫，不能一个人去游泳。", "target_word": "癫痫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我朋友有癫痫，每天都要吃药。", "target_word": "癫痫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "癫痫发作的时候，病人不能控制自己。", "target_word": "癫痫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师知道他有癫痫，所以很照顾他。", "target_word": "癫痫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到有人癫痫发作，要马上叫救护车。", "target_word": "癫痫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "癫痫是一种病，会让人突然抽动。", "target_word": "癫痫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说，吃药可以帮他控制癫痫。", "target_word": "癫痫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的癫痫一个月发作两三次。", "target_word": "癫痫", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "癲癇", "label": "繁体"}, {"form": "癫痫病", "label": "复合"}, {"form": "癫痫发作", "label": "复合"}], "register": "中性", "sense_fingerprint": "让人身体突然抽动、不能控制自己的病", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cbb69d1-c10a-43bf-b61d-02878f3420cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20404, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "癫痫", "is_correct": true, "explanation": "正确：癫痫会让人突然倒地，符合“有时会突然倒在地上”。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒不会导致突然倒地，与后半句的症状不符。"}, {"text": "近视", "is_correct": false, "explanation": "语义：近视是视力问题，不会突然倒在地上，与句意不合。"}, {"text": "脚癣", "is_correct": false, "explanation": "语义：脚癣是皮肤病，不会导致突然倒地，与句意不合。"}], "explanations": {"癫痫": "正确：癫痫会让人突然倒地，符合“有时会突然倒在地上”。", "感冒": "语义：感冒不会导致突然倒地，与后半句的症状不符。", "近视": "语义：近视是视力问题，不会突然倒在地上，与句意不合。", "脚癣": "语义：脚癣是皮肤病，不会导致突然倒地，与句意不合。"}, "sentence_index": 0, "correct_answer": "癫痫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对游戏很癫痫，一玩就是一整天。", "explanation": "这里应该用〈迷恋〉。癫痫只指身体抽动的疾病，不能用来形容对某事痴迷。"}, {"text": "他说话颠三倒四，大家都说他癫痫了。", "explanation": "这里表示“神志混乱”，应说〈糊涂〉。癫痫只指身体抽动的疾病，不能形容人神志不清。"}, {"text": "他一高兴就癫痫，大笑不止。", "explanation": "这里表示“失态、癫狂”，应说〈疯〉。癫痫指疾病，不能用来形容情绪失控。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bef40f7c-2eca-4531-8b41-17a944b3ddb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20404, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "癫痫", "is_correct": true, "explanation": "正确：癫痫发作时会突然抽动，“看到有人癫痫发作”符合句意。"}, {"text": "车祸", "is_correct": false, "explanation": "语义：车祸是事故，不会“发作”，与“有人…发作”的句意不合。"}, {"text": "工作", "is_correct": false, "explanation": "搭配：“发作”只用于疾病或症状，不能说“工作发作”。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情不是疾病，不能“发作”，与句中“要叫救护车”的语境不符。"}], "explanations": {"癫痫": "正确：癫痫发作时会突然抽动，“看到有人癫痫发作”符合句意。", "车祸": "语义：车祸是事故，不会“发作”，与“有人…发作”的句意不合。", "工作": "搭配：“发作”只用于疾病或症状，不能说“工作发作”。", "心情": "语义：心情不是疾病，不能“发作”，与句中“要叫救护车”的语境不符。"}, "sentence_index": 6, "correct_answer": "癫痫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他因为脑出血，一直陷入癫痫。", "explanation": "这里应该用〈昏迷〉。“陷入”后接的是意识状态，癫痫是疾病名，不表示状态。"}, {"text": "他因为中风，半边身子一直癫痫。", "explanation": "这里应该用〈瘫痪〉。描述肢体失去功能要说瘫痪，癫痫指发作性疾病。"}, {"text": "他咳嗽得很厉害，一直癫痫。", "explanation": "这里描述的是持续咳嗽，应说〈咳不停〉。癫痫是会让身体突然抽动的疾病，不能用来形容咳嗽不止。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bef40f7c-2eca-4531-8b41-17a944b3ddb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20404, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一只癫痫，平时要多注意休息。", "corrected_sentence": "他有癫痫，平时要多注意休息。", "error_description": "癫痫是病名，“有癫痫”不需要量词，更不能用“只”；“只”用于动物等，不能计量疾病。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bef40f7c-2eca-4531-8b41-17a944b3ddb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20404, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这孩子癫痫发作的很厉害，家长要马上送医院。", "corrected_sentence": "这孩子癫痫发作得很厉害，家长要马上送医院。", "error_description": "“发作”后面的补语要用“得”引出，写成“的”是错误，“的”不能引出补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bef40f7c-2eca-4531-8b41-17a944b3ddb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20406, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正常", "is_correct": true, "explanation": "“正常”与“异常”是反义词，指符合平常的样子，与“话特别少”的异常相对。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”指明白、不模糊，与“异常”在这一义项上没有反义关系。"}, {"text": "结实", "is_correct": false, "explanation": "“结实”指坚固，与“异常”在这一义项上没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”指光线充足，与“异常”在这一义项上没有反义关系。"}], "correct_answer": "正常", "explanations": {"正常": "“正常”与“异常”是反义词，指符合平常的样子，与“话特别少”的异常相对。", "清楚": "“清楚”指明白、不模糊，与“异常”在这一义项上没有反义关系。", "结实": "“结实”指坚固，与“异常”在这一义项上没有反义关系。", "明亮": "“明亮”指光线充足，与“异常”在这一义项上没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f46955-9baa-4985-8abf-d5886817c790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20406, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正常", "is_correct": true, "explanation": "“正常”与“异常”是反义词，指符合平常的样子，与“反应很异常”相对。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”指智力好，与“异常”在这一义项上没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”指没有脏东西，与“异常”在这一义项上没有反义关系。"}, {"text": "便宜", "is_correct": false, "explanation": "“便宜”指价格低，与“异常”在这一义项上没有反义关系。"}], "correct_answer": "正常", "explanations": {"正常": "“正常”与“异常”是反义词，指符合平常的样子，与“反应很异常”相对。", "聪明": "“聪明”指智力好，与“异常”在这一义项上没有反义关系。", "干净": "“干净”指没有脏东西，与“异常”在这一义项上没有反义关系。", "便宜": "“便宜”指价格低，与“异常”在这一义项上没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f46955-9baa-4985-8abf-d5886817c790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20406, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "跟平时很不一样，让人感觉奇怪。", "primary_collocate": null, "pronunciation": "yì cháng", "ipa": "i˥˩ ʈʂʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "今天他很安静，样子有点异常。", "target_word": "异常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "狗叫得很凶，这很异常。", "target_word": "异常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈觉得我最近的表现有些异常。", "target_word": "异常", "complexity_tier": "T3", "furigana": "yì cháng", "sentence_source": "generated"}, {"text": "他今天的话特别少，真异常。", "target_word": "异常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这么晚了，楼上还有声音，太异常了。", "target_word": "异常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看着我，眼神很异常。", "target_word": "异常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "平时爱说话的他今天不说话，很异常。", "target_word": "异常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师发现小王的样子有点异常。", "target_word": "异常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夜里街上一个人也没有，这很异常。", "target_word": "异常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你今天的反应很异常，是不是有事？", "target_word": "异常", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "异常情况", "label": "复合"}, {"form": "异常现象", "label": "复合"}], "register": "中性", "sense_fingerprint": "和平时很不一样、让人觉得奇怪的（人的样子、行为、情形）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e47f4210-74de-4cff-af94-5b34065844d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20406, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "异常", "is_correct": true, "explanation": "“异常”在这里形容样子跟平时不一样，与“很安静”的描述相呼应。"}, {"text": "刺耳", "is_correct": false, "explanation": "搭配：“刺耳”形容声音，不能用来形容人的样子，搭配不当。"}, {"text": "狭窄", "is_correct": false, "explanation": "语义：“狭窄”指空间小，不能用来形容一个人的样子。"}, {"text": "沙哑", "is_correct": false, "explanation": "搭配：“沙哑”形容声音，不能说“样子沙哑”，搭配不当。"}], "explanations": {"异常": "“异常”在这里形容样子跟平时不一样，与“很安静”的描述相呼应。", "刺耳": "搭配：“刺耳”形容声音，不能用来形容人的样子，搭配不当。", "狭窄": "语义：“狭窄”指空间小，不能用来形容一个人的样子。", "沙哑": "搭配：“沙哑”形容声音，不能说“样子沙哑”，搭配不当。"}, "sentence_index": 0, "correct_answer": "异常"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天都是这个样子，大家早就习惯了，这很异常。", "explanation": "这里应该用〈平常〉。异常指跟平时很不一样，不能用来形容每天都这样、大家早就习惯的样子。"}, {"text": "他一直都很安静，和平时没什么两样，真异常。", "explanation": "这里应该用〈正常〉。异常指跟平时很不一样，不能用来形容和平时没什么两样的表现；这种情况应说“正常”。"}, {"text": "我的成绩每次都差不多，这种情况很异常。", "explanation": "这里应该用〈稳定〉。异常指跟平时很不一样，不能用来形容每次都差不多的成绩；成绩变化小应说“稳定”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f46955-9baa-4985-8abf-d5886817c790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20406, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "异常", "is_correct": true, "explanation": "“异常”说他与平时很不一样，与“平时爱说话”“今天不说话”形成对比，符合句意。"}, {"text": "热情", "is_correct": false, "explanation": "语义：“热情”形容待人友好，与“今天不说话”相矛盾。"}, {"text": "开朗", "is_correct": false, "explanation": "语义：“开朗”形容性格爽朗，与“今天不说话”相矛盾。"}, {"text": "幽默", "is_correct": false, "explanation": "搭配：“幽默”形容言谈风趣，与“不说话”的语境不搭。"}], "explanations": {"异常": "“异常”说他与平时很不一样，与“平时爱说话”“今天不说话”形成对比，符合句意。", "热情": "语义：“热情”形容待人友好，与“今天不说话”相矛盾。", "开朗": "语义：“开朗”形容性格爽朗，与“今天不说话”相矛盾。", "幽默": "搭配：“幽默”形容言谈风趣，与“不说话”的语境不搭。"}, "sentence_index": 6, "correct_answer": "异常"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天都按时跑步，跑得很异常，大家早就习以为常。", "explanation": "这里应该用〈规律〉。异常指跟平时很不一样，不能用来形容每天都按时跑步、一直如此的情况；这种情况应说“跑得很规律”。"}, {"text": "他的字每天都一样工整，写得很异常，大家都习惯了。", "explanation": "这里应该用〈整齐〉。异常指跟平时很不一样，不能用来形容一直一样工整的字迹；字写得整齐应说“整齐”。"}, {"text": "妈妈做的饭每天都是这个味道，很异常，大家都吃得很快。", "explanation": "这里应该用〈熟悉〉。异常指跟平时很不一样，不能用来形容每天都是这个味道、大家早已熟悉的饭菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f46955-9baa-4985-8abf-d5886817c790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20406, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他今天显得有点异常过，不太说话。", "corrected_sentence": "他今天显得有点异常，不太说话。", "error_description": "体标错误：“过”表示经历，不能放在形容词“异常”后面；描述当下的样子直接说“有点异常”，去掉“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f46955-9baa-4985-8abf-d5886817c790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20406, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他今天的笑容看起来有点异常地，有些奇怪。", "corrected_sentence": "他今天的笑容看起来有点异常，有些奇怪。", "error_description": "助词错误：“异常”作谓语时后面不接“地”，“地”只用于修饰动词；应去掉“地”，说“有点异常”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f46955-9baa-4985-8abf-d5886817c790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20408, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "稀少", "is_correct": true, "explanation": "稀少与频繁相反，指数量少、次数少，二者构成反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮与频繁没有反义关系，描述的是光线或颜色。"}, {"text": "坚硬", "is_correct": false, "explanation": "坚硬与频繁没有反义关系，描述的是物体的质地。"}, {"text": "辽阔", "is_correct": false, "explanation": "辽阔与频繁没有反义关系，描述的是空间的广大。"}], "correct_answer": "稀少", "explanations": {"稀少": "稀少与频繁相反，指数量少、次数少，二者构成反义关系。", "明亮": "明亮与频繁没有反义关系，描述的是光线或颜色。", "坚硬": "坚硬与频繁没有反义关系，描述的是物体的质地。", "辽阔": "辽阔与频繁没有反义关系，描述的是空间的广大。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0907cc3e-97e8-4e3a-ba50-cdd19a567979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
