INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20410, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "用来引出具体的例子，对前面的说法加以说明。", "primary_collocate": null, "pronunciation": "lì rú", "ipa": "li˥˩ ɻu˧˥", "syllable_count": 2, "sentences": [{"text": "我喜欢水果，例如苹果和香蕉。", "target_word": "例如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多动物会游泳，例如鱼、鸭子和狗。", "target_word": "例如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会说几种语言，例如中文和日语。", "target_word": "例如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天可以做很多运动，例如游泳。", "target_word": "例如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市有很多好玩的地方，例如公园和博物馆。", "target_word": "例如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天做家务，例如洗碗、扫地。", "target_word": "例如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些习惯对身体好，例如早睡早起。", "target_word": "例如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校有很多社团，例如音乐社和足球社。", "target_word": "例如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国有很多节日，例如春节和中秋节。", "target_word": "例如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有不少爱好，例如看书、下棋。", "target_word": "例如", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "引出举例的连接词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: 3 words above tier T1 (max 2): 家务 (Zipf 3.88), 洗碗 (Zipf 3.09), 扫地 (Zipf 3.55)']::text[], '1eb7735c-2a9b-4b0a-9aa5-30409c5f4706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20410, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "例如", "is_correct": true, "explanation": "例如：引出举例，与“苹果和香蕉”相呼应。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”表示原因，此处不能引出举例。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示结果，与举例的语境不符。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”需与“但是”或“却”等呼应，单独使用说不通。"}], "explanations": {"例如": "例如：引出举例，与“苹果和香蕉”相呼应。", "因为": "语义：“因为”表示原因，此处不能引出举例。", "所以": "语义：“所以”表示结果，与举例的语境不符。", "虽然": "搭配：“虽然”需与“但是”或“却”等呼应，单独使用说不通。"}, "sentence_index": 0, "correct_answer": "例如"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房间很大，例如很亮。", "explanation": "这里应该用〈并且〉。“并且”连接并列的两个描述；“例如”只能用于举例，不能连接“很亮”这样的描述。"}, {"text": "我们明天去超市，例如天气好的话。", "explanation": "这里应该用〈如果〉。「如果」表示条件；「例如」只能用于举例，不能引出条件。"}, {"text": "我昨天去了公园，例如回家了。", "explanation": "这里应该用〈然后〉。“然后”表示动作的先后顺序；“例如”只能用于举例，不能表示先后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730d9adb-f06d-478e-b06a-7cec07ec77a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20410, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "例如", "is_correct": true, "explanation": "例如：引出举例，与“早睡早起”相呼应。"}, {"text": "即使", "is_correct": false, "explanation": "搭配：“即使”需与后文“也”相呼应，此处没有。"}, {"text": "不仅", "is_correct": false, "explanation": "搭配：“不仅”需与“而且”等相呼应，此处没有。"}, {"text": "然而", "is_correct": false, "explanation": "语义：“然而”表示转折，与“对身体好”后面的举例语境不符。"}], "explanations": {"例如": "例如：引出举例，与“早睡早起”相呼应。", "即使": "搭配：“即使”需与后文“也”相呼应，此处没有。", "不仅": "搭配：“不仅”需与“而且”等相呼应，此处没有。", "然而": "语义：“然而”表示转折，与“对身体好”后面的举例语境不符。"}, "sentence_index": 6, "correct_answer": "例如"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有不少爱好，例如他是老师。", "explanation": "这里应该用〈另外〉。“另外”可以补充不同类的信息；“例如”后面应是爱好的例子，“他是老师”是身份，不属于爱好，不能用“例如”引出。"}, {"text": "他有不少爱好，例如他的工作也很忙。", "explanation": "这里应该用〈另外〉。「另外」可以补充关于他的另一方面情况；「例如」后面必须是爱好的例子，「工作很忙」不是爱好。"}, {"text": "他会说中文，例如还会说日语。", "explanation": "这里应该用〈而且〉。「而且」表示递进，补充更进一步的事实；「例如」只能引出举例，不能表示递进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730d9adb-f06d-478e-b06a-7cec07ec77a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20410, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市有很多好吃的，例如的小笼包和牛肉面。", "corrected_sentence": "这个城市有很多好吃的，例如小笼包和牛肉面。", "error_description": "错误在于“例如”后多出“的”。“例如”是连词，后面直接接举例内容，不能加“的”变成“例如的”，应说“例如小笼包和牛肉面”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730d9adb-f06d-478e-b06a-7cec07ec77a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20410, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有很多爱好，也例如游泳和画画。", "corrected_sentence": "他有很多爱好，例如游泳和画画。", "error_description": "错误在于多出“也”。“也”不能放在“例如”前面，引出举例时应直接用“例如”，去掉“也”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730d9adb-f06d-478e-b06a-7cec07ec77a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
