INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20412, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一种让人很长时间都感到非常不开心的病。", "primary_collocate": null, "pronunciation": "yì yù zhèng", "ipa": "i˥˩ y˥˩ ʈʂɤŋ˥˩", "syllable_count": 3, "sentences": [{"text": "他得了抑郁症，每天都不开心。", "target_word": "抑郁症", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "抑郁症是一种让人很难过的病。", "target_word": "抑郁症", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她得抑郁症已经两年了，还在吃药。", "target_word": "抑郁症", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "抑郁症不是小事，要去看医生。", "target_word": "抑郁症", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我朋友有抑郁症，他很少说话。", "target_word": "抑郁症", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "得了抑郁症的人需要家人的帮助。", "target_word": "抑郁症", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说妈妈的抑郁症好多了。", "target_word": "抑郁症", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他因为抑郁症，不想出门见人。", "target_word": "抑郁症", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "抑郁症可以治，别太担心。", "target_word": "抑郁症", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小明的哥哥得过抑郁症，现在很好。", "target_word": "抑郁症", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "产后抑郁症", "label": "复合"}, {"form": "抑郁症患者", "label": "复合"}], "register": "中性", "sense_fingerprint": "让人长期非常不开心的一种病（日常说法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e47f4210-74de-4cff-af94-5b34065844d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20412, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抑郁症", "is_correct": true, "explanation": "抑郁症是一种让人长期不开心的病，与“每天都不开心”的描述相符。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“得了”后接疾病，“得了作业”不成立，与“每天都不开心”也无关。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“得了考试”不成立，考试不是病，句子不通。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“得了名字”不成立，名字不是病，句子不通。"}], "explanations": {"抑郁症": "抑郁症是一种让人长期不开心的病，与“每天都不开心”的描述相符。", "作业": "搭配：“得了”后接疾病，“得了作业”不成立，与“每天都不开心”也无关。", "考试": "搭配：“得了考试”不成立，考试不是病，句子不通。", "名字": "搭配：“得了名字”不成立，名字不是病，句子不通。"}, "sentence_index": 0, "correct_answer": "抑郁症"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他有点抑郁症，我让他多喝水。", "explanation": "这里应该用〈感冒〉。抑郁症需要医生诊断和治疗，不能像感冒那样靠“多喝水”来处理。"}, {"text": "他有点抑郁症，需要配一副眼镜。", "explanation": "这里应该用〈近视〉。抑郁症是精神障碍，需要药物和心理治疗，不能配眼镜；配眼镜是针对近视的。"}, {"text": "考试没考好，我今天有点抑郁症。", "explanation": "这里应该用〈心情不好〉。抑郁症是临床诊断的精神障碍，不能用来形容一时的烦闷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f46955-9baa-4985-8abf-d5886817c790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20412, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抑郁症", "is_correct": true, "explanation": "抑郁症是病名，能用“好多了”描述病情，与“医生说”的语境一致。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是病，“医生说……好多了”描述的是病情，与“手机”搭配不通。"}, {"text": "作文", "is_correct": false, "explanation": "语义：作文不是病，不能用“医生说……好多了”来描述，句子不通。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不是病，“医生说妈妈的钥匙好多了”不成立，与病情语境冲突。"}], "explanations": {"抑郁症": "抑郁症是病名，能用“好多了”描述病情，与“医生说”的语境一致。", "手机": "语义：手机不是病，“医生说……好多了”描述的是病情，与“手机”搭配不通。", "作文": "语义：作文不是病，不能用“医生说……好多了”来描述，句子不通。", "钥匙": "语义：钥匙不是病，“医生说妈妈的钥匙好多了”不成立，与病情语境冲突。"}, "sentence_index": 6, "correct_answer": "抑郁症"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小明的哥哥每天都在玩抑郁症，连饭都不吃。", "explanation": "这里应该用〈游戏〉。“玩”搭配的是游戏、球类等，抑郁症是疾病，不能当作玩的对象。"}, {"text": "小明的哥哥把一瓶抑郁症都吃完了，又去买了一瓶。", "explanation": "这里应该用〈药〉。抑郁症是一种病，不能被吃完或买来；能吃、能买的是药。"}, {"text": "小明的哥哥被老师批评了，心情有点抑郁症。", "explanation": "这里应该用〈郁闷〉。抑郁症是临床疾病，不能用来形容被批评后一时的情绪；这种情绪应说“郁闷”之类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f46955-9baa-4985-8abf-d5886817c790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20412, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他得了抑郁症着，整天都没有力气。", "corrected_sentence": "他得了抑郁症，整天都没有力气。", "error_description": "体标错误：“着”不能放在宾语“抑郁症”后面；表示已经发生的状态应说“得了抑郁症”，去掉“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f46955-9baa-4985-8abf-d5886817c790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20412, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹过抑郁症，现在已经好多了。", "corrected_sentence": "妹妹得过抑郁症，现在已经好多了。", "error_description": "缺词错误：表示经历的“过”前面要有动词，“过”不能直接接宾语“抑郁症”，应补上动词“得”，说“得过抑郁症”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f46955-9baa-4985-8abf-d5886817c790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
