INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20414, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "天气很好，没有云，亮亮的。", "primary_collocate": null, "pronunciation": "míng lǎng", "ipa": "miŋ˧˥ laŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "今天的天空很明朗。", "target_word": "明朗", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "明朗的天气让大家都很高兴。", "target_word": "明朗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末天气明朗，公园里有很多人。", "target_word": "明朗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "早上推开窗，外面的天空明朗极了。", "target_word": "明朗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天天气明朗，最高气温二十度。", "target_word": "明朗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨过天晴，山上的天色格外明朗。", "target_word": "明朗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几天一直很明朗，没有下雨。", "target_word": "明朗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气明朗的时候，可以看到远处的山。", "target_word": "明朗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜间天气明朗，繁星格外多。", "target_word": "明朗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大风把云吹走了，天空变得明朗了。", "target_word": "明朗", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "明朗化", "label": "复合词"}, {"form": "不明朗", "label": "否定式"}], "register": "书面", "sense_fingerprint": "明朗|天气晴好无云明亮", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e47f4210-74de-4cff-af94-5b34065844d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20414, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "明朗", "is_correct": true, "explanation": "明朗：天气晴好、天色明亮，与“天空”搭配，符合句意。"}, {"text": "硬", "is_correct": false, "explanation": "语义：“硬”说质地，不用来形容天色。"}, {"text": "咸", "is_correct": false, "explanation": "搭配：“咸”用于味道，不与“天空”搭配。"}, {"text": "辣", "is_correct": false, "explanation": "搭配：“辣”用于味道，不能用来形容天空。"}], "explanations": {"明朗": "明朗：天气晴好、天色明亮，与“天空”搭配，符合句意。", "硬": "语义：“硬”说质地，不用来形容天色。", "咸": "搭配：“咸”用于味道，不与“天空”搭配。", "辣": "搭配：“辣”用于味道，不能用来形容天空。"}, "sentence_index": 0, "correct_answer": "明朗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子的灯很明朗，照得人睁不开眼。", "explanation": "这里应该用〈明亮〉。明朗多形容天气、心情或声音，灯这类发亮的物体要用〈明亮〉。"}, {"text": "山间的溪水很明朗，能看见水底的鱼在游。", "explanation": "这里应该用〈清澈〉。形容水清而透明要用〈清澈〉，明朗不用于形容水。"}, {"text": "这杯茶的味道很明朗，喝起来很清爽。", "explanation": "这里应该用〈醇厚〉。形容茶的滋味要用〈醇厚〉或〈清香〉，明朗不用于描写味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f46955-9baa-4985-8abf-d5886817c790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20414, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "明朗", "is_correct": true, "explanation": "明朗：天气晴好、没有云，与“一直”搭配，符合“没有下雨”的语境。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”形容味道，不用来形容天气。"}, {"text": "烫", "is_correct": false, "explanation": "语义：“烫”说温度，不用来形容天气的晴好。"}, {"text": "厚", "is_correct": false, "explanation": "语义：“厚”形容物体的厚薄，不能用来形容天气。"}], "explanations": {"明朗": "明朗：天气晴好、没有云，与“一直”搭配，符合“没有下雨”的语境。", "甜": "语义：“甜”形容味道，不用来形容天气。", "烫": "语义：“烫”说温度，不用来形容天气的晴好。", "厚": "语义：“厚”形容物体的厚薄，不能用来形容天气。"}, "sentence_index": 6, "correct_answer": "明朗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块金属被打磨得很明朗，闪闪发亮。", "explanation": "这里应该用〈光亮〉。形容金属等物体表面发亮要用〈光亮〉，明朗用于天气、心情，不用于描写物体表面。"}, {"text": "早晨的空气很明朗，让人神清气爽。", "explanation": "这里应该用〈清新〉。形容空气要用〈清新〉，明朗不用于形容空气。"}, {"text": "他对童年的往事记得很明朗，连细节都说得清清楚楚。", "explanation": "这里应该用〈清晰〉。描述记忆、印象清楚要用〈清晰〉，明朗不用于描述记忆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f46955-9baa-4985-8abf-d5886817c790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20414, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨停以后，天空明朗地很，远处的山看得清清楚楚。", "corrected_sentence": "雨停以后，天空明朗得很，远处的山看得清清楚楚。", "error_description": "补语标记错误：程度补语“明朗得很”中的“得”误写成“地”。错误形式是“明朗地很”，正确形式是“明朗得很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f46955-9baa-4985-8abf-d5886817c790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20414, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今天的天空地明朗，山都看得很清楚。", "corrected_sentence": "今天的天空很明朗，山都看得很清楚。", "error_description": "“明朗”前应用程度副词“很”，不能用结构助词“地”。错误形式是“地明朗”，正确形式是“很明朗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f46955-9baa-4985-8abf-d5886817c790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
