INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20424, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "双方或多方意见不同，并且互相说对方不对。", "primary_collocate": null, "pronunciation": "zhēng yì", "ipa": "ʈʂəŋ˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "这件事在网上引起了很大的争议。", "target_word": "争议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两个人对价钱有争议。", "target_word": "争议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题没有争议，大家都同意。", "target_word": "争议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电影因为内容有争议，很多人在讨论。", "target_word": "争议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家公司的争议最后由法院解决。", "target_word": "争议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "关于新规定的争议还没有结束。", "target_word": "争议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场争议已经持续了一个多月。", "target_word": "争议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居因为停车的事有了争议。", "target_word": "争议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个决定有些争议，但是大多数人同意。", "target_word": "争议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了避免争议，他们先写好了合同。", "target_word": "争议", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "争议性", "label": "复合"}, {"form": "爭議", "label": "繁体"}], "register": "书面", "sense_fingerprint": "双方意见不同、互相认为对方不对的争论", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb662756-0b78-4edf-9c5e-051c04c57dff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20424, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "争议", "is_correct": true, "explanation": "正确答案。争议（zhēng yì）指双方意见不同、互相说对方不对。"}, {"text": "正义", "is_correct": false, "explanation": "zhèng（第四声）与 zhēng（第一声）声调不同，意思是正义、公正的道理。"}, {"text": "生意", "is_correct": false, "explanation": "shēng 与 zhēng 声母不同（sh 与 zh），意思是买卖、生意。"}, {"text": "忠义", "is_correct": false, "explanation": "zhōng 与 zhēng 韵母不同（ong 与 eng），意思是忠诚、讲义气。"}], "explanations": {"争议": "正确答案。争议（zhēng yì）指双方意见不同、互相说对方不对。", "正义": "zhèng（第四声）与 zhēng（第一声）声调不同，意思是正义、公正的道理。", "生意": "shēng 与 zhēng 声母不同（sh 与 zh），意思是买卖、生意。", "忠义": "zhōng 与 zhēng 韵母不同（ong 与 eng），意思是忠诚、讲义气。"}, "sentence_index": null, "correct_answer": "争议"}, "level_3": {"options": [{"text": "争议", "is_correct": true, "explanation": "争议指双方意见不同、互相争论，能与“引起了很大的”搭配，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能被“引起”，“引起了很大的天气”句意不通。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“引起”后面接的是争议、反响、注意等，不能接“名字”。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”不是能被引起的事件，“引起了很大的味道”不通。"}], "explanations": {"争议": "争议指双方意见不同、互相争论，能与“引起了很大的”搭配，符合句意。", "天气": "语义：天气不能被“引起”，“引起了很大的天气”句意不通。", "名字": "搭配：“引起”后面接的是争议、反响、注意等，不能接“名字”。", "味道": "搭配：“味道”不是能被引起的事件，“引起了很大的味道”不通。"}, "sentence_index": 0, "correct_answer": "争议"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们的看法完全一致，所以我们之间有争议。", "explanation": "“看法完全一致”与“有争议”矛盾，句意不通；争议指意见不同、互相争论。"}, {"text": "两位候选人进行了一场争议。", "explanation": "这里应该用〈辩论〉。辩论是有规则的论辩活动，可以“进行一场”；争议指分歧本身，不指有组织的论辩。"}, {"text": "这个孩子争议自己的玩具，不肯让给别的小朋友。", "explanation": "这里应该用〈争夺〉。争夺指为了抢得东西而竞争，争议指意见分歧；要抢玩具说争夺，不能说争议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20424, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "争议", "is_correct": true, "explanation": "争议指争论不休的事件，可以“持续了一个多月”，符合句意。"}, {"text": "婚礼", "is_correct": false, "explanation": "语义：婚礼一般只持续一天，与“持续了一个多月”矛盾。"}, {"text": "车祸", "is_correct": false, "explanation": "语义：车祸是瞬间发生的事，不能“持续了一个多月”。"}, {"text": "派对", "is_correct": false, "explanation": "语义：派对通常只持续几个小时，与“持续了一个多月”矛盾。"}], "explanations": {"争议": "争议指争论不休的事件，可以“持续了一个多月”，符合句意。", "婚礼": "语义：婚礼一般只持续一天，与“持续了一个多月”矛盾。", "车祸": "语义：车祸是瞬间发生的事，不能“持续了一个多月”。", "派对": "语义：派对通常只持续几个小时，与“持续了一个多月”矛盾。"}, "sentence_index": 6, "correct_answer": "争议"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两家公司在市场上争议客户。", "explanation": "这里应该用〈争抢〉。争议指意见分歧，不指争抢客户；争抢客户要说争抢。"}, {"text": "他们为这个问题争议了一个下午。", "explanation": "这里应该用〈争论〉。“争议”是名词，指意见分歧本身；表示互相辩论这个动作要说“争论”。"}, {"text": "双方经过争议，最后吃饱了饭。", "explanation": "“争议”指意见分歧，不能用来描述吃饭的过程，“经过争议”后接“吃饱了饭”搭配不当。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20424, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个政策很争议。", "corrected_sentence": "这个政策很有争议。", "error_description": "错误在“争议”的词性：“争议”是名词，不能直接受“很”修饰，应说“有争议”，加程度时说“很有争议”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20424, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两家公司之间出现了一只争议。", "corrected_sentence": "这两家公司之间出现了一场争议。", "error_description": "错误在量词：“争议”是抽象事件，量词应用“场”，“只”用于动物或成对物品中的一个，不能修饰争议。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
