INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20428, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0dd14d6-72cd-46e8-9916-464d51ef7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20428, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身体里一种能让你感到开心和想动起来的东西。", "primary_collocate": null, "pronunciation": "duō bā àn", "ipa": "tuo˥ pa˥ an˥˩", "syllable_count": 3, "sentences": [{"text": "听到好听的歌，身体里的多巴胺会变多。", "target_word": "多巴胺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多巴胺让我们觉得很开心。", "target_word": "多巴胺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑步以后，多巴胺会让你想动。", "target_word": "多巴胺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天很开心，可能是多巴胺的作用。", "target_word": "多巴胺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃好吃的东西时，身体会放出多巴胺。", "target_word": "多巴胺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多巴胺少了，人就不想动。", "target_word": "多巴胺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，多巴胺是让人开心的东西。", "target_word": "多巴胺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玩游戏赢了，身体里有很多多巴胺。", "target_word": "多巴胺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你笑的时候，多巴胺也在工作。", "target_word": "多巴胺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，多巴胺能让孩子爱玩爱动。", "target_word": "多巴胺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "多巴胺：身体里让人开心、想行动的物质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c9658f7-a5c0-453b-af03-5c53c4129a21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20428, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多巴胺", "is_correct": true, "explanation": "正确：多巴胺是身体里让人开心、想行动的物质，“身体里的……会变多”成立。"}, {"text": "钞票", "is_correct": false, "explanation": "语义：钞票不会存在于身体里，与“身体里的”矛盾。"}, {"text": "行李", "is_correct": false, "explanation": "语义：行李是携带的物品，身体里没有行李，句子无法成立。"}, {"text": "灵魂", "is_correct": false, "explanation": "搭配：“变多”多用于可以增减的物质或数量，“灵魂”不这样搭配。"}], "explanations": {"多巴胺": "正确：多巴胺是身体里让人开心、想行动的物质，“身体里的……会变多”成立。", "钞票": "语义：钞票不会存在于身体里，与“身体里的”矛盾。", "行李": "语义：行李是携带的物品，身体里没有行李，句子无法成立。", "灵魂": "搭配：“变多”多用于可以增减的物质或数量，“灵魂”不这样搭配。"}, "sentence_index": 0, "correct_answer": "多巴胺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "身体里的多巴胺会接收开心的信号，让人想动。", "explanation": "这里应该用〈受体〉。接收信号的是多巴胺受体；多巴胺是传递信号的物质，本身不接收信号。"}, {"text": "多巴胺是我身体里的一个小器官，专门让人开心。", "explanation": "多巴胺是一种让人开心的化学物质，不是身体里的器官。"}, {"text": "我今天很开心，因为身体里有一把多巴胺。", "explanation": "这里量词用错了。「把」用于有柄的东西；多巴胺是一种物质，不按个数计算，应说「身体里有很多多巴胺」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0dd14d6-72cd-46e8-9916-464d51ef7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20428, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多巴胺", "is_correct": true, "explanation": "正确：多巴胺是让人开心的物质，与“老师说”“让人开心的东西”一致。"}, {"text": "噪音", "is_correct": false, "explanation": "搭配：“让人开心的东西”要能带来快乐，“噪音”与这一搭配不符。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不会让人开心，说它是让人开心的东西与句意相反。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：眼泪通常与悲伤相关，不能说是让人开心的东西。"}], "explanations": {"多巴胺": "正确：多巴胺是让人开心的物质，与“老师说”“让人开心的东西”一致。", "噪音": "搭配：“让人开心的东西”要能带来快乐，“噪音”与这一搭配不符。", "垃圾": "语义：垃圾不会让人开心，说它是让人开心的东西与句意相反。", "眼泪": "语义：眼泪通常与悲伤相关，不能说是让人开心的东西。"}, "sentence_index": 6, "correct_answer": "多巴胺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "跑步以后，身体里有一片多巴胺，让人想动。", "explanation": "这里量词用错了。「片」用于薄的东西；多巴胺是一种物质，不按片计算，应说「身体里有很多多巴胺」。"}, {"text": "多巴胺是身体里的一种细胞，能让人开心和想动。", "explanation": "多巴胺是化学物质（神经递质），不是细胞。"}, {"text": "多巴胺是神经元之间的一个突触，让人开心。", "explanation": "突触是神经元之间的连接处；多巴胺是在突触间传递信号的物质，不是突触。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0dd14d6-72cd-46e8-9916-464d51ef7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20428, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "玩游戏赢了，多巴胺会我很开心。", "corrected_sentence": "玩游戏赢了，多巴胺会让我很开心。", "error_description": "错误：「多巴胺会我很开心」缺少使役动词「让」。正确：「多巴胺会让我很开心」，「让」引出被使役的人，句中必须有它。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0dd14d6-72cd-46e8-9916-464d51ef7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20428, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生说，一颗多巴胺是让人开心的物质。", "corrected_sentence": "医生说，多巴胺是让人开心的物质。", "error_description": "量词错误：「颗」用于颗粒状的东西，多巴胺是一种物质，不能用「一颗」计量。应去掉「一颗」，直接说「多巴胺是让人开心的物质」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0dd14d6-72cd-46e8-9916-464d51ef7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
