INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20434, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把自己当做另一个人或动物。", "primary_collocate": null, "pronunciation": "bàn yǎn", "ipa": "pan˥˩ jɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "弟弟扮演小狗，在地上爬。", "target_word": "扮演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们扮演医生和病人。", "target_word": "扮演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢扮演公主。", "target_word": "扮演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "万圣节我扮演了一只猫。", "target_word": "扮演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他扮演老人，说话很慢。", "target_word": "扮演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩扮演妈妈，给娃娃喂饭。", "target_word": "扮演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们玩游戏，我扮演老虎。", "target_word": "扮演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥扮演过一只熊。", "target_word": "扮演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他扮演小鸟，张开手在房间里跑。", "target_word": "扮演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "表演时，她扮演一个很老的人。", "target_word": "扮演", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扮演了", "label": "体标"}, {"form": "扮演着", "label": "体标"}, {"form": "扮演过", "label": "体标"}], "register": "中性", "sense_fingerprint": "游戏或表演中假装自己是另一个人或动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c9658f7-a5c0-453b-af03-5c53c4129a21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20434, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "改正", "is_correct": false, "explanation": "搭配：「改正」的对象是错误、缺点，不能用于动物。"}, {"text": "批改", "is_correct": false, "explanation": "配价：「批改」的宾语是作业、文章，不能以小狗为宾语。"}, {"text": "扮演", "is_correct": true, "explanation": "扮演：假装成某种人物或动物。「弟弟扮演小狗」符合游戏中的句意。"}, {"text": "发明", "is_correct": false, "explanation": "语义：「发明」指创造新事物，与弟弟模仿小狗爬行的游戏情境不符。"}], "explanations": {"改正": "搭配：「改正」的对象是错误、缺点，不能用于动物。", "批改": "配价：「批改」的宾语是作业、文章，不能以小狗为宾语。", "扮演": "扮演：假装成某种人物或动物。「弟弟扮演小狗」符合游戏中的句意。", "发明": "语义：「发明」指创造新事物，与弟弟模仿小狗爬行的游戏情境不符。"}, "sentence_index": 0, "correct_answer": "扮演"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈扮演了一顿晚饭。", "explanation": "这里应该用〈做〉。扮演的对象是人或动物，晚饭是做出来的食物，应该用做。"}, {"text": "老师扮演了一堂课。", "explanation": "这里应该用〈上〉。扮演的对象是人或动物，课是上的，应该用上。"}, {"text": "他扮演了一篇论文。", "explanation": "这里应该用〈写〉或〈发表〉。论文是写出来、发表的成果，扮演的对象只能是人或动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0dd14d6-72cd-46e8-9916-464d51ef7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20434, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "计算", "is_correct": false, "explanation": "搭配：「计算」的对象是数字、费用，不能用于「老虎」。"}, {"text": "扮演", "is_correct": true, "explanation": "扮演：在游戏中假装成某种动物。「我扮演老虎」符合句意。"}, {"text": "打印", "is_correct": false, "explanation": "搭配：「打印」用于文件、图片，不能用于动物。"}, {"text": "关闭", "is_correct": false, "explanation": "配价：「关闭」的宾语是门窗、程序等可开关之物，不能用于「老虎」。"}], "explanations": {"计算": "搭配：「计算」的对象是数字、费用，不能用于「老虎」。", "扮演": "扮演：在游戏中假装成某种动物。「我扮演老虎」符合句意。", "打印": "搭配：「打印」用于文件、图片，不能用于动物。", "关闭": "配价：「关闭」的宾语是门窗、程序等可开关之物，不能用于「老虎」。"}, "sentence_index": 6, "correct_answer": "扮演"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她扮演了一本书。", "explanation": "这里应该用〈读〉或〈写〉。扮演指把自己当做人或动物，书不属于此类，不能作扮演的对象。"}, {"text": "农民扮演了一片庄稼。", "explanation": "这里应该用〈种〉。扮演的对象是人或动物，庄稼是种出来的，应该用种。"}, {"text": "他扮演了一道题。", "explanation": "这里应该用〈解〉。扮演的对象是人或动物，题目是解出来的，应该用解。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0dd14d6-72cd-46e8-9916-464d51ef7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20434, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他扮演很像老虎。", "corrected_sentence": "他扮演得很像老虎。", "error_description": "错误：「扮演很像」漏了「得」。正确：「扮演得很像」，动词后带状态补语时须用「得」连接。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0dd14d6-72cd-46e8-9916-464d51ef7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20434, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟弟扮演着过小鸟。", "corrected_sentence": "弟弟扮演过小鸟。", "error_description": "错误：「扮演着过」在动词后同时用了「着」和「过」。正确：「扮演过」，只用「过」表示曾经做过。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0dd14d6-72cd-46e8-9916-464d51ef7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
