INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20440, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人做事或掌握技能所达到的好坏程度。", "primary_collocate": null, "pronunciation": "shuǐ píng", "ipa": "ʂweɪ˨˩˦ pʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他做饭的水平很高。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的工作水平我很放心。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明踢球的水平越来越好。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她唱歌的水平让大家吃惊。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试看出你的真实水平。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打乒乓球的水平不低。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我做菜的水平一般。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟的画画水平进步了。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说我的作业水平比以前好。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个医生的水平很让人放心。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "技术水平", "label": "复合"}, {"form": "工作水平", "label": "复合"}], "register": "中性", "sense_fingerprint": "水平：一个人做事做得好坏的程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2b17fa-c08d-40b7-9a9a-4277d5c11bc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20440, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水平", "is_correct": true, "explanation": "“水平”指做饭达到的程度，与“很高”搭配，句意通顺。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人的身体高矮，不能说做饭的身高。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”是人的岁数，不能用来说做饭的程度。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“很高”不能用来说颜色，颜色不说高低。"}], "explanations": {"水平": "“水平”指做饭达到的程度，与“很高”搭配，句意通顺。", "身高": "语义：“身高”指人的身体高矮，不能说做饭的身高。", "年龄": "语义：“年龄”是人的岁数，不能用来说做饭的程度。", "颜色": "搭配：“很高”不能用来说颜色，颜色不说高低。"}, "sentence_index": 0, "correct_answer": "水平"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她唱歌的水平很好听。", "explanation": "这里应该用〈声音〉。“好听”描述声音，不能描述能力水平。"}, {"text": "她把乐谱水平放在桌上。", "explanation": "这里的“水平”取“与地面平行”的意思，是另一个义项，与唱歌的能力无关。"}, {"text": "她的水平很苗条。", "explanation": "这里应该用〈身材〉。“苗条”形容人的体形，不能用来描述能力水平。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c52ccf7c-18a6-4962-acc1-231bfff3779e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20440, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水平", "is_correct": true, "explanation": "“水平”指做菜达到的程度，与“一般”搭配，用来评价做菜的好坏，句意通顺。"}, {"text": "长相", "is_correct": false, "explanation": "体貌：“长相”指人的容貌，不能用来说做菜的情况。"}, {"text": "体型", "is_correct": false, "explanation": "体貌：“体型”指人的身体形状，与做菜无关。"}, {"text": "字迹", "is_correct": false, "explanation": "语义：“字迹”指写的字的样子，做菜不写字，不能用“字迹”来评价。"}], "explanations": {"水平": "“水平”指做菜达到的程度，与“一般”搭配，用来评价做菜的好坏，句意通顺。", "长相": "体貌：“长相”指人的容貌，不能用来说做菜的情况。", "体型": "体貌：“体型”指人的身体形状，与做菜无关。", "字迹": "语义：“字迹”指写的字的样子，做菜不写字，不能用“字迹”来评价。"}, "sentence_index": 6, "correct_answer": "水平"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个医生的水平很便宜。", "explanation": "这里应该用〈价格〉。“便宜”描述价格，不能描述能力水平。"}, {"text": "这个医生的水平很温和。", "explanation": "这里应该用〈脾气〉。“温和”形容性格或态度，不能形容能力水平。"}, {"text": "这个医生的水平很红。", "explanation": "这里应该用〈脸色〉。“红”形容颜色，水平没有颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c52ccf7c-18a6-4962-acc1-231bfff3779e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20440, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她弹钢琴得水平很高。", "corrected_sentence": "她弹钢琴的水平很高。", "error_description": "“的”误用：“弹钢琴”修饰“水平”时要用“的”，不能用“得”；“得”只用于动词后引出补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c52ccf7c-18a6-4962-acc1-231bfff3779e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20440, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他游泳的水平很的高。", "corrected_sentence": "他游泳的水平很高。", "error_description": "多余成分：“很”与“高”之间不能加“的”，应说“水平很高”，不能说“很的高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c52ccf7c-18a6-4962-acc1-231bfff3779e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
