INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20442, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "故事、戏剧或生活中某人所扮演的人物或身份。", "primary_collocate": null, "pronunciation": "jué sè", "ipa": "tɕɥe˧˥ sɤ˥˩", "syllable_count": 2, "sentences": [{"text": "他在电影里演一个老人的角色。", "target_word": "角色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个角色很有意思，我很喜欢。", "target_word": "角色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部动画片里的角色都很可爱。", "target_word": "角色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一次演这样的角色。", "target_word": "角色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电视剧里的角色是一位退休的老教授。", "target_word": "角色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都想演小猫这个角色。", "target_word": "角色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书里有三个主要角色。", "target_word": "角色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏里的角色会说四种语言。", "target_word": "角色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明在这个游戏里选了一个新角色。", "target_word": "角色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很会演坏人的角色。", "target_word": "角色", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "角色扮演", "label": "复合词"}], "register": "中性", "sense_fingerprint": "故事或生活中某个人所扮演的人物或身份", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b8f789-626d-40d7-a308-633398a91259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20442, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "角色", "is_correct": true, "explanation": "角色：指戏里扮演的人物，与“演”相配，符合句意。"}, {"text": "演员", "is_correct": false, "explanation": "语义：演员是扮演者本人，不是被扮演的人物。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂是场所，不是可以被扮演的对象。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“演”的对象是人物或角色，不能说“演年龄”。"}], "explanations": {"角色": "角色：指戏里扮演的人物，与“演”相配，符合句意。", "演员": "语义：演员是扮演者本人，不是被扮演的人物。", "工厂": "语义：工厂是场所，不是可以被扮演的对象。", "年龄": "搭配：“演”的对象是人物或角色，不能说“演年龄”。"}, "sentence_index": 0, "correct_answer": "角色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的角色很便宜。", "explanation": "这里应该用〈价格〉。角色指剧中或生活中的人，不能用来说衣服的价钱。"}, {"text": "舞台上摆着一个角色，等着演员去拿。", "explanation": "这里应该用〈道具〉。角色是剧中的人物，不是可以摆放的物品。"}, {"text": "台下坐满了角色，都在看戏。", "explanation": "这里应该用〈观众〉。角色是剧中人物，不是台下看戏的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20442, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "角色", "is_correct": true, "explanation": "角色：指书中的人物，与“三个主要”相配，符合句意。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”不是书里可以数的成分，句子意思不通。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度是数值，不能说书里有“三个主要温度”。"}, {"text": "演技", "is_correct": false, "explanation": "搭配：演技不可数，不能与“三个”搭配。"}], "explanations": {"角色": "角色：指书中的人物，与“三个主要”相配，符合句意。", "味道": "语义：“味道”不是书里可以数的成分，句子意思不通。", "温度": "语义：温度是数值，不能说书里有“三个主要温度”。", "演技": "搭配：演技不可数，不能与“三个”搭配。"}, "sentence_index": 6, "correct_answer": "角色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她每天早上都会穿角色。", "explanation": "这里应该用〈衣服〉。角色指人物，不能像衣服一样被穿。"}, {"text": "妈妈在厨房里煮了角色。", "explanation": "这里应该用〈汤〉。角色指人物，不能被煮。"}, {"text": "他的角色有一米八。", "explanation": "这里应该用〈身高〉。角色指人物或扮演的身份，不能说身体的高矮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20442, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部小说里有一只有趣的角色。", "corrected_sentence": "这部小说里有一个有趣的角色。", "error_description": "量词错误：“一只有趣的角色”中的“只”应改为“个”。“只”多用于动物，人物角色用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20442, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这个角色演很好。", "corrected_sentence": "他把这个角色演得很好。", "error_description": "补语错误：“把”字句中，“演”后的程度补语要用“得”引出，少了“得”，应说“他把这个角色演得很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6859f5b-5a32-49f4-8561-413cccc734f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20444, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "远", "is_correct": true, "explanation": "正确：“远”与“近”是反义词，表示距离远。"}, {"text": "快", "is_correct": false, "explanation": "“快”与“近”无反义关系，“快”指速度。"}, {"text": "宽", "is_correct": false, "explanation": "“宽”与“近”无反义关系，“宽”指宽度。"}, {"text": "高", "is_correct": false, "explanation": "“高”与“近”无反义关系，“高”指高度。"}], "correct_answer": "远", "explanations": {"远": "正确：“远”与“近”是反义词，表示距离远。", "快": "“快”与“近”无反义关系，“快”指速度。", "宽": "“宽”与“近”无反义关系，“宽”指宽度。", "高": "“高”与“近”无反义关系，“高”指高度。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ead0f57e-393d-43ff-b200-52770069b672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20444, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "远", "is_correct": true, "explanation": "正确：“远”与“近”是反义词，表示距离远。"}, {"text": "厚", "is_correct": false, "explanation": "“厚”与“近”无反义关系，“厚”指厚度。"}, {"text": "亮", "is_correct": false, "explanation": "“亮”与“近”无反义关系，“亮”指光线明亮。"}, {"text": "硬", "is_correct": false, "explanation": "“硬”与“近”无反义关系，“硬”指质地坚硬。"}], "correct_answer": "远", "explanations": {"远": "正确：“远”与“近”是反义词，表示距离远。", "厚": "“厚”与“近”无反义关系，“厚”指厚度。", "亮": "“亮”与“近”无反义关系，“亮”指光线明亮。", "硬": "“硬”与“近”无反义关系，“硬”指质地坚硬。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ead0f57e-393d-43ff-b200-52770069b672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20444, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示两个东西离得不远。", "primary_collocate": null, "pronunciation": "jìn", "ipa": "tɕin˥˩", "syllable_count": 1, "sentences": [{"text": "我家离学校很近。", "target_word": "近", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这里离地铁站近，上班很方便。", "target_word": "近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司离我家不近，我坐车去。", "target_word": "近", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请坐近一点，我听不清。", "target_word": "近", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他住得离我很近，我们常见面。", "target_word": "近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他家离公园很近，走路五分钟。", "target_word": "近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想找一个离公司近的房子。", "target_word": "近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭馆离我们很近，走五分钟就到。", "target_word": "近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校离家近，他每天走路回家。", "target_word": "近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你家离海近不近？", "target_word": "近", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "近一点", "label": "复合"}, {"form": "附近", "label": "复合"}], "register": "中性", "sense_fingerprint": "空间上两处距离短，不远", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eddf536e-727f-466d-9471-e2a4e4949a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20444, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "近", "is_correct": true, "explanation": "正确：“近”读 jìn（第四声），表示空间上距离不远。"}, {"text": "紧", "is_correct": false, "explanation": "jǐn（第三声）与 jìn（第四声）声调不同，意思是紧密、紧张。"}, {"text": "信", "is_correct": false, "explanation": "xìn 与 jìn 声母不同（x 与 j），意思是信件、相信。"}, {"text": "静", "is_correct": false, "explanation": "jìng 与 jìn 韵母不同（-ng 与 -n），意思是安静。"}], "explanations": {"近": "正确：“近”读 jìn（第四声），表示空间上距离不远。", "紧": "jǐn（第三声）与 jìn（第四声）声调不同，意思是紧密、紧张。", "信": "xìn 与 jìn 声母不同（x 与 j），意思是信件、相信。", "静": "jìng 与 jìn 韵母不同（-ng 与 -n），意思是安静。"}, "sentence_index": null, "correct_answer": "近"}, "level_3": {"options": [{"text": "近", "is_correct": true, "explanation": "正确：“离学校很近”表示距离不远，符合语境。"}, {"text": "大", "is_correct": false, "explanation": "搭配：“离……很大”不能用来描述距离。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”形容光线，不能用来形容距离。"}, {"text": "硬", "is_correct": false, "explanation": "语义：“硬”形容质地，与距离无关。"}], "explanations": {"近": "正确：“离学校很近”表示距离不远，符合语境。", "大": "搭配：“离……很大”不能用来描述距离。", "亮": "语义：“亮”形容光线，不能用来形容距离。", "硬": "语义：“硬”形容质地，与距离无关。"}, "sentence_index": 0, "correct_answer": "近"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭馆离我家很近，坐飞机要三个小时才能到。", "explanation": "这里应该用〈远〉。“很近”与“坐飞机要三个小时才能到”矛盾，说明距离远，要用〈远〉。"}, {"text": "他的态度很近，大家都很喜欢他。", "explanation": "这里应该用〈亲切〉。“近”表示距离不远，不能形容态度，表示态度友好要用〈亲切〉。"}, {"text": "这家店离我家近，所以我每天要坐两个小时的车去。", "explanation": "这里应该用〈远〉。“近”与“坐两个小时的车”矛盾，需要长时间乘车说明距离远。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ead0f57e-393d-43ff-b200-52770069b672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20444, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "近", "is_correct": true, "explanation": "正确：“近”读 jìn（第四声），表示空间上距离不远。"}, {"text": "今", "is_correct": false, "explanation": "jīn（第一声）与 jìn（第四声）声调不同，意思是今天。"}, {"text": "俊", "is_correct": false, "explanation": "jùn 与 jìn 韵母不同（-un 与 -in），意思是英俊。"}, {"text": "敬", "is_correct": false, "explanation": "jìng 与 jìn 韵母不同（-ng 与 -n），意思是尊敬。"}, {"text": "镜", "is_correct": false, "explanation": "jìng 与 jìn 韵母不同（-ng 与 -n），意思是镜子。"}], "explanations": {"近": "正确：“近”读 jìn（第四声），表示空间上距离不远。", "今": "jīn（第一声）与 jìn（第四声）声调不同，意思是今天。", "俊": "jùn 与 jìn 韵母不同（-un 与 -in），意思是英俊。", "敬": "jìng 与 jìn 韵母不同（-ng 与 -n），意思是尊敬。", "镜": "jìng 与 jìn 韵母不同（-ng 与 -n），意思是镜子。"}, "sentence_index": null, "correct_answer": "近"}, "level_3": {"options": [{"text": "近", "is_correct": true, "explanation": "正确：“离公司近的房子”指房子距离公司不远，符合语境。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“离……高”不能用来描述距离。"}, {"text": "白", "is_correct": false, "explanation": "语义：“白”指颜色，与距离无关。"}, {"text": "软", "is_correct": false, "explanation": "语义：“软”形容质地，与距离无关。"}], "explanations": {"近": "正确：“离公司近的房子”指房子距离公司不远，符合语境。", "高": "搭配：“离……高”不能用来描述距离。", "白": "语义：“白”指颜色，与距离无关。", "软": "语义：“软”形容质地，与距离无关。"}, "sentence_index": 6, "correct_answer": "近"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的房子离学校很近，要走一整天才能到。", "explanation": "这里应该用〈远〉。“很近”与“要走一整天才能到”矛盾，说明距离远，要用〈远〉。"}, {"text": "他的脾气很近，大家都愿意和他玩。", "explanation": "这里应该用〈温和〉。“近”形容距离，不能形容脾气。"}, {"text": "你家离海近，要坐一个月的船才能到。", "explanation": "这里应该用〈远〉。“近”与“坐一个月的船”矛盾，需要长时间航行说明距离远。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ead0f57e-393d-43ff-b200-52770069b672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20444, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家书店离地铁站近很。", "corrected_sentence": "这家书店离地铁站很近。", "error_description": "错误形式“近很”，正确形式“很近”。“很”作状语，应放在形容词“近”之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ead0f57e-393d-43ff-b200-52770069b672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20444, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他住的地方从车站很近。", "corrected_sentence": "他住的地方离车站很近。", "error_description": "错误形式“从车站很近”，正确形式“离车站很近”。表示两地距离远近时要用“离＋地点＋近”，不能用“从”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ead0f57e-393d-43ff-b200-52770069b672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
