INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20446, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "变高，往上走。", "primary_collocate": null, "pronunciation": "shēng gāo", "ipa": "ʂɤŋ˥ kɑʊ˥", "syllable_count": 2, "sentences": [{"text": "气球慢慢升高，飞到了天上。", "target_word": "升高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳升高以后，天气热起来了。", "target_word": "升高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机升高以后，云在脚下。", "target_word": "升高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火箭升高的时候，声音很大。", "target_word": "升高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水位升高了，河边的路不能走了。", "target_word": "升高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "座椅慢慢升高了。", "target_word": "升高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "月亮升高了，院子里更亮了。", "target_word": "升高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "烟慢慢升高，最后看不见了。", "target_word": "升高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风筝升高以后，我们就看不清它了。", "target_word": "升高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电梯慢慢升高，停在了十楼。", "target_word": "升高", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "升高了", "label": "完成体"}, {"form": "升高过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "升高：物体的位置向上移动、变高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c708da23-8b74-483b-bea2-78da0da78450') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20446, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "升高", "is_correct": true, "explanation": "升高：气球向上移动、位置变高，符合句意。"}, {"text": "下沉", "is_correct": false, "explanation": "语义：“下沉”与后句“飞到了天上”方向相反，句子不成立。"}, {"text": "长高", "is_correct": false, "explanation": "搭配：“长高”只说人或植物的身高，不能用于气球。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：气球不会唱歌，与句子描写的运动不符。"}], "explanations": {"升高": "升高：气球向上移动、位置变高，符合句意。", "下沉": "语义：“下沉”与后句“飞到了天上”方向相反，句子不成立。", "长高": "搭配：“长高”只说人或植物的身高，不能用于气球。", "唱歌": "语义：气球不会唱歌，与句子描写的运动不符。"}, "sentence_index": 0, "correct_answer": "升高"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他今年又升高了五厘米。", "explanation": "这里应该用〈长高〉。人的身高增加说长高，升高不用于人的身体高度。"}, {"text": "这双鞋能让我升高五厘米。", "explanation": "这里应该用〈增高〉。鞋垫或高跟鞋让人显得更高说增高，升高指物体往上走，不用于人体的高度增加。"}, {"text": "他升高了手，要回答问题。", "explanation": "这里应该用〈举起〉。人用手向上抬起时说举起，升高不用于人的肢体动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9887ccc-ea02-4a69-9a01-abd713e7242c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20446, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "升高", "is_correct": true, "explanation": "升高：月亮向上移动、位置变高，符合句意。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：月亮不会跳舞，与“院子里更亮了”的描写不相关。"}, {"text": "生长", "is_correct": false, "explanation": "搭配：“生长”用于生物，不用于天体的位置变化。"}, {"text": "散步", "is_correct": false, "explanation": "语义：月亮不会散步，句子描写的是月亮位置的变化。"}], "explanations": {"升高": "升高：月亮向上移动、位置变高，符合句意。", "跳舞": "语义：月亮不会跳舞，与“院子里更亮了”的描写不相关。", "生长": "搭配：“生长”用于生物，不用于天体的位置变化。", "散步": "语义：月亮不会散步，句子描写的是月亮位置的变化。"}, "sentence_index": 6, "correct_answer": "升高"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他升高了脚步，走进了屋子。", "explanation": "这里应该用〈加快〉。升高指物体向上移动，脚步快慢的变化要说加快。"}, {"text": "一阵风升高了窗帘。", "explanation": "这里应该用〈掀起〉。风把窗帘吹起时说掀起，升高不用于这种动作。"}, {"text": "她升高着围巾向我们打招呼。", "explanation": "这里应该用〈挥舞〉。人用手左右或上下摆动物件时说挥舞，升高不用于这种动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9887ccc-ea02-4a69-9a01-abd713e7242c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20446, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "热气球慢慢升高的了。", "corrected_sentence": "热气球慢慢升高了。", "error_description": "错误形式：“升高的了”；正确形式：“升高了”（句中“慢慢”保留不动）。“的”多余，完成体“了”应直接接在动补结构“升高”之后，中间不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9887ccc-ea02-4a69-9a01-abd713e7242c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20446, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "热气球升高的很快。", "corrected_sentence": "热气球升高得很快。", "error_description": "错误形式：“升高的很快”；正确形式：“升高得很快”。表示程度的补语前要用结构助词“得”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9887ccc-ea02-4a69-9a01-abd713e7242c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
