INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20448, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "让人想很多，想很久。", "primary_collocate": null, "pronunciation": "yǐn rén shēn sī", "ipa": "in˨˩ ɻən˧˥ ʂən˥˥ sɹ̩˥˥", "syllable_count": 4, "sentences": [{"text": "他的话引人深思，我想了一晚上。", "target_word": "引人深思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章不长，但是引人深思。", "target_word": "引人深思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个老人的做法非常引人深思。", "target_word": "引人深思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画看起来简单，其实引人深思。", "target_word": "引人深思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提出的问题非常引人深思。", "target_word": "引人深思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事很引人深思，同学们都安静了。", "target_word": "引人深思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影最后一句话引人深思。", "target_word": "引人深思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈讲的小时候的事，真的很引人深思。", "target_word": "引人深思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛的结果引人深思。", "target_word": "引人深思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长的演讲不长，却引人深思。", "target_word": "引人深思", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "成语；某件事或某句话让人想很多、想很久", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2b17fa-c08d-40b7-9a9a-4277d5c11bc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20448, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "引人深思", "is_correct": true, "explanation": "正确：“引人深思”指让人想很多、想很久，与“我想了一晚上”相合。"}, {"text": "无聊", "is_correct": false, "explanation": "语义：“无聊”说明话没有价值，与“我想了一晚上”的深入思考相矛盾。"}, {"text": "吵闹", "is_correct": false, "explanation": "搭配：“吵闹”形容声音或环境，不能用来形容话语。"}, {"text": "一目了然", "is_correct": false, "explanation": "语义：“一目了然”指一看就明白，与“想了一晚上”的深入思考相矛盾。"}], "explanations": {"引人深思": "正确：“引人深思”指让人想很多、想很久，与“我想了一晚上”相合。", "无聊": "语义：“无聊”说明话没有价值，与“我想了一晚上”的深入思考相矛盾。", "吵闹": "搭配：“吵闹”形容声音或环境，不能用来形容话语。", "一目了然": "语义：“一目了然”指一看就明白，与“想了一晚上”的深入思考相矛盾。"}, "sentence_index": 0, "correct_answer": "引人深思"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆红色跑车很引人深思。", "explanation": "这里应该用〈引人注目〉。引人深思指让人思考，跑车的醒目外形应用引人注目来形容。"}, {"text": "那只猫追尾巴的样子很引人深思。", "explanation": "这里应该用〈引人发笑〉。引人深思指引发思考，猫追尾巴的滑稽样子应当引人发笑。"}, {"text": "这盘红烧肉很引人深思。", "explanation": "这里应该用〈引人垂涎〉。引人深思指引发思考，红烧肉诱人的样子应用引人垂涎来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c52ccf7c-18a6-4962-acc1-231bfff3779e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20448, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "引人深思", "is_correct": true, "explanation": "正确：“引人深思”指让人深入思考，与“最后一句话”能引发思考相合。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场面，不能用来形容一句台词。"}, {"text": "乏味", "is_correct": false, "explanation": "语义：“乏味”说明内容无趣，与“引人深思”的效果相反。"}, {"text": "闷热", "is_correct": false, "explanation": "语义：“闷热”说的是天气，与电影台词的内容无关，句意不通。"}], "explanations": {"引人深思": "正确：“引人深思”指让人深入思考，与“最后一句话”能引发思考相合。", "热闹": "搭配：“热闹”形容场面，不能用来形容一句台词。", "乏味": "语义：“乏味”说明内容无趣，与“引人深思”的效果相反。", "闷热": "语义：“闷热”说的是天气，与电影台词的内容无关，句意不通。"}, "sentence_index": 6, "correct_answer": "引人深思"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的穿着很引人深思。", "explanation": "这里应该用〈引人侧目〉。引人深思指引发思考，穿着引人注意要用引人侧目来形容。"}, {"text": "小丑滑倒的样子很引人深思。", "explanation": "这里应该用〈引人发笑〉。引人深思指引发思考，小丑滑倒的滑稽样子应当引人发笑。"}, {"text": "这只鹦鹉的叫声很引人深思。", "explanation": "这里应该用〈引人注意〉。引人深思指引发思考，鹦鹉的叫声只能引人注意，不能使人深思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c52ccf7c-18a6-4962-acc1-231bfff3779e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20448, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本书的结尾把引人深思。", "corrected_sentence": "这本书的结尾很引人深思。", "error_description": "结构错误：「把」字句须带动词谓语，「把引人深思」残缺不成句；应说「这本书的结尾很引人深思。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c52ccf7c-18a6-4962-acc1-231bfff3779e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20448, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈讲的那件往事很引人深思了我。", "corrected_sentence": "妈妈讲的那件往事很引人深思。", "error_description": "错误：“引人深思了我”。正确：“引人深思”。“引人深思”本身已含“人”，是不及物的成语，后面不能再带宾语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c52ccf7c-18a6-4962-acc1-231bfff3779e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
