INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20450, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "控制住，不让它发生或发展。", "primary_collocate": null, "pronunciation": "yì zhì", "ipa": "i˥˩ ʈʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他努力抑制着心里的怒火，没有发火。", "target_word": "抑制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药可以抑制细菌生长。", "target_word": "抑制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想办法抑制物价上涨。", "target_word": "抑制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她抑制不住内心的激动，哭了。", "target_word": "抑制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说这种药能抑制咳嗽。", "target_word": "抑制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个笑话，他怎么也抑制不住笑声。", "target_word": "抑制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "低温能抑制细菌的繁殖。", "target_word": "抑制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要抑制购物的冲动，不乱花钱。", "target_word": "抑制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过度减肥会抑制孩子的生长。", "target_word": "抑制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他抑制着眼泪，笑着和朋友告别。", "target_word": "抑制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抑制着", "label": "体标"}, {"form": "抑制了", "label": "体标"}, {"form": "抑制过", "label": "体标"}], "register": "书面", "sense_fingerprint": "控制住情绪、生长、上涨等，使其不发生或不发展", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69273c12-942b-4785-8ed5-3d4f334825ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20450, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "抑制", "is_correct": true, "explanation": "正确答案：抑制（yì zhì），意思是控制住，不让它发生或发展。"}, {"text": "一直", "is_correct": false, "explanation": "一直（yì zhí）与抑制的第二个音节声调不同：zhí 是第二声，zhì 是第四声。一直的意思是始终。"}, {"text": "议事", "is_correct": false, "explanation": "议事（yì shì）与抑制的第二个音节声母不同：shì 是 sh，zhì 是 zh。议事的意思是商议事情。"}, {"text": "义肢", "is_correct": false, "explanation": "义肢（yì zhī）与抑制的第二个音节声调不同：zhī 是第一声，zhì 是第四声。义肢指装在残缺肢体上的人造肢体。"}], "explanations": {"抑制": "正确答案：抑制（yì zhì），意思是控制住，不让它发生或发展。", "一直": "一直（yì zhí）与抑制的第二个音节声调不同：zhí 是第二声，zhì 是第四声。一直的意思是始终。", "议事": "议事（yì shì）与抑制的第二个音节声母不同：shì 是 sh，zhì 是 zh。议事的意思是商议事情。", "义肢": "义肢（yì zhī）与抑制的第二个音节声调不同：zhī 是第一声，zhì 是第四声。义肢指装在残缺肢体上的人造肢体。"}, "sentence_index": null, "correct_answer": "抑制"}, "level_3": {"options": [{"text": "抑制", "is_correct": true, "explanation": "正确：「努力抑制着心里的怒火」与「没有发火」相符，表示压住情绪。"}, {"text": "释放", "is_correct": false, "explanation": "语义：「释放」是放出，与「没有发火」矛盾，句子说的是压住怒火而不是放出。"}, {"text": "分享", "is_correct": false, "explanation": "搭配：「分享」后面接快乐、心事等，不能接「怒火」。"}, {"text": "发泄", "is_correct": false, "explanation": "语义：「发泄」指把情绪宣泄出来，与「没有发火」矛盾。"}], "explanations": {"抑制": "正确：「努力抑制着心里的怒火」与「没有发火」相符，表示压住情绪。", "释放": "语义：「释放」是放出，与「没有发火」矛盾，句子说的是压住怒火而不是放出。", "分享": "搭配：「分享」后面接快乐、心事等，不能接「怒火」。", "发泄": "语义：「发泄」指把情绪宣泄出来，与「没有发火」矛盾。"}, "sentence_index": 0, "correct_answer": "抑制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈抑制了我去网吧。", "explanation": "这里应该用〈阻止〉。抑制用于情绪、生长、物价等不断发展的倾向，不能用来禁止某人去做具体的事。"}, {"text": "这支队伍在上半场抑制了对手。", "explanation": "这里应该用〈压制〉。压制指以强力使对方处于劣势，用于对手和局面；抑制是控制不断发展的事物，不用于正面较量的对手。"}, {"text": "他把心里的秘密抑制起来，从没告诉过别人。", "explanation": "这里应该用〈隐瞒〉。抑制指压住不让它发展，不指隐藏信息；秘密要说隐瞒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20450, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "抑制", "is_correct": true, "explanation": "正确答案：抑制（yì zhì），意思是控制住，不让它发生或发展。"}, {"text": "一致", "is_correct": false, "explanation": "一致（yí zhì）第一个音节声调不同：yí 是第二声，yì 是第四声。一致的意思是相同、统一。"}, {"text": "以致", "is_correct": false, "explanation": "以致（yǐ zhì）第一个音节声调不同：yǐ 是第三声，yì 是第四声。以致的意思是因而导致。"}, {"text": "一直", "is_correct": false, "explanation": "一直（yì zhí）与抑制的第二个音节声调不同：zhí 是第二声，zhì 是第四声。一直的意思是始终。"}], "explanations": {"抑制": "正确答案：抑制（yì zhì），意思是控制住，不让它发生或发展。", "一致": "一致（yí zhì）第一个音节声调不同：yí 是第二声，yì 是第四声。一致的意思是相同、统一。", "以致": "以致（yǐ zhì）第一个音节声调不同：yǐ 是第三声，yì 是第四声。以致的意思是因而导致。", "一直": "一直（yì zhí）与抑制的第二个音节声调不同：zhí 是第二声，zhì 是第四声。一直的意思是始终。"}, "sentence_index": null, "correct_answer": "抑制"}, "level_3": {"options": [{"text": "抑制", "is_correct": true, "explanation": "正确：低温能减缓细菌的繁殖，「抑制」符合常识。"}, {"text": "促进", "is_correct": false, "explanation": "语义：「促进」是推动，低温会减缓而不是推动细菌繁殖。"}, {"text": "加速", "is_correct": false, "explanation": "语义：「加速」是加快，与「低温」的作用相反。"}, {"text": "抚养", "is_correct": false, "explanation": "搭配：「抚养」的对象是孩子或动物，不能用于细菌的繁殖。"}], "explanations": {"抑制": "正确：低温能减缓细菌的繁殖，「抑制」符合常识。", "促进": "语义：「促进」是推动，低温会减缓而不是推动细菌繁殖。", "加速": "语义：「加速」是加快，与「低温」的作用相反。", "抚养": "搭配：「抚养」的对象是孩子或动物，不能用于细菌的繁殖。"}, "sentence_index": 6, "correct_answer": "抑制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这门课的教学质量抑制了很多。", "explanation": "这里应该用〈提高〉。抑制表示压低、遏制，用于不断发展的倾向，不能用于正向提升质量。"}, {"text": "他双手抑制着方向盘，稳稳地开着车。", "explanation": "这里应该用〈控制〉。抑制指遏制某种倾向，不用于操纵方向盘等具体的物体。"}, {"text": "他抑制了自己的错误，没有让别人发现。", "explanation": "这里应该用〈掩盖〉。掩盖指遮住不让人看见；抑制指压低不断发展的倾向，不能用来表示隐藏错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20450, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈抑制了着哭声，不让孩子看见她难过。", "corrected_sentence": "妈妈抑制着哭声，不让孩子看见她难过。", "error_description": "错误：「抑制了着」同时用了「了」和「着」两个体标。「着」表示状态持续，不能与「了」并用，应改为「抑制着」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20450, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们终于抑制了住愤怒，没有在会上吵起来。", "corrected_sentence": "他们终于抑制住了愤怒，没有在会上吵起来。", "error_description": "错误：结果补语「住」的位置不对。应为「抑制住了」，「住」紧跟动词，「了」放在补语之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
