INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20452, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种东西，能挡住另一种东西的作用。", "primary_collocate": null, "pronunciation": "jié kàng jì", "ipa": "tɕje˧˥ kʰaŋ˥˩ tɕi˥˩", "syllable_count": 3, "sentences": [{"text": "这种拮抗剂能挡住药的作用。", "target_word": "拮抗剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说要用拮抗剂。", "target_word": "拮抗剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拮抗剂可以让药不再起作用。", "target_word": "拮抗剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶是拮抗剂，不是普通的药。", "target_word": "拮抗剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝了药，医生马上给他拮抗剂。", "target_word": "拮抗剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拮抗剂的作用和药相反。", "target_word": "拮抗剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室里有几种拮抗剂。", "target_word": "拮抗剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个拮抗剂是新研究出来的。", "target_word": "拮抗剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人用了拮抗剂以后好多了。", "target_word": "拮抗剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拮抗剂能与受体结合，阻止激动剂发挥作用。", "target_word": "拮抗剂", "complexity_tier": "T3", "furigana": "jié kàng jì néng yǔ shòu tǐ jié hé，zǔ zhǐ jī dòng jì fā huī zuò yòng。", "sentence_source": "generated"}], "morphological_forms": [{"form": "拮抗劑", "label": "繁体"}, {"form": "受体拮抗剂", "label": "复合"}], "register": "专业", "sense_fingerprint": "拮抗剂：能挡住另一种东西作用的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2b17fa-c08d-40b7-9a9a-4277d5c11bc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20452, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拮抗剂", "is_correct": true, "explanation": "拮抗剂指能挡住另一种东西作用的东西，正好对应句中“挡住药的作用”。"}, {"text": "兴奋剂", "is_correct": false, "explanation": "语义：兴奋剂是使人兴奋的物质，与“挡住药的作用”的意思相反。"}, {"text": "调味剂", "is_correct": false, "explanation": "语域：调味剂是烹饪用语，不用于药理语境。"}, {"text": "催化剂", "is_correct": false, "explanation": "搭配：催化剂说“起催化作用”，不说“挡住作用”。"}], "explanations": {"拮抗剂": "拮抗剂指能挡住另一种东西作用的东西，正好对应句中“挡住药的作用”。", "兴奋剂": "语义：兴奋剂是使人兴奋的物质，与“挡住药的作用”的意思相反。", "调味剂": "语域：调味剂是烹饪用语，不用于药理语境。", "催化剂": "搭配：催化剂说“起催化作用”，不说“挡住作用”。"}, "sentence_index": 0, "correct_answer": "拮抗剂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种拮抗剂能防止食物变质。", "explanation": "这里应该用〈防腐剂〉。拮抗剂是挡住另一种东西作用的东西，不用于防止食物变质。"}, {"text": "这种拮抗剂能加快化学反应。", "explanation": "这里应该用〈催化剂〉。拮抗剂是挡住作用的东西，不能加快化学反应。"}, {"text": "这种拮抗剂能让植物长得更快。", "explanation": "这里应该用〈肥料〉。拮抗剂的作用是挡住，不能促进植物生长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c52ccf7c-18a6-4962-acc1-231bfff3779e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20452, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拮抗剂", "is_correct": true, "explanation": "拮抗剂指能挡住另一种东西作用的东西，符合“实验室”的专业语境。"}, {"text": "抵抗", "is_correct": false, "explanation": "词性：“抵抗”是动词，不能作“几种”后的名词。"}, {"text": "拮抗", "is_correct": false, "explanation": "词性：“拮抗”是动词，指相互抑制，“几种拮抗”不成立，要用名词“拮抗剂”。"}, {"text": "急忙", "is_correct": false, "explanation": "词性：“急忙”是副词，不能作“几种”后的名词。"}], "explanations": {"拮抗剂": "拮抗剂指能挡住另一种东西作用的东西，符合“实验室”的专业语境。", "抵抗": "词性：“抵抗”是动词，不能作“几种”后的名词。", "拮抗": "词性：“拮抗”是动词，指相互抑制，“几种拮抗”不成立，要用名词“拮抗剂”。", "急忙": "词性：“急忙”是副词，不能作“几种”后的名词。"}, "sentence_index": 6, "correct_answer": "拮抗剂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种拮抗剂能让病人失去知觉。", "explanation": "这里应该用〈麻醉剂〉。拮抗剂是挡住另一种东西作用的东西，不能使人失去知觉。"}, {"text": "这种拮抗剂能让运动员更兴奋。", "explanation": "这里应该用〈兴奋剂〉。拮抗剂是挡住作用的东西，不能使人兴奋。"}, {"text": "这种拮抗剂能让人获得长期免疫。", "explanation": "这里应该用〈疫苗〉。拮抗剂是挡住另一种东西作用的东西，不能让人产生免疫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c52ccf7c-18a6-4962-acc1-231bfff3779e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20452, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些拮抗剂们都能阻止药物发挥作用。", "corrected_sentence": "这些拮抗剂都能阻止药物发挥作用。", "error_description": "错误：“拮抗剂们”；正确：“拮抗剂”。“们”一般只加在指人的名词后面，拮抗剂是物质名词，不能加“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c52ccf7c-18a6-4962-acc1-231bfff3779e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20452, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生给他打了一只拮抗剂。", "corrected_sentence": "医生给他打了一针拮抗剂。", "error_description": "错误：“一只拮抗剂”。正确：“一针拮抗剂”。“只”不用于药剂；“打针”一次注射用量词“针”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c52ccf7c-18a6-4962-acc1-231bfff3779e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
