INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20458, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "由生病的原因或身体变化引起的，与“生理性”相对。", "primary_collocate": null, "pronunciation": "bìng lǐ xìng", "ipa": "piŋ˥˩ li˨˩˦ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "医生说他的头疼是病理性的。", "target_word": "病理性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种身体变化是病理性的，要吃药。", "target_word": "病理性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子发烧有病理性的原因。", "target_word": "病理性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生想知道他咳嗽有没有病理性原因。", "target_word": "病理性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "累了会打哈欠，这不是病理性的。", "target_word": "病理性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人皮肤变黄，可能是病理性变化。", "target_word": "病理性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是正常反应，不是病理性问题。", "target_word": "病理性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她总是很累，医生查了病理性原因。", "target_word": "病理性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明的脸很红，是病理性的反应吗？", "target_word": "病理性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有病理性的疼痛，必须去看医生。", "target_word": "病理性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "病理学", "label": "复合"}, {"form": "非病理性", "label": "派生"}], "register": "中性", "sense_fingerprint": "病理性：由生病的原因或身体变化引起的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f86388a0-d51c-4e9d-b000-ecf475b0afc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20458, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "病理性", "is_correct": true, "explanation": "病理性指由生病的原因或身体变化引起，句中说头疼是这样的，符合句意。"}, {"text": "悦耳", "is_correct": false, "explanation": "语义：悦耳形容声音好听，不能用来描述头疼的性质。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：寒冷形容温度低，与头疼的性质无关，不符合句意。"}, {"text": "给力", "is_correct": false, "explanation": "语域：“给力”是口语网络用语，与医学叙述的书面语域不协调，而且不能描述疾病的性质。"}], "explanations": {"病理性": "病理性指由生病的原因或身体变化引起，句中说头疼是这样的，符合句意。", "悦耳": "语义：悦耳形容声音好听，不能用来描述头疼的性质。", "寒冷": "语义：寒冷形容温度低，与头疼的性质无关，不符合句意。", "给力": "语域：“给力”是口语网络用语，与医学叙述的书面语域不协调，而且不能描述疾病的性质。"}, "sentence_index": 0, "correct_answer": "病理性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一个病理性的人，做事总是很冷静。", "explanation": "这里应该用〈理智〉。“病理性”指生病的原因或身体变化，不能用来形容一个人做事理智、冷静。"}, {"text": "这是正常的病理性反应，不用担心。", "explanation": "这里应该用〈生理性〉。“病理性”指由生病引起的变化，不能用于形容正常的身体反应。"}, {"text": "他有一副病理性的身体，每天能跑五公里。", "explanation": "这里应该用〈健康〉。“病理性”指生病的原因或身体变化，不能用来形容身体健康、能跑五公里的状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e9dc6a-731f-4989-9f53-dfbadddc86f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20458, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "病理性", "is_correct": true, "explanation": "病理性问题指由疾病引起的问题，与“正常反应”相对，句意通顺。"}, {"text": "灿烂", "is_correct": false, "explanation": "语义：灿烂形容光彩耀眼，不能修饰“问题”，与“正常反应”的语境无关。"}, {"text": "辉煌", "is_correct": false, "explanation": "语义：辉煌形容成就或景象宏大，不能用来修饰“问题”，不符合句意。"}, {"text": "超赞", "is_correct": false, "explanation": "语域：“超赞”是口语网络用语，与句子的书面表达不协调，而且不能修饰“问题”。"}], "explanations": {"病理性": "病理性问题指由疾病引起的问题，与“正常反应”相对，句意通顺。", "灿烂": "语义：灿烂形容光彩耀眼，不能修饰“问题”，与“正常反应”的语境无关。", "辉煌": "语义：辉煌形容成就或景象宏大，不能用来修饰“问题”，不符合句意。", "超赞": "语域：“超赞”是口语网络用语，与句子的书面表达不协调，而且不能修饰“问题”。"}, "sentence_index": 6, "correct_answer": "病理性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "春天到了，树叶病理性地变绿了。", "explanation": "这里应该用〈自然地〉。“病理性”指由疾病引起的身体变化，树叶随季节变绿是自然现象，不能说是病理性的。"}, {"text": "这家饭店的菜是病理性的，大家都说好吃。", "explanation": "这里应该用〈可口〉。“病理性”只指疾病的原因或身体变化，不能用来评价食物的味道。"}, {"text": "他们的婚礼是病理性的，宾客们都很满意。", "explanation": "这里应该用〈喜庆〉。“病理性”指生病的原因或身体变化，不能用来形容婚礼的气氛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e9dc6a-731f-4989-9f53-dfbadddc86f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20458, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子发烧可能有一病理性原因，要及时检查。", "corrected_sentence": "孩子发烧可能有一种病理性原因，要及时检查。", "error_description": "量词缺失：“病理性原因”前的“一”后面要加量词“种”，应写作“一种病理性原因”，不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e9dc6a-731f-4989-9f53-dfbadddc86f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20458, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这不是病理性地问题，不用担心。", "corrected_sentence": "这不是病理性的问题，不用担心。", "error_description": "结构助词误用：“地”是状语标记，不能用来修饰名词“问题”。应改为“的”（写作“病理性的问题”）；“病理性问题”不加“的”也合乎规范，但不能用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e9dc6a-731f-4989-9f53-dfbadddc86f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
