INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20460, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "有的人脑子生病了，会想一些奇怪的事或做奇怪的事。", "primary_collocate": null, "pronunciation": "jīng shén bìng", "ipa": "tɕiŋ˥ ʂən˧˥ piŋ˥˩", "syllable_count": 3, "sentences": [{"text": "他有精神病，常常说奇怪的话。", "target_word": "精神病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的精神病又犯了，在街上一直自言自语。", "target_word": "精神病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人有精神病，所以做事很奇怪。", "target_word": "精神病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他得过精神病，现在在医院治疗。", "target_word": "精神病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居说他有精神病，大家都有点怕他。", "target_word": "精神病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人不懂精神病，觉得病人很可怕。", "target_word": "精神病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她妈妈有精神病，常常一个人笑。", "target_word": "精神病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生告诉我们，精神病不是他的错。", "target_word": "精神病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有精神病，把不是真的事当成真的。", "target_word": "精神病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "精神病不是小病，要去医院看。", "target_word": "精神病", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "精神病人", "label": "复合"}, {"form": "精神病院", "label": "复合"}], "register": "口语", "sense_fingerprint": "精神病：脑子生病，想法或行为变得奇怪", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f86388a0-d51c-4e9d-b000-ecf475b0afc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20460, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "精神病", "is_correct": true, "explanation": "精神病指脑子生病，想法或行为变得奇怪，与句中“常常说奇怪的话”相符。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是呼吸道感染，不会让人常常说奇怪的话。"}, {"text": "近视", "is_correct": false, "explanation": "语义：近视只影响视力，与说话的内容无关，不符合句意。"}, {"text": "神经衰弱", "is_correct": false, "explanation": "语域：“神经衰弱”是书面医学用语，与口语句子不协调，而且主要表现为疲劳和失眠，不是说奇怪的话。"}], "explanations": {"精神病": "精神病指脑子生病，想法或行为变得奇怪，与句中“常常说奇怪的话”相符。", "感冒": "语义：感冒是呼吸道感染，不会让人常常说奇怪的话。", "近视": "语义：近视只影响视力，与说话的内容无关，不符合句意。", "神经衰弱": "语域：“神经衰弱”是书面医学用语，与口语句子不协调，而且主要表现为疲劳和失眠，不是说奇怪的话。"}, "sentence_index": 0, "correct_answer": "精神病"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈买了一斤精神病，晚上做菜吃。", "explanation": "这里应该用〈白菜〉。“精神病”指脑子生病，想法或行为变得奇怪，不能指能买来做菜的东西。"}, {"text": "他最近精神病很足，每天都很有干劲。", "explanation": "这里应该用〈精神〉。“精神”指人的状态和活力，“精神病”是疾病名称，不能用来形容状态。"}, {"text": "这顿精神病很好吃，我吃了两碗。", "explanation": "这里应该用〈饭菜〉。“精神病”指脑子生病，不能指食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e9dc6a-731f-4989-9f53-dfbadddc86f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20460, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "精神病", "is_correct": true, "explanation": "精神病指脑子生病，表现为想法或行为奇怪，与“常常一个人笑”的描写相符。"}, {"text": "骨折", "is_correct": false, "explanation": "语义：骨折是骨头断裂，不会让人常常一个人笑。"}, {"text": "皮肤病", "is_correct": false, "explanation": "语义：皮肤病是皮肤的疾病，与人一个人笑没有关系。"}, {"text": "病毒性肝炎", "is_correct": false, "explanation": "语域：“病毒性肝炎”是书面医学用语，与口语句子不协调，而且是肝脏疾病，与笑的行为无关。"}], "explanations": {"精神病": "精神病指脑子生病，表现为想法或行为奇怪，与“常常一个人笑”的描写相符。", "骨折": "语义：骨折是骨头断裂，不会让人常常一个人笑。", "皮肤病": "语义：皮肤病是皮肤的疾病，与人一个人笑没有关系。", "病毒性肝炎": "语域：“病毒性肝炎”是书面医学用语，与口语句子不协调，而且是肝脏疾病，与笑的行为无关。"}, "sentence_index": 6, "correct_answer": "精神病"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间房子的精神病很好，阳光充足。", "explanation": "这里应该用〈采光〉。“精神病”指脑子生病，不能用来说房子的光线。"}, {"text": "医生做出了精神病，马上开了药。", "explanation": "这里应该用〈诊断〉。“精神病”是病名，医生做出的是诊断，不能说“做出精神病”。"}, {"text": "精神病告诉我们，不要乱吃药。", "explanation": "这里应该用〈医生〉。“精神病”指一种脑子生病的状态，不是能说话、给人建议的人，不能作“告诉”的主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e9dc6a-731f-4989-9f53-dfbadddc86f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20460, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他以前得过精神病过，现在已经好了。", "corrected_sentence": "他以前得过精神病，现在已经好了。", "error_description": "“过”多写了一次。“得过”中的“过”表示经历，只需一个，应写作“得过精神病”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e9dc6a-731f-4989-9f53-dfbadddc86f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20460, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她妈妈有一把精神病，常常一个人笑。", "corrected_sentence": "她妈妈有一种精神病，常常一个人笑。", "error_description": "量词误用：“把”用于有柄的物品，不能修饰病名。“精神病”前应用“种”，应写作“一种精神病”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e9dc6a-731f-4989-9f53-dfbadddc86f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
