INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20470, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "身体没有生病，感觉很好。", "primary_collocate": null, "pronunciation": "jiàn kāng", "ipa": "tɕjɛn˥˩ kʰaŋ˥˥", "syllable_count": 2, "sentences": [{"text": "爷爷身体很健康。", "target_word": "健康", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的孩子很健康。", "target_word": "健康", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看起来很健康。", "target_word": "健康", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天跑步，所以很健康。", "target_word": "健康", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小狗健康吗？", "target_word": "健康", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶八十岁了，还很健康。", "target_word": "健康", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说我很健康。", "target_word": "健康", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多运动，你会更健康。", "target_word": "健康", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我希望家人都健康。", "target_word": "健康", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟吃得好，睡得好，很健康。", "target_word": "健康", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不健康", "label": "否定"}, {"form": "健康检查", "label": "复合"}], "register": "中性", "sense_fingerprint": "健康：身体没有病，状态良好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09aebaf0-be95-4ef2-b319-0da839c40a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20470, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "健康", "is_correct": true, "explanation": "健康：身体没有病，状态良好，这里指爷爷身体好。"}, {"text": "快乐", "is_correct": false, "explanation": "搭配：“身体”不能和“快乐”搭配，身体不会快乐。"}, {"text": "便宜", "is_correct": false, "explanation": "语义：“便宜”形容价钱低，不能用来形容身体。"}, {"text": "安静", "is_correct": false, "explanation": "搭配：“安静”形容环境或人的状态，不说身体安静。"}], "explanations": {"健康": "健康：身体没有病，状态良好，这里指爷爷身体好。", "快乐": "搭配：“身体”不能和“快乐”搭配，身体不会快乐。", "便宜": "语义：“便宜”形容价钱低，不能用来形容身体。", "安静": "搭配：“安静”形容环境或人的状态，不说身体安静。"}, "sentence_index": 0, "correct_answer": "健康"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服很健康。", "explanation": "这里应该用〈结实〉。健康指人或动植物的身体没有病，不用于衣服；说衣服耐用要用〈结实〉。"}, {"text": "这个答案很健康。", "explanation": "这里应该用〈正确〉。健康说身体状况，不用来评价答案对错。"}, {"text": "这道题很健康。", "explanation": "这里应该用〈简单〉。健康不用来形容题目的难易。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20470, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "健康", "is_correct": true, "explanation": "健康：身体没有病，这里指医生说我身体很好。"}, {"text": "好吃", "is_correct": false, "explanation": "语义：“好吃”形容食物的味道，不用来形容人。"}, {"text": "便宜", "is_correct": false, "explanation": "语义：“便宜”指价钱低，不能用来形容人。"}, {"text": "寒冷", "is_correct": false, "explanation": "搭配：“寒冷”形容天气或温度，不用来描述人的身体状况。"}], "explanations": {"健康": "健康：身体没有病，这里指医生说我身体很好。", "好吃": "语义：“好吃”形容食物的味道，不用来形容人。", "便宜": "语义：“便宜”指价钱低，不能用来形容人。", "寒冷": "搭配：“寒冷”形容天气或温度，不用来描述人的身体状况。"}, "sentence_index": 6, "correct_answer": "健康"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的数学成绩很健康。", "explanation": "这里应该用〈优秀〉。健康不用来评价成绩的好坏。"}, {"text": "我的手机很健康。", "explanation": "这里应该用〈好用〉。健康指人或动植物的身体没有病，不用于器物；说手机状态正常要用〈好用〉。"}, {"text": "这个房间很健康。", "explanation": "这里应该用〈干净〉。健康不用来形容房间的整洁程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20470, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈的身体没健康。", "corrected_sentence": "妈妈的身体不健康。", "error_description": "否定词错误：形容词“健康”表示状态，否定时要用“不”，说“不健康”，不能说“没健康”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20470, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天运动，变很健康。", "corrected_sentence": "他每天运动，变得很健康。", "error_description": "补语标志错误：“变”之后缺少“得”，应说“变得很健康”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
