INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20472, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "不是，表示差得很远。", "primary_collocate": null, "pronunciation": "yuǎn fēi", "ipa": "ɥɛn˨˩˦ fei˥", "syllable_count": 2, "sentences": [{"text": "他的汉语水平远非完美。", "target_word": "远非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事远非一天能做完。", "target_word": "远非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的能力远非你说的那么强。", "target_word": "远非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钱远非生活的全部。", "target_word": "远非", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这远非一个简单的问题。", "target_word": "远非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今年的收成远非去年可比。", "target_word": "远非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "成绩好远非成功的唯一标准。", "target_word": "远非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市的夜晚远非乡下那样安静。", "target_word": "远非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的故事远非这几句话能讲完。", "target_word": "远非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买一张票远非旅行的全部。", "target_word": "远非", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "副词，书面，否定判断，表示与某种情况差得很远", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f86388a0-d51c-4e9d-b000-ecf475b0afc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20472, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "远非", "is_correct": true, "explanation": "正确。“远非”表示差得很远，与“完美”的否定语境相符。"}, {"text": "稍微", "is_correct": false, "explanation": "搭配：“完美”是绝对概念，不能用“稍微”修饰，“稍微完美”不通。"}, {"text": "有点", "is_correct": false, "explanation": "搭配：“有点”表示程度轻微，不能与“完美”搭配。"}, {"text": "略", "is_correct": false, "explanation": "语义：“略”表示轻微的程度，与“完美”的绝对意义相冲突。"}], "explanations": {"远非": "正确。“远非”表示差得很远，与“完美”的否定语境相符。", "稍微": "搭配：“完美”是绝对概念，不能用“稍微”修饰，“稍微完美”不通。", "有点": "搭配：“有点”表示程度轻微，不能与“完美”搭配。", "略": "语义：“略”表示轻微的程度，与“完美”的绝对意义相冲突。"}, "sentence_index": 0, "correct_answer": "远非"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我远非懂英语，还懂法语。", "explanation": "这里用错了词义。远非表示程度相差很大，不表示递进，“远非懂英语”与后文“还懂法语”前后矛盾，应说〈不仅〉。"}, {"text": "我家远非学校，所以我每天坐车上学。", "explanation": "这里用错了词义。远非表示程度相差很大，不表示空间距离，这里应该用〈远离〉。"}, {"text": "他的口语远非完美，所以每次比赛他都是第一名。", "explanation": "这里前后矛盾。“远非完美”表示口语还差得很远，与“每次比赛他都是第一名”的因果不合，应说〈非常好〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e9dc6a-731f-4989-9f53-dfbadddc86f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20472, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "远非", "is_correct": true, "explanation": "正确。“远非”表示差得很远，与后文“成功的唯一标准”的否定语境相符。"}, {"text": "非常", "is_correct": false, "explanation": "语法：“非常”是程度副词，不能直接放在名词短语“成功的唯一标准”前。"}, {"text": "只是", "is_correct": false, "explanation": "搭配：“只是”表示仅仅如此，与“唯一标准”的强调意义搭配不通。"}, {"text": "不过", "is_correct": false, "explanation": "语义：“不过”表示仅仅是，肯定了“成绩好”的作用，与句子结论相反。"}], "explanations": {"远非": "正确。“远非”表示差得很远，与后文“成功的唯一标准”的否定语境相符。", "非常": "语法：“非常”是程度副词，不能直接放在名词短语“成功的唯一标准”前。", "只是": "搭配：“只是”表示仅仅如此，与“唯一标准”的强调意义搭配不通。", "不过": "语义：“不过”表示仅仅是，肯定了“成绩好”的作用，与句子结论相反。"}, "sentence_index": 6, "correct_answer": "远非"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张票远非贵，我每次都买不起。", "explanation": "这里前后矛盾。“远非贵”表示不贵，与“我每次都买不起”矛盾，应说〈非常贵〉。"}, {"text": "我家远非机场，所以我们提前一天出发。", "explanation": "这里用错了词义。远非表示程度相差很大，不表示空间距离，这里应该用〈远离〉。"}, {"text": "他远非富有，所以每天都买名牌衣服。", "explanation": "这里前后矛盾。“远非富有”表示不富有，与“所以每天都买名牌衣服”的因果不合，应说〈非常富有〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e9dc6a-731f-4989-9f53-dfbadddc86f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20472, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事很远非简单。", "corrected_sentence": "这件事远非简单。", "error_description": "“远非”本身已表示程度，前面不能再加“很”，应说“远非简单”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e9dc6a-731f-4989-9f53-dfbadddc86f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20472, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次考试远非很容易，我复习了很久。", "corrected_sentence": "这次考试远非容易，我复习了很久。", "error_description": "“远非”本身已表示程度，后面的形容词前不能再加“很”，应说“远非容易”，不能说“远非很容易”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e9dc6a-731f-4989-9f53-dfbadddc86f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
