INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20474, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不冷也不热，刚刚好。", "primary_collocate": null, "pronunciation": "wēn", "ipa": "wən˥", "syllable_count": 1, "sentences": [{"text": "这杯牛奶不冷也不热，刚好是温的。", "target_word": "温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水太烫了，加点冷水，让它温一点。", "target_word": "温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你喝温的还是热的？", "target_word": "温", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "宝宝喝的奶要温一点，不能太烫。", "target_word": "温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天只想喝一杯温的蜂蜜水。", "target_word": "温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这碗汤放了一会儿，现在刚好温，可以喝了。", "target_word": "温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，吃药要用温的水，不要用冰水。", "target_word": "温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗脸的水不能太冷，温的最舒服。", "target_word": "温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上起来先喝一杯温的，对胃好。", "target_word": "温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡放了很久，现在是温的。", "target_word": "温", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "溫", "label": "繁体"}, {"form": "温温", "label": "重叠"}, {"form": "温水", "label": "复合"}], "register": "口语", "sense_fingerprint": "形容水、奶、汤等温度适中，不冷不热", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c5811c7-5286-4a58-bed4-0f21f210b18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20474, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "温", "is_correct": true, "explanation": "温（wēn，第一声）：不冷也不热，与听到的读音一致。"}, {"text": "闻", "is_correct": false, "explanation": "wén（第二声）与 wēn（第一声）声调不同，意思是闻到、听到。"}, {"text": "问", "is_correct": false, "explanation": "wèn（第四声）与 wēn（第一声）声调不同，意思是询问。"}, {"text": "稳", "is_correct": false, "explanation": "wěn（第三声）与 wēn（第一声）声调不同，意思是稳定。"}, {"text": "文", "is_correct": false, "explanation": "wén（第二声）与 wēn（第一声）声调不同，意思是文字。"}], "explanations": {"温": "温（wēn，第一声）：不冷也不热，与听到的读音一致。", "闻": "wén（第二声）与 wēn（第一声）声调不同，意思是闻到、听到。", "问": "wèn（第四声）与 wēn（第一声）声调不同，意思是询问。", "稳": "wěn（第三声）与 wēn（第一声）声调不同，意思是稳定。", "文": "wén（第二声）与 wēn（第一声）声调不同，意思是文字。"}, "sentence_index": null, "correct_answer": "温"}, "level_3": {"options": [{"text": "温", "is_correct": true, "explanation": "正确：「不冷也不热，刚好是温的」与“温”的温度适中义相符。"}, {"text": "冷", "is_correct": false, "explanation": "语义：「刚好是冷的」与前半句「不冷」矛盾。"}, {"text": "热", "is_correct": false, "explanation": "语义：「刚好是热的」与前半句「不热」矛盾。"}, {"text": "烫", "is_correct": false, "explanation": "搭配：「烫」多形容温度很高的食物，与「刚好」这种适中的说法不搭。"}], "explanations": {"温": "正确：「不冷也不热，刚好是温的」与“温”的温度适中义相符。", "冷": "语义：「刚好是冷的」与前半句「不冷」矛盾。", "热": "语义：「刚好是热的」与前半句「不热」矛盾。", "烫": "搭配：「烫」多形容温度很高的食物，与「刚好」这种适中的说法不搭。"}, "sentence_index": 0, "correct_answer": "温"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "屋里生了火，所以很温。", "explanation": "这里应该用〈暖和〉。温多用于水、奶、饮料等液体的温度，形容屋里的暖意一般说暖和。"}, {"text": "他发烧了，额头很温。", "explanation": "这里应该用〈发热〉。发烧时额头温度很高，应说发热。温指温度适中，不指高温。"}, {"text": "今天很温，我们去游泳吧。", "explanation": "这里应该用〈暖和〉。温多指水、奶等液体或食物的温度，形容天气的暖意一般说暖和。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef8669af-1187-499f-b907-8925a3beaf1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20474, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "温", "is_correct": true, "explanation": "温（wēn，第一声）：不冷也不热，与听到的读音一致。"}, {"text": "吻", "is_correct": false, "explanation": "wěn（第三声）与 wēn（第一声）声调不同，意思是亲吻。"}, {"text": "蚊", "is_correct": false, "explanation": "wén（第二声）与 wēn（第一声）声调不同，意思是蚊子。"}, {"text": "纹", "is_correct": false, "explanation": "wén（第二声）与 wēn（第一声）声调不同，意思是花纹、纹路。"}], "explanations": {"温": "温（wēn，第一声）：不冷也不热，与听到的读音一致。", "吻": "wěn（第三声）与 wēn（第一声）声调不同，意思是亲吻。", "蚊": "wén（第二声）与 wēn（第一声）声调不同，意思是蚊子。", "纹": "wén（第二声）与 wēn（第一声）声调不同，意思是花纹、纹路。"}, "sentence_index": null, "correct_answer": "温"}, "level_3": {"options": [{"text": "温", "is_correct": true, "explanation": "正确：吃药用温水，与「不要用冰水」的医嘱相符。"}, {"text": "烫", "is_correct": false, "explanation": "搭配：服药的水一般不说「烫的水」，医嘱要的是温水。"}, {"text": "滚烫", "is_correct": false, "explanation": "语义：「滚烫」指温度极高，与医嘱中要用温水的意思相反。"}, {"text": "冰冷", "is_correct": false, "explanation": "语义：「冰冷」与后半句「不要用冰水」的意思直接矛盾。"}], "explanations": {"温": "正确：吃药用温水，与「不要用冰水」的医嘱相符。", "烫": "搭配：服药的水一般不说「烫的水」，医嘱要的是温水。", "滚烫": "语义：「滚烫」指温度极高，与医嘱中要用温水的意思相反。", "冰冷": "语义：「冰冷」与后半句「不要用冰水」的意思直接矛盾。"}, "sentence_index": 6, "correct_answer": "温"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冰箱里的西瓜很温。", "explanation": "这里应该用〈凉〉。温指温度适中，冰箱里的西瓜应说凉。"}, {"text": "这碗面刚煮好，很温。", "explanation": "这里应该用〈烫〉。刚煮好的面温度很高，形容它不能用温。"}, {"text": "这块冰很温。", "explanation": "这里应该用〈冰冷〉。冰的温度很低，温指温度适中，不能用来形容冰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef8669af-1187-499f-b907-8925a3beaf1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20474, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "现在的牛奶是温，可以喝了。", "corrected_sentence": "现在的牛奶是温的，可以喝了。", "error_description": "“温”作谓语时，“是”后面要加“的”，应说“是温的”。漏掉“的”就不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef8669af-1187-499f-b907-8925a3beaf1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20474, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想喝一杯水温。", "corrected_sentence": "我想喝一杯温水。", "error_description": "“温水”是固定词序，“水温”指水的温度，不能说「一杯水温」。应说「一杯温水」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef8669af-1187-499f-b907-8925a3beaf1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
