INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20482, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "每天都有的、平常的。", "primary_collocate": null, "pronunciation": "rì cháng", "ipa": "ɻ̩˥˩ ʈʂʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他的日常工作是照顾小孩。", "target_word": "日常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很喜欢这种安静的日常生活。", "target_word": "日常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机已经是我们日常生活的一部分。", "target_word": "日常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写日记是她的日常习惯。", "target_word": "日常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说日常饮食要少吃盐。", "target_word": "日常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些日常用品超市里都有。", "target_word": "日常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学汉语不难，日常对话我已经能听懂了。", "target_word": "日常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天做饭、洗衣服，日常家务都是他做。", "target_word": "日常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们一些日常用语。", "target_word": "日常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用照片记录日常生活。", "target_word": "日常", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "日常生活", "label": "复合"}, {"form": "日常用品", "label": "复合"}], "register": "中性", "sense_fingerprint": "形容每天都有的、平常的事情或生活", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bacc239c-df87-4c0c-a87d-ec7f9978f1b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20482, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "日常", "is_correct": true, "explanation": "正确：“日常”指每天都有的、平常的，即目标义项。"}, {"text": "热肠", "is_correct": false, "explanation": "最小对立：rè 与 rì 仅韵母不同（e/i），声调相同；“热肠”指热心肠，不是同义词。"}, {"text": "日场", "is_correct": false, "explanation": "声调混淆：rìchǎng 与 rìcháng 仅第二字声调不同；“日场”指白天的演出场次。"}, {"text": "异常", "is_correct": false, "explanation": "最小对立：yì 与 rì 仅声母不同（零声母与 r），声调相同；“异常”指不正常。"}], "explanations": {"日常": "正确：“日常”指每天都有的、平常的，即目标义项。", "热肠": "最小对立：rè 与 rì 仅韵母不同（e/i），声调相同；“热肠”指热心肠，不是同义词。", "日场": "声调混淆：rìchǎng 与 rìcháng 仅第二字声调不同；“日场”指白天的演出场次。", "异常": "最小对立：yì 与 rì 仅声母不同（零声母与 r），声调相同；“异常”指不正常。"}, "sentence_index": null, "correct_answer": "日常"}, "level_3": {"options": [{"text": "日常", "is_correct": true, "explanation": "正确：“日常”修饰“工作”，表示每天都做的工作，符合语境。"}, {"text": "圆形", "is_correct": false, "explanation": "语义：“圆形”说的是形状，不能用来修饰“工作”。"}, {"text": "高大", "is_correct": false, "explanation": "语义：“高大”形容人或物的身材，不能修饰“工作”。"}, {"text": "雪白", "is_correct": false, "explanation": "搭配：“雪白”形容颜色，不能修饰“工作”。"}], "explanations": {"日常": "正确：“日常”修饰“工作”，表示每天都做的工作，符合语境。", "圆形": "语义：“圆形”说的是形状，不能用来修饰“工作”。", "高大": "语义：“高大”形容人或物的身材，不能修饰“工作”。", "雪白": "搭配：“雪白”形容颜色，不能修饰“工作”。"}, "sentence_index": 0, "correct_answer": "日常"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他日常去图书馆。", "explanation": "这里应该用〈经常〉。“日常”是形容词，修饰名词，不能当副词表示频率。"}, {"text": "这次去海边的旅行是我的日常。", "explanation": "这里误把〈日常〉当作“经历”的意思；“日常”指每天都要做的事，与“这次”的一次性旅行矛盾，应说〈经历〉。"}, {"text": "我买了一瓶日常。", "explanation": "这里应该用〈日常用品〉。“日常”是形容词，不能单独作名词使用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20482, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日常", "is_correct": true, "explanation": "正确：“日常对话”指日常生活中的交流，符合“学汉语不难”的语境。"}, {"text": "遥远", "is_correct": false, "explanation": "语义：“遥远”形容距离或时间，与“日常对话”的语境不符。"}, {"text": "滚烫", "is_correct": false, "explanation": "搭配：“滚烫”形容温度，不能修饰“对话”。"}, {"text": "光滑", "is_correct": false, "explanation": "搭配：“光滑”形容物体表面，不能修饰“对话”。"}], "explanations": {"日常": "正确：“日常对话”指日常生活中的交流，符合“学汉语不难”的语境。", "遥远": "语义：“遥远”形容距离或时间，与“日常对话”的语境不符。", "滚烫": "搭配：“滚烫”形容温度，不能修饰“对话”。", "光滑": "搭配：“光滑”形容物体表面，不能修饰“对话”。"}, "sentence_index": 6, "correct_answer": "日常"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的晚会非常日常。", "explanation": "这里应该用〈热闹〉或〈普通〉。“日常”只作定语表示每天都有的，不能受“非常”修饰作谓语。"}, {"text": "这份合同的日常写错了。", "explanation": "这里应该用〈日期〉。“日常”指每天都要做的事，合同上的时间要用“日期”。"}, {"text": "我日常去超市买东西。", "explanation": "这里应该用〈常常〉。“日常”是形容词，不能当副词表示频率。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20482, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很重视日常得锻炼。", "corrected_sentence": "他很重视日常锻炼。", "error_description": "结构助词误用：“日常”作定语修饰“锻炼”时不能加“得”，应说“日常锻炼”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20482, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了几双日常用品。", "corrected_sentence": "我买了几件日常用品。", "error_description": "量词错误：“日常用品”用量词“件”，“双”只用于成对的东西，不能用于“用品”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20484, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "凝华", "is_correct": true, "explanation": "凝华：物质由气态直接变为固态，与升华的方向相反，两者互为反义。"}, {"text": "融化", "is_correct": false, "explanation": "融化：固态变为液态，与升华所指的变化不构成反义。"}, {"text": "蒸发", "is_correct": false, "explanation": "蒸发：液态变为气态，起点与升华不同，不是反义关系。"}, {"text": "冻结", "is_correct": false, "explanation": "冻结：液态变为固态，与升华不构成反义。"}], "correct_answer": "凝华", "explanations": {"凝华": "凝华：物质由气态直接变为固态，与升华的方向相反，两者互为反义。", "融化": "融化：固态变为液态，与升华所指的变化不构成反义。", "蒸发": "蒸发：液态变为气态，起点与升华不同，不是反义关系。", "冻结": "冻结：液态变为固态，与升华不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20484, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "凝华", "is_correct": true, "explanation": "凝华：物质由气态直接变为固态，与升华的方向相反，两者互为反义。"}, {"text": "烧焦", "is_correct": false, "explanation": "烧焦：被火烤成焦黑，与升华所指的变化无关。"}, {"text": "腐蚀", "is_correct": false, "explanation": "腐蚀：物质被化学作用逐渐损坏，与升华不构成反义。"}, {"text": "破碎", "is_correct": false, "explanation": "破碎：物体被打成碎块，与升华所指的变化无关。"}], "correct_answer": "凝华", "explanations": {"凝华": "凝华：物质由气态直接变为固态，与升华的方向相反，两者互为反义。", "烧焦": "烧焦：被火烤成焦黑，与升华所指的变化无关。", "腐蚀": "腐蚀：物质被化学作用逐渐损坏，与升华不构成反义。", "破碎": "破碎：物体被打成碎块，与升华所指的变化无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20484, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西从固体直接变成气体，中间不经过液体。", "primary_collocate": null, "pronunciation": "shēng huá", "ipa": "ʂɤŋ˥ xwa˧˥", "syllable_count": 2, "sentences": [{"text": "干冰会升华。", "target_word": "升华", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "冰在很冷的天气里会直接升华。", "target_word": "升华", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "干冰放在空气里，很快就升华成气体。", "target_word": "升华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "樟脑丸会慢慢升华，所以味道很大。", "target_word": "升华", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "碘受热以后会直接升华成紫色的气体。", "target_word": "升华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪没有化成水，是直接升华到空气里了。", "target_word": "升华", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，衣服上的冰也会慢慢升华。", "target_word": "升华", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师做了一个实验，让固体升华。", "target_word": "升华", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "干冰升华的时候，周围的温度很低。", "target_word": "升华", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "升华不会经过水，固体直接变成气体。", "target_word": "升华", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "升华了", "label": "了体"}, {"form": "升华过", "label": "过体"}, {"form": "升華", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词（物理）：物质由固态直接变为气态，如干冰、樟脑丸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75b6c6b-1a83-43ea-bf8d-cebf12c05e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20484, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "升华", "is_correct": true, "explanation": "升华：固体直接变成气体，符合“干冰会升华”的说法。"}, {"text": "生锈", "is_correct": false, "explanation": "语义：生锈指金属与氧气等发生氧化，干冰是固态二氧化碳，不会生锈。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：发芽指种子或植物长出新芽，干冰不是植物，不能发芽。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：游泳的主体须是人或动物，不能用于干冰。"}], "explanations": {"升华": "升华：固体直接变成气体，符合“干冰会升华”的说法。", "生锈": "语义：生锈指金属与氧气等发生氧化，干冰是固态二氧化碳，不会生锈。", "发芽": "语义：发芽指种子或植物长出新芽，干冰不是植物，不能发芽。", "游泳": "搭配：游泳的主体须是人或动物，不能用于干冰。"}, "sentence_index": 0, "correct_answer": "升华"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏天，湖水会慢慢升华到空气里。", "explanation": "这里应该用〈蒸发〉。升华指固体直接变成气体；湖水是液体，变成气体要用蒸发。"}, {"text": "物价每天都在升华。", "explanation": "这里应该用〈上升〉。升华只指固体直接变成气体，不能用于物价的变化。"}, {"text": "铁块放在火里，很快就升华了。", "explanation": "这里应该用〈熔化〉。铁受热变成液体要用熔化；升华指固体直接变成气体，不经过液态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20484, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "升华", "is_correct": true, "explanation": "升华：固体直接变成气体，符合“冰慢慢升华”的语境。"}, {"text": "腐烂", "is_correct": false, "explanation": "语义：腐烂指有机物变质分解，冰不会腐烂。"}, {"text": "呼吸", "is_correct": false, "explanation": "语义：呼吸是生物的生理活动，冰不会呼吸。"}, {"text": "结婚", "is_correct": false, "explanation": "搭配：结婚的主体只能是人，不能用于冰。"}], "explanations": {"升华": "升华：固体直接变成气体，符合“冰慢慢升华”的语境。", "腐烂": "语义：腐烂指有机物变质分解，冰不会腐烂。", "呼吸": "语义：呼吸是生物的生理活动，冰不会呼吸。", "结婚": "搭配：结婚的主体只能是人，不能用于冰。"}, "sentence_index": 6, "correct_answer": "升华"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "水烧开以后会慢慢升华成蒸汽。", "explanation": "这里应该用〈汽化〉。水是液体，变成气体要用汽化；升华只指固体直接变成气体。"}, {"text": "白糖放进热水里，很快就升华了。", "explanation": "这里应该用〈溶解〉。白糖放进水里是溶解，不是固体直接变成气体。"}, {"text": "木头在火里很快升华。", "explanation": "这里应该用〈燃烧〉。木头在火里燃烧是化学变化，不是固体直接变成气体的升华。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20484, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "实验室里的干冰很快就升华了气体。", "corrected_sentence": "实验室里的干冰很快就升华成了气体。", "error_description": "错误形式“升华了气体”：升华是不及物动词，不能直接带宾语。表示变成某物时要用“升华成了……”，应为“升华成了气体”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20484, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冬天，窗户上的霜也会慢慢升华成水。", "corrected_sentence": "冬天，窗户上的霜也会慢慢升华成水蒸气。", "error_description": "错误形式“升华成水”：升华是固体直接变为气体，不经过液态。结果应是气体，应改为“升华成水蒸气”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
